window.__GM_I18N={"Meridyen Gayrimenkul · Hizmetler":{"en":"Meridyen Gayrimenkul · Services","ru":"Meridyen Gayrimenkul · Услуги","zh":"Meridyen Gayrimenkul · 服务","ar":"Meridyen Gayrimenkul · الخدمات"},"Fikirden tapuya,":{"en":"From idea to title deed,","ru":"От идеи до тапу,","zh":"从想法到房产证，","ar":"من الفكرة إلى سند الملكية،"},"veriyle":{"en":"with data","ru":"на основе данных","zh":"以数据","ar":"بالبيانات"},"uçtan uca emlak":{"en":"end-to-end real estate","ru":"недвижимость от и до","zh":"端到端的房产服务","ar":"خدمات عقارية من البداية إلى النهاية"},"Alım-satımdan kiralamaya, değerlemeden yatırım danışmanlığına ve miras / intikal işlemlerine kadar; gayrimenkulünüzün her aşamasında bölge verisiyle konuşan bir yerel emlak ekibi.":{"en":"From buying and selling to leasing, from valuation to investment advisory and inheritance / transfer procedures; a local real estate team that speaks with regional data at every stage of your property journey.","ru":"От купли-продажи до аренды, от оценки до инвестиционного консалтинга и наследственных операций (miras / intikal); местная команда по недвижимости, которая на каждом этапе работы с вашей недвижимостью опирается на данные по региону.","zh":"从买卖到租赁，从估价到投资顾问，再到遗产/继承过户；在您房产的每一个阶段，都有一支以区域数据说话的本地房产团队。","ar":"من البيع والشراء إلى التأجير، ومن التقييم إلى الاستشارات الاستثمارية وصولاً إلى معاملات الميراث / الانتقال؛ فريق عقاري محلي يتحدث بلغة بيانات المنطقة في كل مرحلة من مراحل عقاركم."},"Tüm Hizmetler":{"en":"All Services","ru":"Все услуги","zh":"全部服务","ar":"جميع الخدمات"},"Uzmanlık alanı":{"en":"Area of expertise","ru":"Область специализации","zh":"专业领域","ar":"مجال تخصص"},"Adımlı miras rehberi":{"en":"Step-by-step inheritance guide","ru":"Пошаговое руководство по наследству","zh":"分步继承指南","ar":"دليل الميراث خطوة بخطوة"},"Bölge verisi odaklı":{"en":"Regional-data driven","ru":"На основе данных по региону","zh":"以区域数据为核心","ar":"قائم على بيانات المنطقة"},"Hizmet Haritası":{"en":"Service Map","ru":"Карта услуг","zh":"服务地图","ar":"خريطة الخدمات"},"Gayrimenkulün her ihtiyacı için tek bir adres":{"en":"A single address for every real estate need","ru":"Единый адрес для всех потребностей в недвижимости","zh":"满足房产各类需求的一站式选择","ar":"عنوان واحد لكل احتياجات العقار"},"14 uzmanlık alanı ve özel miras / intikal masası. İhtiyacınız olan başlığa geçin, her biri için sürecin nasıl işlediğini adım adım anlatıyoruz.":{"en":"14 areas of expertise and a dedicated inheritance / transfer desk. Jump to the topic you need; for each one we explain step by step how the process works.","ru":"14 областей специализации и отдельная служба по вопросам наследства (miras / intikal). Перейдите к нужному разделу — для каждого мы шаг за шагом объясняем, как устроен процесс.","zh":"14 个专业领域及专属遗产/继承服务台。前往您需要的板块，我们为每一项逐步说明流程如何运作。","ar":"14 مجال تخصص إضافةً إلى مكتب خاص للميراث / الانتقال. انتقلوا إلى العنوان الذي تحتاجونه، فنحن نشرح لكم آلية سير كل عملية خطوة بخطوة."},"Konut Alım & Satım Danışmanlığı":{"en":"Residential Buying & Selling Advisory","ru":"Консультации по купле-продаже жилья","zh":"住宅买卖顾问","ar":"استشارات بيع وشراء المساكن"},"Doğru fiyat, doğru zaman ve doğru alıcıyla konutunuzu güvenle alıp satmanızı sağlayan uçtan uca danışmanlık.":{"en":"End-to-end advisory that lets you buy and sell your home with confidence, at the right price, at the right time and with the right buyer.","ru":"Комплексный консалтинг, позволяющий уверенно купить или продать жильё по правильной цене, в правильное время и с правильным покупателем.","zh":"端到端顾问服务，助您以正确的价格、正确的时机和正确的买家安心买卖住宅。","ar":"استشارات متكاملة تتيح لكم شراء وبيع مسكنكم بثقة، بالسعر المناسب والوقت المناسب والمشتري المناسب."},"İncele":{"en":"Explore","ru":"Подробнее","zh":"查看","ar":"استعراض"},"Kiralama & Kira Garantili Yönetim":{"en":"Leasing & Rent-Guaranteed Management","ru":"Аренда и управление с гарантией арендной платы","zh":"租赁与租金保障管理","ar":"التأجير والإدارة بضمان الإيجار"},"Kiracı bulmadan tahliyeye, kira takibinden garantili gelire kadar mülkünüzün tüm kira sürecini biz yönetelim.":{"en":"From finding a tenant to eviction, from rent tracking to guaranteed income, let us manage your property's entire rental process.","ru":"От поиска арендатора до выселения, от контроля платежей до гарантированного дохода — мы управляем всем арендным процессом вашей недвижимости.","zh":"从寻找租客到清退，从租金跟踪到保障收益，您房产的整个租赁流程都由我们管理。","ar":"من إيجاد المستأجر إلى الإخلاء، ومن متابعة الإيجار إلى الدخل المضمون؛ دعونا ندير كامل عملية تأجير عقاركم."},"Ticari & Ofis Gayrimenkul Danışmanlığı":{"en":"Commercial & Office Real Estate Advisory","ru":"Консультации по коммерческой и офисной недвижимости","zh":"商业与办公房产顾问","ar":"استشارات العقارات التجارية والمكتبية"},"Dükkan, ofis, plaza ve depo yatırımlarında lokasyon zekası ve doğru kiracı eşleştirmesiyle getiriyi maksimize edin.":{"en":"Maximize your return on shop, office, plaza and warehouse investments with location intelligence and the right tenant matching.","ru":"Максимизируйте доходность инвестиций в магазины, офисы, бизнес-центры и склады благодаря аналитике локаций и подбору правильного арендатора.","zh":"在商铺、办公室、写字楼和仓库投资中，以区位智慧和精准的租客匹配实现收益最大化。","ar":"عظّموا العائد في استثمارات المحال والمكاتب والأبراج والمستودعات عبر ذكاء الموقع والمطابقة الصحيحة للمستأجر."},"Arsa & Arazi Danışmanlığı":{"en":"Plot & Land Advisory","ru":"Консультации по земельным участкам","zh":"地块与土地顾问","ar":"استشارات الأراضي والقطع"},"İmar, tapu ve zemin risklerini önceden çözerek arsa ve arazide gerçek yatırım potansiyelini ortaya çıkarıyoruz.":{"en":"By resolving zoning, title deed and ground risks in advance, we reveal the true investment potential of plots and land.","ru":"Заранее устраняя риски, связанные с зонированием, тапу и грунтом, мы раскрываем реальный инвестиционный потенциал земельных участков.","zh":"提前化解规划、房产证和地质风险，发掘地块与土地的真实投资潜力。","ar":"نكشف الإمكانات الاستثمارية الحقيقية في الأراضي والقطع من خلال حل مخاطر التنظيم العمراني وسند الملكية والتربة مسبقاً."},"Değerleme & Ön Ekspertiz":{"en":"Valuation & Preliminary Appraisal","ru":"Оценка и предварительная экспертиза","zh":"估价与初步估价","ar":"التقييم والتقييم المبدئي"},"Mülkünüzün gerçek piyasa değerini emsal verilerle belirliyor, resmi işlemler için SPK lisanslı ekspertize yönlendiriyoruz.":{"en":"We determine your property's true market value with comparable data and, for official transactions, direct you to SPK-licensed appraisal.","ru":"Определяем реальную рыночную стоимость вашей недвижимости на основе данных о сопоставимых сделках и для официальных операций направляем вас к оценке, имеющей лицензию SPK.","zh":"以可比数据确定您房产的真实市场价值，并为正式手续将您转介至持 SPK 牌照的估价机构。","ar":"نحدد القيمة السوقية الحقيقية لعقاركم ببيانات مماثلة، ونحيلكم إلى جهة تقييم مرخّصة من SPK للمعاملات الرسمية."},"Yatırım Danışmanlığı & Getiri Analizi":{"en":"Investment Advisory & Return Analysis","ru":"Инвестиционный консалтинг и анализ доходности","zh":"投资顾问与收益分析","ar":"الاستشارات الاستثمارية وتحليل العائد"},"Kira çarpanı, net ROI ve amortisman süresini hesaplayarak duygusal değil veri odaklı yatırım kararları aldırıyoruz.":{"en":"By calculating the rent multiplier, net ROI and payback period, we help you make data-driven rather than emotional investment decisions.","ru":"Рассчитывая мультипликатор аренды, чистый ROI и срок окупаемости, мы помогаем принимать инвестиционные решения на основе данных, а не эмоций.","zh":"通过计算租金倍数、净 ROI 和回本周期，帮助您做出以数据而非情绪为依据的投资决策。","ar":"نجعلكم تتخذون قرارات استثمارية قائمة على البيانات لا على العاطفة، عبر حساب مضاعف الإيجار وصافي ROI ومدة الاسترداد."},"Bölge & Fiyat Endeksi Analizi":{"en":"Region & Price Index Analysis","ru":"Анализ региона и ценового индекса","zh":"区域与价格指数分析","ar":"تحليل المنطقة ومؤشر الأسعار"},"TCMB konut fiyat endeksi ve semt bazlı metrekare verileriyle hangi bölgenin ne zaman değerlendiğini gösteriyoruz.":{"en":"With the TCMB housing price index and neighborhood-level per-square-meter data, we show which region appreciates and when.","ru":"С помощью индекса цен на жильё TCMB и данных о цене за квадратный метр по районам мы показываем, какой район и когда растёт в цене.","zh":"以 TCMB 住房价格指数和按街区的每平方米数据，向您展示哪个区域在何时升值。","ar":"نُظهر لكم أي منطقة ترتفع قيمتها ومتى، عبر مؤشر أسعار المساكن الصادر عن TCMB وبيانات المتر المربع على مستوى الأحياء."},"Tapu & Hukuki Süreç Danışmanlığı":{"en":"Title Deed & Legal Process Advisory","ru":"Консультации по тапу и юридическим процедурам","zh":"房产证与法律流程顾问","ar":"استشارات سند الملكية والإجراءات القانونية"},"Web Tapu başvurusundan harç ödemesine ve devir randevusuna kadar tüm tapu sürecini hatasız yönetiyoruz.":{"en":"From the Web Tapu application to fee payment and the transfer appointment, we manage the entire title deed process flawlessly.","ru":"От подачи заявки через Web Tapu до уплаты пошлины и записи на переоформление — мы безошибочно ведём весь процесс оформления тапу.","zh":"从 Web Tapu 申请到税费缴纳再到过户预约，全程无误地管理整个房产证流程。","ar":"ندير كامل عملية سند الملكية دون أخطاء، من طلب Web Tapu إلى دفع الرسوم وموعد النقل."},"Konut Kredisi & Ödeme Planı Danışmanlığı":{"en":"Mortgage & Payment Plan Advisory","ru":"Консультации по ипотеке и плану платежей","zh":"住房贷款与还款计划顾问","ar":"استشارات القرض السكني وخطة السداد"},"Ekspertiz, faiz ve ödeme planını karşılaştırarak size en uygun konut kredisi yapısını kurgulayıp süreci hızlandırıyoruz.":{"en":"By comparing appraisal, interest and payment plans, we structure the most suitable mortgage for you and speed up the process.","ru":"Сравнивая оценку, процентные ставки и план платежей, мы выстраиваем наиболее подходящую для вас структуру ипотеки и ускоряем процесс.","zh":"通过比较估价、利率和还款计划，为您搭建最合适的住房贷款结构并加快流程。","ar":"نصمم لكم أنسب هيكل قرض سكني ونسرّع العملية، عبر مقارنة التقييم والفائدة وخطة السداد."},"Portföy Yönetimi (Mülk Sahipleri İçin)":{"en":"Portfolio Management (For Property Owners)","ru":"Управление портфелем (для собственников недвижимости)","zh":"投资组合管理（面向业主）","ar":"إدارة المحفظة (لمالكي العقارات)"},"Birden fazla mülkün kira, bakım, vergi ve değer takibini tek elden yöneterek portföyünüzün getirisini optimize ediyoruz.":{"en":"By managing the rent, maintenance, tax and value tracking of multiple properties from a single point, we optimize your portfolio's return.","ru":"Управляя из единого центра арендой, обслуживанием, налогами и стоимостью нескольких объектов, мы оптимизируем доходность вашего портфеля.","zh":"一站式管理多套房产的租金、维护、税费和价值跟踪，优化您投资组合的收益。","ar":"نحسّن عائد محفظتكم عبر إدارة إيجار وصيانة وضرائب ومتابعة قيمة عدة عقارات من مصدر واحد."},"Home Staging & Satışa Hazırlık":{"en":"Home Staging & Sale Preparation","ru":"Home staging и подготовка к продаже","zh":"Home Staging 与售前准备","ar":"التهيئة للعرض (Home Staging) والإعداد للبيع"},"Profesyonel sunum, fotoğraf ve düzenlemeyle mülkünüzü daha hızlı ve daha yüksek fiyata satılır hale getiriyoruz.":{"en":"With professional presentation, photography and styling, we make your property sell faster and at a higher price.","ru":"С помощью профессиональной презентации, фотографий и оформления мы делаем вашу недвижимость продаваемой быстрее и по более высокой цене.","zh":"通过专业的呈现、摄影和布置，让您的房产更快、以更高的价格售出。","ar":"نجعل عقاركم قابلاً للبيع بسرعة أكبر وسعر أعلى عبر العرض الاحترافي والتصوير والتنسيق."},"Kentsel Dönüşüm & Yeni Proje Danışmanlığı":{"en":"Urban Regeneration & New Project Advisory","ru":"Консультации по городской реновации и новым проектам","zh":"城市更新与新项目顾问","ar":"استشارات التحول الحضري والمشاريع الجديدة"},"Riskli yapı tespitinden hak sahipliğine ve Yarısı Bizden desteklerine kadar dönüşüm sürecinizde yanınızdayız.":{"en":"From risky-building assessment to rights-holder status and Yarısı Bizden support, we stand by you throughout your regeneration process.","ru":"От признания здания аварийным до определения прав собственности и субсидий Yarısı Bizden — мы рядом с вами на всём пути реновации.","zh":"从危房鉴定到权属确认，再到 Yarısı Bizden 补助，我们在您的更新过程中全程相伴。","ar":"نقف إلى جانبكم في عملية التحول، من تحديد المبنى المعرّض للخطر إلى إثبات الاستحقاق ودعم Yarısı Bizden."},"Yabancıya Satış & Oturma İzni Gayrimenkulü":{"en":"Sales to Foreigners & Residence-Permit Real Estate","ru":"Продажа иностранцам и недвижимость для вида на жительство","zh":"向外国人销售与居留许可房产","ar":"البيع للأجانب وعقارات تصريح الإقامة"},"Yabancı yatırımcılara döviz bozdurma belgesinden vatandaşlık başvurusuna kadar uçtan uca uyumlu gayrimenkul danışmanlığı.":{"en":"End-to-end, compliant real estate advisory for foreign investors, from the foreign-currency exchange certificate to the citizenship application.","ru":"Комплексный и соответствующий законодательству консалтинг по недвижимости для иностранных инвесторов — от справки о конвертации валюты до заявления на гражданство.","zh":"为外国投资者提供从换汇证明到入籍申请的端到端合规房产顾问服务。","ar":"استشارات عقارية متكاملة ومتوافقة للمستثمرين الأجانب، من وثيقة صرف العملة إلى طلب الجنسية."},"Ege Tatil Konutu & Kısa Dönem Kiralama Yönetimi":{"en":"Aegean Holiday Home & Short-Term Rental Management","ru":"Курортное жильё в Эгейском регионе и управление краткосрочной арендой","zh":"爱琴海地区度假房产与短租管理","ar":"مساكن العطلات في منطقة بحر إيجه وإدارة التأجير قصير المدى"},"Çeşme, Urla, Alaçatı ve Kuşadası hattında yazlık, villa ve yalı yatırımlarını sezonluk gelirle profesyonelce yönetiyoruz.":{"en":"Along the Çeşme, Urla, Alaçatı and Kuşadası line, we professionally manage summer house, villa and waterfront mansion (yalı) investments with seasonal income.","ru":"Профессионально управляем инвестициями в летние дома, виллы и прибрежные особняки (yalı) на линии Çeşme, Urla, Alaçatı и Kuşadası, обеспечивая сезонный доход.","zh":"在 Çeşme、Urla、Alaçatı 和 Kuşadası 一线，以季节性收益专业管理度假屋、别墅和 yalı 海滨豪宅投资。","ar":"ندير باحترافية استثمارات المنازل الصيفية والفلل والقصور المائية (yalı) على خط Çeşme وUrla وAlaçatı وKuşadası بدخل موسمي."},"Miras & İntikal İşlemleri":{"en":"Inheritance & Transfer Procedures","ru":"Наследство и операции по переходу имущества (Miras & İntikal)","zh":"遗产与继承过户业务","ar":"معاملات الميراث والانتقال"},"Veraset ilamından tapu intikaline, reddi mirastan izale-i şuyuya kadar tüm süreç tek elden.":{"en":"From the certificate of inheritance to title-deed transfer, from renunciation of inheritance to partition action, the entire process from a single point.","ru":"От свидетельства о праве на наследство (Veraset İlamı) до переоформления тапу, от отказа от наследства (Reddi Miras) до иска о разделе общей собственности (İzale-i Şuyu) — весь процесс из единого центра.","zh":"从继承权证明（Veraset İlamı）到房产证继承过户，从放弃继承（Reddi Miras）到共有物分割之诉（İzale-i Şuyu），全流程一站式办理。","ar":"كامل العملية من مصدر واحد، من حجة الوراثة (Veraset İlamı) إلى انتقال سند الملكية، ومن رفض الميراث (Reddi Miras) إلى دعوى إزالة الشيوع (İzale-i Şuyu)."},"Rehberi Aç":{"en":"Open the Guide","ru":"Открыть руководство","zh":"打开指南","ar":"افتح الدليل"},"Alım & Satım":{"en":"Buying & Selling","ru":"Купля-продажа","zh":"买卖","ar":"الشراء والبيع"},"Konut alım-satım danışmanlığı, bir dairenin, villanın veya müstakil evin el değiştirmesini sadece iki tarafı buluşturmaktan ibaret görmeyen, veri temelli bir aracılık hizmetidir. Meridyen Gayrimenkul olarak süreci; bölgedeki emsal satış verilerinin, metrekare birim fiyatlarının ve arz-talep dengesinin analiziyle başlatır, mülkü piyasanın gerçek değerine göre konumlandırırız. Amacımız satıcı için değeri gizli kalmış bir mülkü doğru fiyata satmak, alıcı için ise fazla ödeme yapmasını engellemektir. Satış tarafında profesyonel fotoğraf, mülk sunum dosyası, hedefli dijital pazarlama (portal ilanları, sosyal medya ve Meta reklamları) ve nitelikli alıcı ön elemesiyle mülkünüzü en geniş doğru kitleye ulaştırırız. Danışman aracılığıyla satılan konutların, kişisel satışa kıyasla ortalama daha kısa sürede ve daha yüksek fiyata el değiştirdiği sektör verileriyle sabittir. Alım tarafında ise ihtiyaç ve bütçe profilinize uygun mülkleri filtreler, tapu ve imar temizliği doğrulanmış seçenekleri size sunarız. Pazarlık aşamasında tarafsız ve deneyimli bir müzakereci gibi hareket eder, sözleşme ve kapora süreçlerini güvence altına alırız. Tapu devrine kadar geçen tüm adımlarda -ekspertiz, kredi, harç, evrak- yanınızda oluruz. Böylece duygusal ve finansal olarak yorucu bir süreci, şeffaf ve öngörülebilir bir işleme dönüştürürüz.":{"en":"Residential buying-and-selling advisory is a data-driven brokerage service that does not view the change of hands of an apartment, villa or detached house as merely bringing two parties together. As Meridyen Gayrimenkul, we begin the process by analyzing the region's comparable sales data, per-square-meter unit prices and the supply-demand balance, and we position the property according to the market's true value. Our aim is to sell, at the right price, a property whose value has stayed hidden for the seller, and to prevent the buyer from overpaying. On the sales side, with professional photography, a property presentation file, targeted digital marketing (portal listings, social media and Meta ads) and pre-screening of qualified buyers, we bring your property to the widest right audience. Industry data confirms that homes sold through an advisor change hands, on average, in a shorter time and at a higher price than in a private sale. On the buying side, we filter properties suited to your needs and budget profile and present you options whose title deed and zoning have been verified clean. During negotiation we act like an impartial, experienced negotiator and secure the contract and deposit processes. At every step up to the title-deed transfer -appraisal, loan, fees, paperwork- we are by your side. This way we turn an emotionally and financially exhausting process into a transparent and predictable transaction.","ru":"Консультации по купле-продаже жилья — это посредническая услуга на основе данных, для которой смена собственника квартиры, виллы или отдельного дома не сводится лишь к тому, чтобы свести две стороны. В Meridyen Gayrimenkul мы начинаем процесс с анализа данных о сопоставимых сделках в районе, цен за квадратный метр и баланса спроса и предложения, позиционируя объект по его реальной рыночной стоимости. Наша цель — для продавца продать по правильной цене объект, ценность которого осталась незамеченной, а для покупателя — не допустить переплаты. Со стороны продажи мы доводим ваш объект до максимально широкой и при этом целевой аудитории с помощью профессиональной фотосъёмки, презентационного досье объекта, таргетированного цифрового маркетинга (объявления на порталах, социальные сети и реклама Meta) и предварительного отбора квалифицированных покупателей. Отраслевые данные подтверждают, что жильё, продаваемое через консультанта, в среднем меняет собственника быстрее и по более высокой цене, чем при самостоятельной продаже. Со стороны покупки мы фильтруем объекты, соответствующие вашим потребностям и бюджету, и предлагаем варианты с проверенной чистотой тапу и зонирования. На этапе переговоров мы действуем как беспристрастный и опытный переговорщик, обеспечивая надёжность процессов договора и задатка. На всех шагах вплоть до переоформления тапу — оценка, кредит, пошлина, документы — мы рядом с вами. Так мы превращаем эмоционально и финансово изнурительный процесс в прозрачную и предсказуемую сделку.","zh":"住宅买卖顾问并非只是把买卖双方撮合在一起，而是一项以数据为基础的中介服务。作为 Meridyen Gayrimenkul，我们以对该区域可比成交数据、每平方米单价和供需平衡的分析开启流程，并根据市场的真实价值为房产定位。我们的目标是为卖方以正确的价格卖出价值被埋没的房产，为买方避免多付。在销售端，我们通过专业摄影、房产展示文件、精准的数字营销（门户网站挂牌、社交媒体和 Meta 广告）以及合格买家的预筛选，将您的房产触达最广泛且精准的受众。行业数据表明，经顾问出售的住宅相比个人自售，平均在更短时间内以更高价格成交。在购买端，我们筛选符合您需求和预算画像的房产，为您提供已核实房产证和规划清洁的选项。在议价阶段，我们如同中立而经验丰富的谈判者般行事，为合同和定金流程提供保障。直至房产证过户前的所有环节——估价、贷款、税费、文件——我们都在您身边。由此，我们把一个在情感和财务上都令人疲惫的过程，转变为透明且可预期的手续。","ar":"استشارات بيع وشراء المساكن هي خدمة وساطة قائمة على البيانات لا ترى في انتقال ملكية شقة أو فيلا أو منزل مستقل مجرد جمع بين طرفين. نحن في Meridyen Gayrimenkul نبدأ العملية بتحليل بيانات المبيعات المماثلة في المنطقة وأسعار وحدة المتر المربع وتوازن العرض والطلب، ونحدد موضع العقار وفق قيمته السوقية الحقيقية. هدفنا أن نبيع للبائع عقاراً بقيت قيمته خفية بالسعر الصحيح، وأن نمنع المشتري من الدفع الزائد. في جانب البيع نوصل عقاركم إلى أوسع جمهور صحيح عبر التصوير الاحترافي وملف عرض العقار والتسويق الرقمي المستهدف (إعلانات البوابات ووسائل التواصل وإعلانات Meta) والفرز المسبق للمشترين المؤهلين. وثابتٌ ببيانات القطاع أن المساكن المباعة عبر مستشار تنتقل ملكيتها في المتوسط بمدة أقصر وسعر أعلى مقارنةً بالبيع الشخصي. أما في جانب الشراء فنُرشّح العقارات المناسبة لملف احتياجاتكم وميزانيتكم، ونقدّم لكم خيارات مؤكَّدة السلامة من حيث سند الملكية والتنظيم العمراني. في مرحلة التفاوض نتصرّف كمفاوض محايد وذي خبرة، ونؤمّن إجراءات العقد والعربون. ونقف إلى جانبكم في كل الخطوات حتى نقل سند الملكية — التقييم، القرض، الرسم، الأوراق. وهكذا نحوّل عملية مرهقة عاطفياً ومالياً إلى معاملة شفافة ويمكن التنبؤ بها."},"İhtiyaç ve bütçe analizi":{"en":"Needs and budget analysis","ru":"Анализ потребностей и бюджета","zh":"需求与预算分析","ar":"تحليل الاحتياج والميزانية"},"Emsal veri & değer tespiti":{"en":"Comparable data & value assessment","ru":"Данные о сопоставимых сделках и определение стоимости","zh":"可比数据与价值评定","ar":"بيانات مماثلة وتحديد القيمة"},"Pazarlama veya mülk arama":{"en":"Marketing or property search","ru":"Маркетинг или поиск объекта","zh":"营销或房源搜寻","ar":"التسويق أو البحث عن العقار"},"Gösterim & müzakere":{"en":"Viewing & negotiation","ru":"Показ и переговоры","zh":"带看与谈判","ar":"المعاينة والتفاوض"},"Sözleşme ve kapora":{"en":"Contract and deposit","ru":"Договор и задаток","zh":"合同与定金","ar":"العقد والعربون"},"Tapu devri & teslim":{"en":"Title-deed transfer & handover","ru":"Переоформление тапу и передача","zh":"房产证过户与交付","ar":"نقل سند الملكية والتسليم"},"Emsal satış verisine dayalı gerçekçi fiyat raporu, tahmine değil veriye dayanır.":{"en":"A realistic price report based on comparable sales data relies on data, not guesswork.","ru":"Реалистичный отчёт о цене на основе данных о сопоставимых сделках опирается на данные, а не на предположения.","zh":"基于可比成交数据的现实价格报告，依据数据而非猜测。","ar":"تقرير سعر واقعي مبني على بيانات المبيعات المماثلة، يستند إلى البيانات لا إلى التخمين."},"Tapu ve imar durumu doğrulanmadan hiçbir mülk portföye alınmaz.":{"en":"No property is taken into the portfolio until its title deed and zoning status are verified.","ru":"Ни один объект не берётся в портфель без проверки статуса тапу и зонирования.","zh":"任何房产在房产证和规划状况未经核实前，都不会纳入房源。","ar":"لا يُدرَج أي عقار في المحفظة قبل التحقق من وضع سند الملكية والتنظيم العمراني."},"Kapora ve sözleşme süreçleri yazılı, şeffaf ve iki tarafı da koruyacak şekilde yürütülür.":{"en":"Deposit and contract processes are conducted in writing, transparently and in a way that protects both parties.","ru":"Процессы задатка и договора ведутся письменно, прозрачно и так, чтобы защитить обе стороны.","zh":"定金和合同流程以书面、透明且保护双方的方式进行。","ar":"تُدار إجراءات العربون والعقد كتابياً وبشفافية وبما يحمي الطرفين."},"Konutumu satmam ne kadar sürer?":{"en":"How long will it take to sell my home?","ru":"Сколько времени займёт продажа моего жилья?","zh":"卖掉我的住宅需要多久？","ar":"كم يستغرق بيع مسكني؟"},"Doğru fiyatlandırılmış ve pazarlaması iyi yapılan bir konut, bölge ve sezona göre genellikle birkaç hafta ile birkaç ay arasında satılır. Piyasa üzeri fiyatlama en büyük gecikme nedenidir.":{"en":"A well-priced and well-marketed home usually sells within a few weeks to a few months, depending on the region and season. Above-market pricing is the biggest cause of delay.","ru":"Правильно оценённое и хорошо продвигаемое жильё обычно продаётся за срок от нескольких недель до нескольких месяцев в зависимости от района и сезона. Завышенная относительно рынка цена — главная причина задержек.","zh":"定价合理、营销得当的住宅，视区域和季节通常在数周至数月内售出。高于市场的定价是最主要的延误原因。","ar":"المسكن المُسعّر بشكل صحيح والمسوّق جيداً يُباع عادةً خلال بضعة أسابيع إلى بضعة أشهر بحسب المنطقة والموسم. والتسعير فوق السوق هو السبب الأكبر للتأخير."},"Emlak komisyonu ne kadardır ve kim öder?":{"en":"How much is the real estate commission and who pays it?","ru":"Каков размер комиссии за недвижимость и кто её платит?","zh":"房产中介佣金是多少，由谁支付？","ar":"كم عمولة العقار ومن يدفعها؟"},"Yürürlükteki mevzuata göre hizmet bedeli genellikle satış bedelinin yüzde 2+2 KDV oranındadır; alıcı ve satıcı taraflarından tahsil edilir. Tüm bedel işlem öncesi yazılı olarak netleştirilir.":{"en":"Under current legislation, the service fee is generally 2+2% plus VAT of the sale price; it is collected from both the buyer and the seller. The entire fee is clarified in writing before the transaction.","ru":"Согласно действующему законодательству, стоимость услуги обычно составляет 2+2% + НДС от суммы продажи и взимается со стороны покупателя и продавца. Вся сумма письменно фиксируется до сделки.","zh":"根据现行法规，服务费通常为成交价的 2+2% 增值税；向买方和卖方双方收取。全部费用在交易前以书面形式明确。","ar":"وفقاً للتشريعات السارية يكون بدل الخدمة عادةً بنسبة 2+2% + ضريبة القيمة المضافة من قيمة البيع؛ ويُحصَّل من طرفي المشتري والبائع. ويُوضَّح كامل البدل كتابياً قبل المعاملة."},"Kiralama":{"en":"Leasing","ru":"Аренда","zh":"租赁","ar":"التأجير"},"Kiralama danışmanlığı, mülkünüzü boş bekletmeden, doğru kiracıyla ve hukuki güvence altında değerlendirmenizi sağlar. Meridyen Gayrimenkul, mülk kontrolünü yaptıktan sonra dijital mecralarda hedefli ilanlar açar, kiracı adaylarını gelir belgesi, referans ve güvenilirlik açısından ön elemeden geçirir. Böylece kira ödemesinde ve mülkün korunmasında en düşük riski taşıyan kiracı profili belirlenir. Kira garantili yönetim modelinde ise mülk sahibini kira gelirine ilişkin riskten büyük ölçüde arındırırız. Kiracı kira ödemesinde temerrüde düşse dahi, sistem devreye girerek mülk sahibine düzenli ve kesintisiz gelir akışını sağlamayı hedefler. Kira ödemeleri online olarak kayıt altına alınır; birden fazla mülkü olan sahipler tek panelden tüm kira gelirlerini görüntüleyebilir. Hukuk müşavirlerimizle hazırlanan kişiye özel kira sözleşmesi, tahliye taahhütnamesi ve teminatlar sayesinde mülk sahibi ileride yaşanabilecek uyuşmazlıklara karşı korunur. Kiracıya teslimde demirbaşlar ve mülkün fiziksel durumu kayıt altına alınır; tahliyede mülk ilk günkü durumuyla teslim alınır. Bu bütünsel yaklaşım, düzensiz ödeme ve tahliye süreçlerinde kaybedilen zaman ve geliri en aza indirir.":{"en":"Leasing advisory lets you make the most of your property with the right tenant and under legal security, without leaving it vacant. After inspecting the property, Meridyen Gayrimenkul opens targeted listings on digital channels and pre-screens candidate tenants for income documentation, references and reliability. This identifies the tenant profile carrying the lowest risk for rent payment and protection of the property. In the rent-guaranteed management model, we largely relieve the owner of the risk relating to rental income. Even if the tenant defaults on the rent payment, the system steps in and aims to provide the owner with a steady and uninterrupted flow of income. Rent payments are recorded online; owners with more than one property can view all their rental income from a single panel. Thanks to a customized lease agreement, eviction undertaking and guarantees prepared with our legal counsel, the owner is protected against disputes that may arise later. At handover to the tenant, the fixtures and the physical condition of the property are recorded; on vacating, the property is taken back in its original condition. This holistic approach minimizes the time and income lost in irregular payment and eviction processes.","ru":"Консультации по аренде позволяют вам использовать недвижимость без простоя, с правильным арендатором и под юридической защитой. Meridyen Gayrimenkul после проверки объекта размещает таргетированные объявления на цифровых площадках и проводит предварительный отбор кандидатов в арендаторы по справке о доходах, рекомендациям и благонадёжности. Так определяется профиль арендатора с наименьшим риском для арендных платежей и сохранности объекта. В модели управления с гарантией арендной платы мы в значительной мере избавляем собственника от рисков, связанных с доходом от аренды. Даже если арендатор допустит просрочку платежа, система вступает в действие, стремясь обеспечить собственнику регулярный и бесперебойный поток дохода. Арендные платежи фиксируются онлайн; собственники нескольких объектов могут видеть все свои арендные доходы на единой панели. Благодаря индивидуальному договору аренды, обязательству о выселении (tahliye taahhütnamesi) и обеспечению, подготовленным с нашими юрисконсультами, собственник защищён от возможных будущих споров. При передаче арендатору фиксируются опись имущества и физическое состояние объекта; при выселении объект принимается в состоянии первого дня. Такой целостный подход сводит к минимуму время и доход, теряемые при нерегулярных платежах и процессах выселения.","zh":"租赁顾问让您的房产不必空置等待，以合适的租客并在法律保障下加以利用。Meridyen Gayrimenkul 在完成房产查验后，在数字渠道发布精准挂牌，从收入证明、推荐和可信度方面对候选租客进行预筛选。由此确定在租金支付和房产保护方面风险最低的租客画像。在租金保障管理模式中，我们在很大程度上为业主消除了与租金收入相关的风险。即便租客在支付租金上违约，系统也会启动，力求为业主提供稳定且不间断的收入流。租金支付以在线方式记录；拥有多套房产的业主可在单一面板中查看全部租金收入。凭借与我们法律顾问共同拟定的专属租赁合同、清退承诺书和担保，业主得以应对未来可能发生的纠纷。在向租客交付时记录固定资产和房产的物理状况；清退时按最初的状态收回房产。这一整体化做法将不规律支付和清退过程中损失的时间和收入降至最低。","ar":"تتيح لكم استشارات التأجير تقييم عقاركم — دون تركه شاغراً — مع المستأجر الصحيح وتحت ضمانة قانونية. تقوم Meridyen Gayrimenkul، بعد إجراء فحص العقار، بنشر إعلانات مستهدفة في المنصات الرقمية، وتُخضع المرشّحين المستأجرين لفرز مسبق من حيث وثيقة الدخل والمراجع والموثوقية. وهكذا يُحدَّد ملف المستأجر الأقل خطراً على سداد الإيجار وحماية العقار. أما في نموذج الإدارة بضمان الإيجار فنُبعد المالك إلى حد كبير عن المخاطر المتعلقة بدخل الإيجار. وحتى إذا تعثّر المستأجر في سداد الإيجار، يتدخل النظام ليؤمّن للمالك تدفق دخل منتظم وغير منقطع. تُسجَّل مدفوعات الإيجار إلكترونياً؛ ويستطيع المالكون الذين يملكون أكثر من عقار عرض جميع إيرادات الإيجار من لوحة واحدة. وبفضل عقد الإيجار المخصّص وتعهد الإخلاء والضمانات المُعدّة مع مستشارينا القانونيين، يكون المالك محمياً من النزاعات المحتملة مستقبلاً. عند التسليم للمستأجر تُسجَّل الموجودات الثابتة والحالة المادية للعقار؛ وعند الإخلاء يُستلَم العقار بحالته الأولى. هذا النهج الشامل يقلّل إلى أدنى حد الوقت والدخل المفقودين في عمليات السداد غير المنتظم والإخلاء."},"Mülk kontrolü & kira değeri":{"en":"Property inspection & rental value","ru":"Проверка объекта и арендная стоимость","zh":"房产查验与租金价值","ar":"فحص العقار وقيمة الإيجار"},"İlan ve kiracı bulma":{"en":"Listing and finding a tenant","ru":"Объявление и поиск арендатора","zh":"挂牌与寻找租客","ar":"الإعلان وإيجاد المستأجر"},"Kiracı ön eleme (gelir/referans)":{"en":"Tenant pre-screening (income/reference)","ru":"Предварительный отбор арендатора (доход/рекомендации)","zh":"租客预筛选（收入/推荐）","ar":"الفرز المسبق للمستأجر (الدخل/المراجع)"},"Sözleşme & tahliye taahhüdü":{"en":"Contract & eviction undertaking","ru":"Договор и обязательство о выселении","zh":"合同与清退承诺书","ar":"العقد وتعهد الإخلاء"},"Kira takibi & tahsilat":{"en":"Rent tracking & collection","ru":"Контроль аренды и сбор платежей","zh":"租金跟踪与催收","ar":"متابعة الإيجار والتحصيل"},"Tahliyede durum kontrolü":{"en":"Condition check on vacating","ru":"Проверка состояния при выселении","zh":"清退时的状况查验","ar":"فحص الحالة عند الإخلاء"},"Kira garantili modelde temerrüt halinde bile mülk sahibine düzenli gelir akışı hedeflenir.":{"en":"In the rent-guaranteed model, a steady income flow to the owner is targeted even in the event of default.","ru":"В модели с гарантией арендной платы даже при просрочке цель — обеспечить собственнику регулярный поток дохода.","zh":"在租金保障模式中，即便发生违约，也力求为业主提供稳定的收入流。","ar":"في النموذج بضمان الإيجار، يُستهدَف تدفق دخل منتظم للمالك حتى في حالة التعثّر."},"Her kiracı gelir belgesi ve referans kontrolünden geçirilir, tahliye taahhütnamesi alınır.":{"en":"Every tenant is put through income documentation and reference checks, and an eviction undertaking is obtained.","ru":"Каждый арендатор проходит проверку справки о доходах и рекомендаций, оформляется обязательство о выселении.","zh":"每位租客都经过收入证明和推荐核查，并取得清退承诺书。","ar":"يُخضَع كل مستأجر لفحص وثيقة الدخل والمراجع، ويُؤخَذ منه تعهد إخلاء."},"Demirbaş ve mülk durumu teslimde ve tahliyede tutanakla kayıt altına alınır.":{"en":"Fixtures and the property's condition are recorded by report at handover and on vacating.","ru":"Опись имущества и состояние объекта фиксируются актом при передаче и при выселении.","zh":"固定资产和房产状况在交付和清退时以笔录记录。","ar":"تُسجَّل الموجودات الثابتة وحالة العقار بمحضر عند التسليم وعند الإخلاء."},"Kira garantisi tam olarak neyi kapsar?":{"en":"What exactly does the rent guarantee cover?","ru":"Что именно покрывает гарантия арендной платы?","zh":"租金保障究竟涵盖什么？","ar":"ماذا يغطّي ضمان الإيجار بالضبط؟"},"Kiracının kirayı geç ödemesi veya ödememesi durumunda mülk sahibinin gelirinin kesintiye uğramamasını hedefleyen bir güvence sistemidir; kapsam sözleşmede net olarak tanımlanır.":{"en":"It is an assurance system that aims to keep the owner's income uninterrupted if the tenant pays the rent late or fails to pay; the scope is clearly defined in the contract.","ru":"Это система обеспечения, цель которой — чтобы доход собственника не прерывался при просрочке или неуплате аренды арендатором; объём покрытия чётко определяется в договоре.","zh":"这是一套保障系统，旨在当租客迟付或不付租金时，使业主的收入不被中断；涵盖范围在合同中明确界定。","ar":"هو نظام ضمان يستهدف عدم انقطاع دخل المالك في حال تأخر المستأجر عن سداد الإيجار أو عدم سداده؛ ويُحدَّد النطاق بوضوح في العقد."},"Kiracı çıkmazsa tahliye sürecini siz mi yönetiyorsunuz?":{"en":"If the tenant won't leave, do you manage the eviction process?","ru":"Если арендатор не съезжает, вы ведёте процесс выселения?","zh":"如果租客不搬走，是由你们管理清退流程吗？","ar":"إذا لم يخرج المستأجر، هل تديرون أنتم عملية الإخلاء؟"},"Evet. Alınan tahliye taahhütnamesi ve hukuki destek ile tahliye sürecini takip eder, mülkün ilk günkü durumuyla teslim alınmasını sağlarız.":{"en":"Yes. With the eviction undertaking obtained and legal support, we follow the eviction process and ensure the property is taken back in its original condition.","ru":"Да. С помощью оформленного обязательства о выселении и юридической поддержки мы ведём процесс выселения и обеспечиваем приём объекта в состоянии первого дня.","zh":"是的。凭借取得的清退承诺书和法律支持，我们跟进清退流程，确保房产按最初状态收回。","ar":"نعم. نتابع عملية الإخلاء بتعهد الإخلاء المأخوذ والدعم القانوني، ونضمن استلام العقار بحالته الأولى."},"Ticari & Ofis":{"en":"Commercial & Office","ru":"Коммерческая и офисная недвижимость","zh":"商业与办公","ar":"التجاري والمكتبي"},"Ticari gayrimenkul, konuta göre daha yüksek kira getirisi ve genellikle daha uzun, kurumsal zeminde ilerleyen kira sözleşmeleri sunar. Ancak başarısı büyük ölçüde lokasyona ve doğru kiracı-mülk eşleşmesine bağlıdır. Meridyen Gayrimenkul, dükkan, ofis, plaza katı, depo ve endüstriyel tesis danışmanlığında; yaya akımı, ulaşım aksları, demografik segmentasyon ve güncel emsal kira verilerini bir arada değerlendiren bir lokasyon analizi metodolojisi uygular. 2025 piyasasında ofis talebi yüksek standartlı ve merkezi binalara kayarken esnek metrekare yönetimi öne çıkmış, perakendede gıda-içecek, sağlık ve spor odaklı kiracılar doğru yaya aksında güçlü performans göstermiş, lojistikte ise şehir içi erişilebilirliği yüksek mikrolokasyonlar kira büyümesinde lider olmuştur. Bu trendleri yatırımcı ve kiracı tarafına stratejik yol haritası olarak sunarız. Yeni şube açılışı, mağaza konsepti belirleme, mevcut mülkün fonksiyon değişikliği veya kurumsal marka için lokasyon seçimi kararlarında yanınızda oluruz. Mülk sahibi tarafında ise mülkünüzü kurumsal ve ödeme gücü yüksek kiracılarla buluşturarak sürdürülebilir bir gelir sağlarız.":{"en":"Commercial real estate offers a higher rental yield than residential and generally longer leases that proceed on a corporate footing. However, its success depends largely on location and the right tenant-property match. In advisory for shops, offices, plaza floors, warehouses and industrial facilities, Meridyen Gayrimenkul applies a location-analysis methodology that evaluates foot traffic, transport axes, demographic segmentation and current comparable rent data together. In the 2025 market, office demand has shifted toward high-standard, central buildings while flexible square-meter management has come to the fore; in retail, food-and-beverage, health and sports-focused tenants have performed strongly on the right pedestrian axis; and in logistics, micro-locations with high intra-city accessibility have led rent growth. We present these trends to investors and tenants as a strategic road map. We stand by you in decisions on opening a new branch, defining a store concept, changing the function of an existing property, or choosing a location for a corporate brand. On the owner's side, we secure sustainable income by matching your property with corporate, high-paying tenants.","ru":"Коммерческая недвижимость по сравнению с жильём приносит более высокую доходность от аренды и, как правило, предполагает более длительные договоры аренды на корпоративной основе. Однако её успех во многом зависит от локации и правильного соответствия арендатора и объекта. В консультациях по магазинам, офисам, этажам бизнес-центров, складам и промышленным объектам Meridyen Gayrimenkul применяет методологию анализа локации, которая одновременно учитывает пешеходный поток, транспортные оси, демографическую сегментацию и актуальные данные о сопоставимой аренде. На рынке 2025 года спрос на офисы сместился в сторону высококлассных и центральных зданий, а гибкое управление площадью вышло на первый план; в ритейле арендаторы в сегментах еды и напитков, здоровья и спорта показали сильные результаты на правильной пешеходной оси, а в логистике лидерами по росту аренды стали микролокации с высокой внутригородской доступностью. Мы предоставляем эти тренды инвестору и арендатору в виде стратегической дорожной карты. Мы рядом с вами при решениях об открытии нового филиала, определении концепции магазина, смене функции существующего объекта или выборе локации для корпоративного бренда. Со стороны собственника мы сводим ваш объект с корпоративными и платёжеспособными арендаторами, обеспечивая устойчивый доход.","zh":"商业房产相比住宅提供更高的租金收益，且通常提供更长、在企业化基础上推进的租赁合同。然而其成败在很大程度上取决于区位和精准的租客-房产匹配。Meridyen Gayrimenkul 在商铺、办公室、写字楼楼层、仓库和工业设施顾问中，运用一套将人流、交通轴线、人口结构细分和最新可比租金数据综合评估的区位分析方法论。在 2025 年的市场中，办公需求转向高标准的中心楼宇，灵活的面积管理凸显；零售业中以餐饮、健康和运动为主的租客在正确的人流轴线上表现强劲；物流方面，城市内可达性高的微区位在租金增长中领先。我们将这些趋势作为战略路线图提供给投资者和租客双方。在开设新分店、确定店铺概念、现有房产的功能变更或为企业品牌选址等决策中，我们与您相伴。在业主端，我们让您的房产与企业化且支付能力强的租客对接，实现可持续的收入。","ar":"يوفّر العقار التجاري عائد إيجار أعلى مقارنةً بالسكني، وعقود إيجار أطول عادةً تسير على أرضية مؤسسية. غير أن نجاحه يعتمد إلى حد كبير على الموقع والمطابقة الصحيحة بين المستأجر والعقار. تطبّق Meridyen Gayrimenkul في استشارات المحال والمكاتب وطوابق الأبراج والمستودعات والمنشآت الصناعية منهجية تحليل موقع تجمع بين حركة المشاة ومحاور النقل والتقسيم الديموغرافي وبيانات الإيجار المماثلة المحدّثة. في سوق 2025 اتجه الطلب على المكاتب نحو المباني عالية المعايير والمركزية وبرزت إدارة المساحة المرنة، وحقق المستأجرون في مجالات الأغذية والمشروبات والصحة والرياضة أداءً قوياً في محور المشاة الصحيح ضمن قطاع التجزئة، فيما تصدّرت المواقع الدقيقة عالية الوصول داخل المدينة نمو الإيجار في مجال اللوجستيك. نقدّم هذه الاتجاهات كخارطة طريق استراتيجية لجانبي المستثمر والمستأجر. ونقف إلى جانبكم في قرارات افتتاح فرع جديد وتحديد مفهوم المتجر وتغيير وظيفة عقار قائم أو اختيار موقع لعلامة مؤسسية. أما في جانب المالك فنؤمّن دخلاً مستداماً عبر جمع عقاركم بمستأجرين مؤسسيين وذوي قدرة سداد عالية."},"İş modeli & metrekare ihtiyacı":{"en":"Business model & square-meter need","ru":"Бизнес-модель и потребность в площади","zh":"商业模式与面积需求","ar":"نموذج العمل واحتياج المتر المربع"},"Lokasyon ve yaya akımı analizi":{"en":"Location and foot-traffic analysis","ru":"Анализ локации и пешеходного потока","zh":"区位与人流分析","ar":"تحليل الموقع وحركة المشاة"},"Emsal kira & getiri değerlendirmesi":{"en":"Comparable rent & yield assessment","ru":"Оценка сопоставимой аренды и доходности","zh":"可比租金与收益评估","ar":"تقييم الإيجار المماثل والعائد"},"Mülk / kiracı eşleştirme":{"en":"Property / tenant matching","ru":"Подбор объекта / арендатора","zh":"房产／租客匹配","ar":"مطابقة العقار / المستأجر"},"Ticari sözleşme müzakeresi":{"en":"Commercial contract negotiation","ru":"Переговоры по коммерческому договору","zh":"商业合同谈判","ar":"التفاوض على العقد التجاري"},"Teslim & süreç takibi":{"en":"Handover & process follow-up","ru":"Передача и контроль процесса","zh":"交付与流程跟进","ar":"التسليم ومتابعة العملية"},"Lokasyon kararları yaya akımı, demografi ve emsal veriyle desteklenir, sezgiyle değil.":{"en":"Location decisions are supported by foot traffic, demographics and comparable data, not by intuition.","ru":"Решения о локации подкрепляются пешеходным потоком, демографией и данными о сопоставимых объектах, а не интуицией.","zh":"区位决策以人流、人口结构和可比数据为支撑，而非凭直觉。","ar":"تُدعَم قرارات الموقع بحركة المشاة والديموغرافيا والبيانات المماثلة، لا بالحدس."},"Ticari kira sözleşmeleri kurumsal standartlarda, uzun vadeli ve koruyucu maddelerle hazırlanır.":{"en":"Commercial leases are prepared to corporate standards, long-term and with protective clauses.","ru":"Коммерческие договоры аренды составляются по корпоративным стандартам — долгосрочными и с защитными положениями.","zh":"商业租赁合同以企业化标准、长期且带保护性条款拟定。","ar":"تُعَد عقود الإيجار التجارية بمعايير مؤسسية وطويلة الأمد وببنود حامية."},"Kiracı ödeme gücü ve sektörel uyum önceden değerlendirilir.":{"en":"Tenant solvency and sector fit are assessed in advance.","ru":"Платёжеспособность арендатора и отраслевое соответствие оцениваются заранее.","zh":"租客的支付能力和行业契合度会事先评估。","ar":"تُقيَّم قدرة المستأجر على السداد وتوافقه القطاعي مسبقاً."},"Ofis mi dükkan mı daha iyi yatırım?":{"en":"Which is a better investment, office or shop?","ru":"Что выгоднее для инвестиций — офис или магазин?","zh":"办公室还是商铺是更好的投资？","ar":"المكتب أم المحل استثمار أفضل؟"},"Cevap lokasyona ve kiracı profiline bağlıdır. Cadde üstü dükkanlar perakende için, merkezi plazalar kurumsal kiracı için avantajlıdır; sizin için getiri ve risk analizini birlikte yaparız.":{"en":"The answer depends on the location and the tenant profile. Street-front shops are advantageous for retail, central plazas for corporate tenants; we carry out the return and risk analysis together for you.","ru":"Ответ зависит от локации и профиля арендатора. Магазины на улице выгодны для ритейла, центральные бизнес-центры — для корпоративного арендатора; мы вместе проведём для вас анализ доходности и рисков.","zh":"答案取决于区位和租客画像。临街商铺利于零售，中心写字楼利于企业租客；我们会为您一同做收益和风险分析。","ar":"الجواب يعتمد على الموقع وملف المستأجر. المحال على الشارع مفيدة للتجزئة، والأبراج المركزية مفيدة للمستأجر المؤسسي؛ ونجري لكم تحليل العائد والمخاطر معاً."},"Ticari mülkte kira çarpanı kaç olmalı?":{"en":"What should the rent multiplier be for a commercial property?","ru":"Каким должен быть мультипликатор аренды для коммерческой недвижимости?","zh":"商业房产的租金倍数应为多少？","ar":"كم يجب أن يكون مضاعف الإيجار في العقار التجاري؟"},"Konuta göre değişir; genelde iyi konumlu ticari mülkte daha düşük kira çarpanı yani daha hızlı geri dönüş beklenir. Her mülk için gerçek getiriyi ayrıca hesaplarız.":{"en":"It varies compared with residential; a well-located commercial property is generally expected to have a lower rent multiplier, that is, a faster payback. We calculate the real return separately for each property.","ru":"Отличается от жилья; обычно у хорошо расположенной коммерческой недвижимости ожидается более низкий мультипликатор аренды, то есть более быстрая окупаемость. Для каждого объекта мы отдельно рассчитываем реальную доходность.","zh":"视住宅而异；一般来说，区位良好的商业房产预期租金倍数更低，即回本更快。我们会为每套房产另行计算真实收益。","ar":"يختلف عن السكني؛ يُتوقَّع عادةً في العقار التجاري جيد الموقع مضاعف إيجار أدنى، أي استرداد أسرع. ونحسب العائد الحقيقي لكل عقار على حدة."},"Arsa & Arazi":{"en":"Plots & Land","ru":"Земельные участки","zh":"地块与土地","ar":"الأراضي والقطع"},"Arsa ve arazi yatırımı, doğru yapıldığında en yüksek değer artışını sunan, yanlış yapıldığında ise yatırımcıyı yıllarca hukuki süreçlere kilitleyebilen bir alandır. Meridyen Gayrimenkul olarak her arsa incelemesinde önce tapu senedindeki niteliği kontrol ederiz: tapuda arsa ibaresi ile tarla veya bahçe ibaresi çok farklı imar hakları ve yatırım potansiyeli doğurur. Ardından belediyeden imar durumunu, TAKS-KAKS oranlarını, sit ve yapılaşma kısıtlarını sorgular; yatırımınızın gerçekten ne inşa etmenize izin verdiğini netleştiririz. Hisseli tapularda diğer hissedarların ön alım (şufa) hakkı bulunabileceği veya ifrazın mümkün olmayabileceği gibi kritik riskleri baştan tespit ederiz. İzmir gibi fay hatları üzerindeki bir coğrafyada zemin etüdü ve dayanıklılık raporlarının önemini asla göz ardı etmez, bu kontrolleri yatırım kararınızın parçası haline getiririz. Ege bölgesinin büyüme akslarını, Torbalı ve Kemalpaşa gibi lojistik ve otoyol bağlantılı gelişme koridorlarını yakından izleriz. Bir arazinin asıl potansiyeli çoğu zaman gelecekte imara açılarak tarladan arsaya dönüşmesindedir; bu dönüşüm gerçekleştiğinde değer geometrik olarak artar. Doğru koridoru doğru zamanda yakalamanız için veriye dayalı yol haritası sunarız.":{"en":"Plot and land investment is an area that, done right, offers the highest appreciation, but done wrong can lock the investor into legal proceedings for years. As Meridyen Gayrimenkul, in every plot review we first check the designation on the title deed: the term \"building plot\" (arsa) versus \"field\" or \"orchard\" on the title deed gives rise to very different zoning rights and investment potential. Next we query the zoning status, TAKS/KAKS ratios, and conservation-site and construction restrictions from the municipality, clarifying what your investment actually allows you to build. On shared title deeds, we identify critical risks from the outset, such as the other co-owners possibly holding a right of pre-emption (şufa) or subdivision possibly not being feasible. In a geography sitting on fault lines such as İzmir, we never overlook the importance of ground surveys and durability reports, and we make these checks part of your investment decision. We closely follow the Aegean region's growth axes and development corridors with logistics and highway connections, such as Torbalı and Kemalpaşa. A land parcel's real potential often lies in its future opening to development, turning from a field into a building plot; when that transformation occurs, its value rises geometrically. We provide a data-driven road map so that you catch the right corridor at the right time.","ru":"Инвестиции в земельные участки — это сфера, которая при правильном подходе даёт наибольший прирост стоимости, а при неправильном может на годы приковать инвестора к судебным процессам. В Meridyen Gayrimenkul при каждом изучении участка мы сначала проверяем его назначение в тапу: обозначение «участок под застройку» (arsa) и обозначение «поле» (tarla) или «сад» (bahçe) в тапу порождают совершенно разные права на застройку и инвестиционный потенциал. Затем мы запрашиваем в муниципалитете статус зонирования, коэффициенты TAKS-KAKS, охранные и строительные ограничения и уточняем, что именно ваша инвестиция действительно позволяет построить. При долевых тапу мы заранее выявляем критические риски — например, наличие у других дольщиков права преимущественной покупки (şufa) или невозможность выделения доли (ifraz). В такой географии, как Измир, расположенной на линиях разломов, мы никогда не пренебрегаем важностью геологического исследования грунта и отчётов о сейсмостойкости и делаем эти проверки частью вашего инвестиционного решения. Мы внимательно следим за осями роста Эгейского региона, за коридорами развития с логистическими и автомагистральными связями, такими как Torbalı и Kemalpaşa. Настоящий потенциал участка чаще всего в том, что в будущем он будет открыт под застройку и превратится из поля в участок под застройку; когда такое преобразование происходит, стоимость растёт в геометрической прогрессии. Мы предлагаем дорожную карту на основе данных, чтобы вы поймали правильный коридор в правильное время.","zh":"地块和土地投资，做对时能带来最高的价值增长，做错时则可能让投资者被锁在多年的法律纠纷中。作为 Meridyen Gayrimenkul，我们在每次地块勘查中首先核对房产证上的性质：房产证上标注为地块（arsa）与标注为农地（tarla）或园地（bahçe）会产生截然不同的规划权利和投资潜力。随后我们向市政府查询规划状况、TAKS-KAKS 比率、保护区和建设限制；厘清您的投资究竟允许建造什么。在共有房产证中，我们从一开始就识别诸如其他共有人可能享有优先购买权（şufa）、或无法进行分割（ifraz）等关键风险。在伊兹密尔这样位于断层带上的地理环境中，我们绝不忽视地质勘察和抗震报告的重要性，并把这些查验纳入您投资决策的一部分。我们密切关注爱琴海地区的增长轴线，以及 Torbalı 和 Kemalpaşa 等具备物流和高速公路连接的发展走廊。一块土地真正的潜力往往在于未来被纳入规划、从农地转为地块；当这一转变实现时，价值会呈几何级数增长。为让您在正确的时机把握正确的走廊，我们提供以数据为依据的路线图。","ar":"استثمار الأراضي والقطع مجال يوفّر أعلى ارتفاع في القيمة إذا أُحسِن، وقد يُكبّل المستثمر بإجراءات قانونية لسنوات إذا أُسيء. نحن في Meridyen Gayrimenkul نتحقق في كل فحص أرض أولاً من الوصف الوارد في سند الملكية: فوصف «أرض» (arsa) في السند يختلف كثيراً عن وصف «حقل» (tarla) أو «بستان» من حيث حقوق التنظيم العمراني والإمكانات الاستثمارية. ثم نستعلم من البلدية عن وضع التنظيم العمراني ونسب TAKS-KAKS وقيود المناطق الأثرية والبناء؛ ونوضّح ما الذي يسمح لكم استثماركم ببنائه فعلاً. وفي سندات الملكية المشاعة نحدد مسبقاً مخاطر حرجة مثل احتمال وجود حق الشفعة (şufa) لبقية الشركاء أو عدم إمكانية الإفراز. وفي جغرافيا على خطوط الصدع مثل إزمير لا نغفل أبداً أهمية دراسة التربة وتقارير المتانة، ونجعل هذه الفحوص جزءاً من قرار استثماركم. ونتابع عن كثب محاور نمو منطقة بحر إيجه وممرات التطور المرتبطة باللوجستيك والطرق السريعة مثل Torbalı وKemalpaşa. غالباً ما تكمن الإمكانات الحقيقية للأرض في تحوّلها مستقبلاً من حقل إلى أرض قابلة للبناء بفتحها للتنظيم العمراني؛ وعند حدوث هذا التحول ترتفع القيمة هندسياً. نقدّم لكم خارطة طريق قائمة على البيانات لتلتقطوا الممر الصحيح في الوقت الصحيح."},"Tapu niteliği & kayıt kontrolü":{"en":"Title-deed designation & record check","ru":"Назначение в тапу и проверка записи","zh":"房产证性质与登记核查","ar":"وصف سند الملكية وفحص القيد"},"İmar durumu ve TAKS/KAKS sorgusu":{"en":"Zoning status and TAKS/KAKS query","ru":"Статус зонирования и запрос TAKS/KAKS","zh":"规划状况及 TAKS/KAKS 查询","ar":"وضع التنظيم العمراني والاستعلام عن TAKS/KAKS"},"Hisse & şufa risk analizi":{"en":"Share & pre-emption (şufa) risk analysis","ru":"Анализ рисков доли и права преимущественной покупки (şufa)","zh":"份额与优先购买权（şufa）风险分析","ar":"تحليل مخاطر الحصص وحق الشفعة (şufa)"},"Zemin ve konum değerlendirmesi":{"en":"Ground and location assessment","ru":"Оценка грунта и местоположения","zh":"地质与位置评估","ar":"تقييم التربة والموقع"},"Gelişim koridoru & potansiyel raporu":{"en":"Development corridor & potential report","ru":"Отчёт о коридоре развития и потенциале","zh":"发展走廊与潜力报告","ar":"تقرير ممر التطور والإمكانات"},"Alım / satım ve devir":{"en":"Buying / selling and transfer","ru":"Купля / продажа и переоформление","zh":"买入／卖出与过户","ar":"الشراء / البيع والنقل"},"Her arsa için imar durumu ve tapu niteliği resmi kaynaklardan doğrulanır.":{"en":"For every plot, the zoning status and title-deed designation are verified from official sources.","ru":"Для каждого участка статус зонирования и назначение в тапу проверяются по официальным источникам.","zh":"每块地块的规划状况和房产证性质都从官方渠道核实。","ar":"يُتحقَّق لكل أرض من وضع التنظيم العمراني ووصف سند الملكية من المصادر الرسمية."},"Hisseli tapu, şufa hakkı ve ifraz riskleri satın almadan önce yazılı olarak raporlanır.":{"en":"Shared title deed, pre-emption (şufa) rights and subdivision risks are reported in writing before purchase.","ru":"Риски долевого тапу, права преимущественной покупки (şufa) и выделения доли (ifraz) письменно отражаются в отчёте до покупки.","zh":"共有房产证、优先购买权（şufa）和分割（ifraz）风险在购买前以书面报告。","ar":"تُوثَّق مخاطر السند المشاع وحق الشفعة (şufa) والإفراز كتابياً قبل الشراء."},"İzmir ve Ege'de zemin/fay hattı hassasiyeti değerlendirmeye dahil edilir.":{"en":"In İzmir and the Aegean, ground/fault-line sensitivity is included in the assessment.","ru":"В Измире и Эгейском регионе чувствительность к грунту/линии разлома включается в оценку.","zh":"在伊兹密尔和爱琴海地区，地质／断层带敏感性纳入评估。","ar":"تُدرَج حساسية التربة/خط الصدع في إزمير ومنطقة بحر إيجه ضمن التقييم."},"Tarla mı arsa mı almalıyım?":{"en":"Should I buy a field or a building plot?","ru":"Что покупать — поле (tarla) или участок под застройку (arsa)?","zh":"我该买农地还是地块？","ar":"هل أشتري حقلاً (tarla) أم أرضاً (arsa)؟"},"Kısa vadede yapı yapacaksanız imarlı arsa, uzun vadeli değer artışı hedefliyorsanız gelişim koridorundaki tarla mantıklı olabilir. İkisi arasındaki riski ve potansiyeli sizin için ayrıntılı kıyaslarız.":{"en":"If you will build in the short term, a zoned building plot; if you aim for long-term appreciation, a field in a development corridor may make sense. We compare the risk and potential between the two in detail for you.","ru":"Если вы собираетесь строить в краткосрочной перспективе — разумен участок под застройку с зонированием (imarlı arsa), если нацелены на долгосрочный прирост стоимости — поле в коридоре развития. Мы подробно сравним для вас риск и потенциал каждого из вариантов.","zh":"若短期内要建造，有规划的地块合适；若追求长期价值增长，发展走廊中的农地可能更合理。我们会为您详细比较两者之间的风险和潜力。","ar":"إذا كنتم ستبنون على المدى القصير فالأرض المنظَّمة عمرانياً، وإذا كنتم تستهدفون ارتفاع القيمة على المدى الطويل فقد يكون الحقل في ممر التطور منطقياً. نقارن لكم بالتفصيل بين المخاطر والإمكانات في كليهما."},"Hisseli tapulu arsa alınır mı?":{"en":"Should one buy a plot with a shared title deed?","ru":"Стоит ли покупать участок с долевым тапу?","zh":"该买共有房产证的地块吗？","ar":"هل تُشترى أرض بسند ملكية مشاع؟"},"Alınabilir ancak dikkat gerektirir; diğer hissedarların önalım hakkı ve bölünme kısıtları olabilir. Bu riskleri baştan inceleyip size net bir tablo sunarız.":{"en":"It can be bought, but it requires care; the other co-owners may have pre-emption rights and there may be subdivision restrictions. We examine these risks from the outset and give you a clear picture.","ru":"Купить можно, но требуется осторожность; у других дольщиков может быть право преимущественной покупки, а также возможны ограничения на раздел. Мы заранее изучим эти риски и представим вам чёткую картину.","zh":"可以买，但需谨慎；其他共有人可能享有优先购买权，且可能存在分割限制。我们会从一开始审查这些风险，为您呈现清晰的全貌。","ar":"يمكن ذلك لكنه يتطلب حذراً؛ فقد يكون لبقية الشركاء حق الشفعة وقيود على التقسيم. نفحص هذه المخاطر من البداية ونقدّم لكم صورة واضحة."},"Değerleme":{"en":"Valuation","ru":"Оценка","zh":"估价","ar":"التقييم"},"Doğru bir fiyat, hem satışta hem yatırımda en kritik karardır. Meridyen Gayrimenkul, mülkünüz için ön değerleme (ön ekspertiz) hizmeti sunar: taşınmazın konumu, niteliği, fiziksel durumu, imar bilgileri ve bölgedeki gerçekleşmiş emsal satışlar ışığında piyasa değerini şeffaf bir raporla ortaya koyarız. Bu rapor, fiyat belirlerken tahmine değil veriye dayanmanızı sağlar. Bankaya teminat, kredi, mahkeme, miras paylaşımı veya sermaye piyasası işlemleri gibi resmi ve yasal geçerlilik gerektiren durumlarda ise devreye SPK (Sermaye Piyasası Kurulu) lisanslı gayrimenkul değerleme kuruluşları girer. SPK lisanslı değerleme, taşınmazın belirli bir tarihteki muhtemel değerinin, SPK düzenlemeleri ve kabul edilmiş değerleme standartları çerçevesinde bağımsız ve tarafsız olarak takdir edilmesidir ve raporun yasal geçerliliğe sahip olduğunu gösterir. Biz, ön ekspertizinizi yapar, hangi işlemde SPK lisanslı rapor gerektiğini net olarak açıklar ve sizi doğrudan lisanslı kuruluşa yönlendiririz. Böylece hem gündelik alım-satım kararlarınızda gerçekçi bir referans fiyatına, hem de resmi süreçlerde yasal olarak geçerli bir rapora zamanında ulaşırsınız.":{"en":"The right price is the most critical decision, both in a sale and in an investment. Meridyen Gayrimenkul offers a preliminary valuation (preliminary appraisal) service for your property: in light of the property's location, designation, physical condition, zoning information and realized comparable sales in the region, we set out its market value in a transparent report. This report lets you base your pricing on data rather than guesswork. In official, legally binding situations such as bank collateral, loans, court, inheritance division or capital-market transactions, SPK (Capital Markets Board)-licensed real estate valuation firms come into play. SPK-licensed valuation is the independent and impartial assessment of a property's probable value at a specific date within the framework of SPK regulations and accepted valuation standards, and it means the report has legal validity. We carry out your preliminary appraisal, explain clearly which transaction requires an SPK-licensed report, and direct you straight to a licensed firm. This way you reach both a realistic reference price for your everyday buy-sell decisions and a legally valid report for official processes, in good time.","ru":"Правильная цена — самое важное решение как при продаже, так и при инвестировании. Meridyen Gayrimenkul предоставляет для вашей недвижимости услугу предварительной оценки (предварительной экспертизы): мы прозрачным отчётом раскрываем рыночную стоимость с учётом местоположения, назначения, физического состояния объекта, данных о зонировании и состоявшихся сопоставимых сделок в районе. Этот отчёт позволяет вам при определении цены опираться на данные, а не на предположения. В официальных и требующих юридической силы случаях — залог в банк, кредит, суд, раздел наследства или операции на рынке ценных бумаг — в дело вступают организации по оценке недвижимости, имеющие лицензию SPK (Совет по рынкам капитала). Оценка с лицензией SPK — это независимая и беспристрастная оценка вероятной стоимости объекта на определённую дату в рамках регулирования SPK и принятых стандартов оценки, и она означает, что отчёт обладает юридической силой. Мы выполняем вашу предварительную экспертизу, чётко объясняем, для какой операции требуется отчёт с лицензией SPK, и напрямую направляем вас к лицензированной организации. Так вы своевременно получаете и реалистичную ориентировочную цену для повседневных решений о купле-продаже, и юридически действительный отчёт для официальных процедур.","zh":"正确的价格，无论在销售还是投资中都是最关键的决策。Meridyen Gayrimenkul 为您的房产提供初步估价服务：在房产的位置、性质、物理状况、规划信息和该区域已成交可比案例的综合考量下，以透明的报告呈现市场价值。这份报告让您在定价时依据数据而非猜测。而在向银行提供担保、贷款、法院、遗产分割或资本市场交易等需要正式和法律效力的情形中，则由持 SPK（资本市场委员会）牌照的房产估价机构介入。SPK 牌照估价，是在 SPK 规定和公认估价标准的框架下，对房产在特定日期的可能价值做出独立、公正的评定，并表明报告具有法律效力。我们为您做初步估价，明确说明哪类交易需要 SPK 牌照报告，并将您直接转介至持牌机构。由此，您既能在日常买卖决策中及时获得现实的参考价格，也能在正式流程中及时获得具法律效力的报告。","ar":"السعر الصحيح هو القرار الأكثر حسماً في البيع وفي الاستثمار معاً. تقدّم Meridyen Gayrimenkul لعقاركم خدمة تقييم مبدئي (تقييم أولي): نُظهر القيمة السوقية بتقرير شفاف في ضوء موقع العقار ووصفه وحالته المادية ومعلومات التنظيم العمراني والمبيعات المماثلة المتحققة في المنطقة. يتيح لكم هذا التقرير الاستناد إلى البيانات لا إلى التخمين عند تحديد السعر. أما في الحالات الرسمية التي تتطلب صلاحية قانونية مثل الرهن المصرفي والقرض والمحكمة وتقسيم الميراث أو معاملات سوق المال، فتدخل جهات تقييم العقارات المرخّصة من SPK (هيئة أسواق المال). التقييم المرخّص من SPK هو تقدير القيمة المحتملة للعقار في تاريخ معيّن بشكل مستقل ومحايد ضمن إطار أنظمة SPK ومعايير التقييم المعتمدة، ويُثبت أن التقرير ذو صلاحية قانونية. نحن نُجري تقييمكم المبدئي، ونوضّح بجلاء أي معاملة تتطلب تقريراً مرخّصاً من SPK، ونحيلكم مباشرةً إلى الجهة المرخّصة. وهكذا تصلون في الوقت المناسب إلى سعر مرجعي واقعي لقرارات البيع والشراء اليومية، وإلى تقرير ذي صلاحية قانونية في الإجراءات الرسمية."},"Mülk yerinde inceleme":{"en":"On-site property inspection","ru":"Осмотр объекта на месте","zh":"房产实地勘查","ar":"معاينة العقار في الموقع"},"İmar & tapu bilgisi kontrolü":{"en":"Zoning & title-deed information check","ru":"Проверка данных зонирования и тапу","zh":"规划与房产证信息核查","ar":"فحص معلومات التنظيم العمراني وسند الملكية"},"Emsal satış verisi analizi":{"en":"Comparable sales data analysis","ru":"Анализ данных о сопоставимых сделках","zh":"可比成交数据分析","ar":"تحليل بيانات المبيعات المماثلة"},"Ön değer raporu sunumu":{"en":"Preliminary value report presentation","ru":"Представление отчёта о предварительной стоимости","zh":"初步价值报告呈交","ar":"تقديم تقرير القيمة المبدئية"},"Gerekirse SPK lisanslı kuruluşa yönlendirme":{"en":"Referral to an SPK-licensed firm if needed","ru":"При необходимости направление в организацию с лицензией SPK","zh":"必要时转介至持 SPK 牌照机构","ar":"الإحالة إلى جهة مرخّصة من SPK عند اللزوم"},"Ön değerleme, gerçekleşmiş emsal satış verisine dayanır; şişirilmiş beklenti oluşturulmaz.":{"en":"The preliminary valuation is based on realized comparable sales data; no inflated expectation is created.","ru":"Предварительная оценка опирается на данные о состоявшихся сопоставимых сделках; завышенных ожиданий не создаётся.","zh":"初步估价依据已成交的可比数据；不制造被夸大的预期。","ar":"يستند التقييم المبدئي إلى بيانات المبيعات المماثلة المتحققة؛ ولا يُخلَق توقع مبالغ فيه."},"Resmi işlem gerektiğinde yalnızca SPK lisanslı, yasal geçerli kuruluşlara yönlendirme yapılır.":{"en":"When an official transaction is required, referral is made only to SPK-licensed, legally valid firms.","ru":"Когда требуется официальная операция, направление осуществляется только в организации с лицензией SPK, имеющие юридическую силу.","zh":"需要正式手续时，仅转介至持 SPK 牌照、具法律效力的机构。","ar":"عند الحاجة إلى معاملة رسمية، تتم الإحالة فقط إلى جهات مرخّصة من SPK وذات صلاحية قانونية."},"Değer raporu yazılı ve gerekçeli olarak teslim edilir.":{"en":"The value report is delivered in writing and with justification.","ru":"Отчёт о стоимости предоставляется в письменном и обоснованном виде.","zh":"价值报告以书面并附理由的方式交付。","ar":"يُسلَّم تقرير القيمة كتابياً ومُسبَّباً."},"Sizin verdiğiniz değerleme bankada geçerli mi?":{"en":"Is the valuation you provide valid at the bank?","ru":"Действительна ли ваша оценка в банке?","zh":"你们出具的估价在银行有效吗？","ar":"هل التقييم الذي تقدّمونه صالح لدى البنك؟"},"Bizim ön ekspertizimiz karar desteği içindir. Banka kredisi, mahkeme veya resmi işlemler için SPK lisanslı bir kuruluşun raporu gerekir; sizi doğru kuruluşa yönlendiririz.":{"en":"Our preliminary appraisal is for decision support. For a bank loan, court or official transactions, a report from an SPK-licensed firm is required; we direct you to the right firm.","ru":"Наша предварительная экспертиза предназначена для поддержки решений. Для банковского кредита, суда или официальных операций требуется отчёт организации с лицензией SPK; мы направим вас в нужную организацию.","zh":"我们的初步估价用于决策支持。银行贷款、法院或正式手续需要持 SPK 牌照机构的报告；我们会将您转介至正确的机构。","ar":"تقييمنا المبدئي لدعم القرار. أما لقرض البنك أو المحكمة أو المعاملات الرسمية فيلزم تقرير من جهة مرخّصة من SPK؛ ونحيلكم إلى الجهة الصحيحة."},"Değerleme ile satış fiyatı neden farklı olabilir?":{"en":"Why can the valuation and the sale price differ?","ru":"Почему оценка и цена продажи могут различаться?","zh":"估价与成交价为何会不同？","ar":"لماذا قد يختلف التقييم عن سعر البيع؟"},"Değerleme muhtemel piyasa değerini gösterir; nihai satış fiyatı arz-talep, aciliyet ve pazarlıkla oluşur. İkisini birlikte değerlendirerek stratejinizi belirleriz.":{"en":"Valuation shows the probable market value; the final sale price is formed by supply-demand, urgency and negotiation. We determine your strategy by evaluating the two together.","ru":"Оценка показывает вероятную рыночную стоимость; итоговая цена продажи формируется спросом и предложением, срочностью и торгом. Оценивая оба фактора вместе, мы определяем вашу стратегию.","zh":"估价显示的是可能的市场价值；最终成交价由供需、紧迫程度和议价形成。我们会将两者结合评估，为您确定策略。","ar":"يُظهر التقييم القيمة السوقية المحتملة؛ أما سعر البيع النهائي فيتكوّن من العرض والطلب والإلحاح والتفاوض. نحدد استراتيجيتكم بتقييم الاثنين معاً."},"Yatırım":{"en":"Investment","ru":"Инвестиции","zh":"投资","ar":"الاستثمار"},"Gayrimenkul yatırımı, doğru metriklerle ölçülmediğinde yanıltıcı olabilir. Meridyen Gayrimenkul, her yatırım adayı mülk için kira çarpanı, brüt ve net kira getirisi, ROI ve amortisman süresini birlikte hesaplayarak gerçek kârlılığı önünüze koyar. Kira çarpanı, mülkün fiyatının yıllık brüt kira gelirine oranıdır; örneğin 2 milyon TL'ye alınan ve aylık 15 bin TL kira getiren bir dairenin çarpanı yaklaşık 11 yıla denk gelir. Ancak brüt getiri tek başına yeterli değildir. Net kira getirisi, bakım-onarım (genelde kira gelirinin yüzde 5-10'u), vergi, aidat ve boş kalma riski gibi tüm işletme giderlerini düşerek mülkün gerçek kârlılığını gösterir: (Yıllık Net Kira Geliri / Satın Alma Fiyatı) x 100. Genellikle 15 yıl ve altı kira çarpanına sahip bölgeler yatırım açısından daha caziptir; çarpanın yükselmesi düşen getiri veya artan risk anlamına gelebilir. İzmir, İstanbul ve büyük şehirlerden aldığı nitelikli göç, gelişen sanayisi, turizm potansiyeli ve genç nüfusuyla Türkiye'nin en cazip yatırım pazarlarından biridir. Türkiye genelinde yıllık kira getirisi son dönemde yüzde 6-10 bandına yükselmiştir. Biz bu makro tabloyu, seçtiğiniz mülkün mikro verisiyle birleştirerek size en yüksek risk-getiri dengesini sunan seçeneği gösteririz.":{"en":"Real estate investment can be misleading when it is not measured with the right metrics. For every candidate investment property, Meridyen Gayrimenkul calculates the rent multiplier, gross and net rental yield, ROI and payback period together to put the real profitability in front of you. The rent multiplier is the ratio of the property's price to its annual gross rental income; for example, an apartment bought for 2 million TL that yields 15 thousand TL rent per month has a multiplier equal to approximately 11 years. But gross yield alone is not enough. Net rental yield shows the property's real profitability by deducting all operating expenses such as maintenance-repair (generally 5-10% of rental income), tax, dues and vacancy risk: (Annual Net Rental Income / Purchase Price) x 100. Regions with a rent multiplier of 15 years or below are generally more attractive for investment; a rising multiplier can mean falling yield or increasing risk. With the qualified migration it receives from İstanbul and other major cities, its growing industry, tourism potential and young population, İzmir is one of Turkey's most attractive investment markets. Across Turkey, the annual rental yield has recently risen to the 6-10% band. We combine this macro picture with the micro data of the property you choose to show you the option offering the highest risk-return balance.","ru":"Инвестиции в недвижимость могут вводить в заблуждение, если их не измерять правильными метриками. Для каждого рассматриваемого для инвестиций объекта Meridyen Gayrimenkul, рассчитывая вместе мультипликатор аренды, валовую и чистую доходность аренды, ROI и срок окупаемости, показывает вам реальную прибыльность. Мультипликатор аренды — это отношение цены объекта к годовому валовому доходу от аренды; например, у квартиры, купленной за 2 млн TL и приносящей 15 тыс. TL аренды в месяц, мультипликатор составляет около 11 лет. Однако одной валовой доходности недостаточно. Чистая доходность аренды показывает реальную прибыльность объекта за вычетом всех операционных расходов — обслуживания и ремонта (обычно 5-10% дохода от аренды), налогов, взносов и риска простоя: (Годовой чистый доход от аренды / Цена покупки) x 100. Как правило, районы с мультипликатором аренды 15 лет и ниже более привлекательны для инвестиций; рост мультипликатора может означать снижение доходности или увеличение риска. Измир — один из самых привлекательных инвестиционных рынков Турции благодаря качественной миграции из Стамбула и крупных городов, развивающейся промышленности, туристическому потенциалу и молодому населению. По Турции в целом годовая доходность аренды в последнее время поднялась до диапазона 6-10%. Объединяя эту макрокартину с микроданными по выбранному вами объекту, мы показываем вариант с наилучшим балансом риска и доходности.","zh":"房产投资若不以正确的指标衡量，可能具有误导性。Meridyen Gayrimenkul 为每一处候选投资房产同时计算租金倍数、毛租金收益和净租金收益、ROI 及回本周期，把真实的盈利能力摆在您面前。租金倍数是房产价格与年度毛租金收入之比；例如，一套以 200 万 TL 购入、月租 1.5 万 TL 的公寓，其倍数约相当于 11 年。然而毛收益本身并不足够。净租金收益是在扣除维护维修（一般为租金收入的 5-10%）、税费、物业费和空置风险等全部运营支出后，显示房产真实盈利能力：（年度净租金收入 / 购入价格）× 100。通常租金倍数在 15 年及以下的区域在投资上更具吸引力；倍数升高可能意味着收益下降或风险上升。伊兹密尔凭借从伊斯坦布尔和各大城市获得的优质人口流入、发展中的工业、旅游潜力和年轻人口，是土耳其最具吸引力的投资市场之一。近来土耳其全国的年度租金收益已升至 6-10% 区间。我们把这一宏观图景与您所选房产的微观数据结合，向您展示能提供最高风险-收益平衡的选项。","ar":"قد يكون الاستثمار العقاري مضلِّلاً إذا لم يُقَس بالمقاييس الصحيحة. تضع Meridyen Gayrimenkul أمامكم الربحية الحقيقية عبر حساب مضاعف الإيجار وعائد الإيجار الإجمالي والصافي وROI ومدة الاسترداد معاً لكل عقار مرشّح للاستثمار. مضاعف الإيجار هو نسبة سعر العقار إلى دخل الإيجار الإجمالي السنوي؛ فمثلاً شقة تُشترى بمبلغ 2 مليون TL وتدرّ إيجاراً شهرياً قدره 15 ألف TL يبلغ مضاعفها نحو 11 عاماً. غير أن العائد الإجمالي وحده لا يكفي. أما صافي عائد الإيجار فيُظهر الربحية الحقيقية للعقار بعد خصم جميع نفقات التشغيل مثل الصيانة والإصلاح (عادةً 5-10% من دخل الإيجار) والضريبة ورسوم الإدارة وخطر الشغور: (صافي دخل الإيجار السنوي / سعر الشراء) × 100. عادةً ما تكون المناطق ذات مضاعف الإيجار 15 عاماً فأقل أكثر جاذبيةً استثمارياً؛ وارتفاع المضاعف قد يعني انخفاض العائد أو ازدياد المخاطر. وتُعد إزمير من أكثر أسواق الاستثمار جاذبيةً في تركيا بفضل الهجرة النوعية من إسطنبول والمدن الكبرى وصناعتها المتنامية وإمكاناتها السياحية وسكانها الشباب. وقد ارتفع عائد الإيجار السنوي في عموم تركيا مؤخراً إلى نطاق 6-10%. نجمع هذه الصورة الكلية مع البيانات الجزئية للعقار الذي تختارونه لنُظهر لكم الخيار الذي يقدّم أفضل توازن بين المخاطر والعائد."},"Yatırım hedefi & risk profili":{"en":"Investment goal & risk profile","ru":"Инвестиционная цель и профиль риска","zh":"投资目标与风险画像","ar":"هدف الاستثمار وملف المخاطر"},"Bölge ve mülk aday listesi":{"en":"Region and property shortlist","ru":"Список кандидатов по региону и объектам","zh":"区域与候选房产清单","ar":"قائمة المناطق والعقارات المرشّحة"},"Kira çarpanı & net ROI hesabı":{"en":"Rent multiplier & net ROI calculation","ru":"Расчёт мультипликатора аренды и чистого ROI","zh":"租金倍数与净 ROI 计算","ar":"حساب مضاعف الإيجار وصافي ROI"},"Amortisman & senaryo analizi":{"en":"Payback & scenario analysis","ru":"Анализ окупаемости и сценариев","zh":"回本周期与情景分析","ar":"تحليل الاسترداد والسيناريوهات"},"Yatırım kararı ve alım":{"en":"Investment decision and purchase","ru":"Инвестиционное решение и покупка","zh":"投资决策与购入","ar":"قرار الاستثمار والشراء"},"Getiri takibi & çıkış planı":{"en":"Return tracking & exit plan","ru":"Контроль доходности и план выхода","zh":"收益跟踪与退出计划","ar":"متابعة العائد وخطة الخروج"},"Her mülk için brüt değil net getiri ve amortisman süresi hesaplanır.":{"en":"For each property, net return and payback period are calculated, not gross.","ru":"Для каждого объекта рассчитывается не валовая, а чистая доходность и срок окупаемости.","zh":"为每套房产计算的是净收益而非毛收益，以及回本周期。","ar":"يُحسَب لكل عقار العائد الصافي ومدة الاسترداد لا العائد الإجمالي."},"Bakım, vergi, aidat ve boşluk riski gibi gizli maliyetler analize dahil edilir.":{"en":"Hidden costs such as maintenance, tax, dues and vacancy risk are included in the analysis.","ru":"Скрытые издержки — обслуживание, налоги, взносы и риск простоя — включаются в анализ.","zh":"维护、税费、物业费和空置风险等隐性成本都纳入分析。","ar":"تُدرَج التكاليف الخفية مثل الصيانة والضريبة ورسوم الإدارة وخطر الشغور في التحليل."},"Yatırım kararı yazılı getiri raporuyla desteklenir, sözlü vaatle değil.":{"en":"The investment decision is supported by a written return report, not by verbal promises.","ru":"Инвестиционное решение подкрепляется письменным отчётом о доходности, а не устными обещаниями.","zh":"投资决策以书面收益报告为支撑，而非口头承诺。","ar":"يُدعَم قرار الاستثمار بتقرير عائد مكتوب، لا بوعد شفهي."},"İyi bir kira çarpanı kaç olmalı?":{"en":"What should a good rent multiplier be?","ru":"Каким должен быть хороший мультипликатор аренды?","zh":"好的租金倍数应为多少？","ar":"كم يجب أن يكون مضاعف الإيجار الجيد؟"},"Genellikle 15 ve altı kira çarpanı yatırımcı için caziptir; 12'nin üzeri daha düşük getiri ya da yüksek fiyat sinyali olabilir. Bölge özelinde ideal aralığı birlikte belirleriz.":{"en":"Generally a rent multiplier of 15 or below is attractive for the investor; above 12 can signal lower yield or a high price. We determine the ideal range for the specific region together.","ru":"Обычно мультипликатор аренды 15 и ниже привлекателен для инвестора; выше 12 может быть сигналом более низкой доходности или высокой цены. Идеальный диапазон для конкретного района мы определим вместе.","zh":"通常租金倍数在 15 及以下对投资者有吸引力；高于 12 可能是收益偏低或价格偏高的信号。我们会针对具体区域一同确定理想区间。","ar":"عادةً يكون مضاعف الإيجار 15 فأقل جذاباً للمستثمر؛ وما فوق 12 قد يكون إشارة إلى عائد أدنى أو سعر مرتفع. نحدد معاً النطاق المثالي حسب المنطقة."},"Net getiri ile brüt getiri arasındaki fark nedir?":{"en":"What is the difference between net yield and gross yield?","ru":"В чём разница между чистой и валовой доходностью?","zh":"净收益与毛收益之间有何区别？","ar":"ما الفرق بين العائد الصافي والعائد الإجمالي؟"},"Brüt getiri sadece kirayı, net getiri ise bakım, vergi, aidat ve boş kalma gibi giderleri düştükten sonra gerçek kârı gösterir. Kararınızı net getiriye göre veririz.":{"en":"Gross yield reflects only the rent, while net yield shows the real profit after deducting expenses such as maintenance, tax, dues and vacancy. We base your decision on the net yield.","ru":"Валовая доходность учитывает только аренду, а чистая доходность показывает реальную прибыль после вычета расходов — обслуживания, налогов, взносов и простоя. Ваше решение мы принимаем исходя из чистой доходности.","zh":"毛收益仅指租金，净收益则是在扣除维护、税费、物业费和空置等支出后显示的真实利润。我们建议您依据净收益做决策。","ar":"يُظهر العائد الإجمالي الإيجار فقط، أما العائد الصافي فيُظهر الربح الحقيقي بعد خصم نفقات مثل الصيانة والضريبة ورسوم الإدارة والشغور. ونتخذ قراركم بناءً على العائد الصافي."},"Endeks & Analiz":{"en":"Index & Analysis","ru":"Индекс и анализ","zh":"指数与分析","ar":"المؤشر والتحليل"},"Doğru bölgeyi doğru zamanda seçmek, gayrimenkulde kazancın büyük bölümünü belirler. Meridyen Gayrimenkul, kararlarını TCMB Konut Fiyat Endeksi, TÜİK verileri ve güncel semt bazlı metrekare fiyatları gibi resmi ve piyasa göstergeleriyle destekler. Konut Fiyat Endeksi, ülke genelindeki konut fiyatlarının değişimini ölçen resmi bir göstergedir; biz bunu İzmir ilçe ve semt kırılımına indirerek yorumlarız. İzmir, son yıllarda güçlü bir değer artışı yaşadı; metrekare birim değerleri bazı bölgelerde yüzde 100'ün üzerinde arttı, kira endeksinde ise İzmir dönem dönem Türkiye'nin en yüksek yıllık artış oranlarına sahip oldu. Ancak her semt aynı hızda değerlenmez: Çeşme gibi premium bölgelerde metrekare fiyatları çok yüksek olup geri dönüş süresi uzayabilirken, gelişmekte olan ilçelerde giriş fiyatı düşük ve potansiyel yüksek olabilir. Biz size sadece bir mülkü değil, o mülkün içinde bulunduğu bölgenin geçmiş trendini, mevcut arz-talep dengesini ve gelecekteki altyapı-ulaşım projelerinin yaratacağı değer potansiyelini bir arada sunarız. Böylece alım, satım veya bekleme kararınızı sezgiyle değil endeks ve emsal veriyle verirsiniz.":{"en":"Choosing the right region at the right time determines much of the gain in real estate. Meridyen Gayrimenkul supports its decisions with official and market indicators such as the TCMB Housing Price Index, TÜİK data and current neighborhood-level per-square-meter prices. The Housing Price Index is an official indicator that measures the change in housing prices nationwide; we interpret it by breaking it down to İzmir district and neighborhood level. İzmir has experienced strong appreciation in recent years; per-square-meter unit values rose by over 100% in some areas, and in the rent index İzmir has from time to time had some of Turkey's highest annual increase rates. However, not every neighborhood appreciates at the same pace: in premium areas such as Çeşme, per-square-meter prices are very high and the payback period may lengthen, while in developing districts the entry price may be low and the potential high. We present you not just a property, but the past trend of the region it sits in, the current supply-demand balance, and the value potential that future infrastructure-transport projects will create, all together. This way you make your buy, sell or hold decision with index and comparable data rather than intuition.","ru":"Выбор правильного района в правильное время определяет бо́льшую часть выигрыша в недвижимости. Meridyen Gayrimenkul подкрепляет свои решения официальными и рыночными индикаторами — Индексом цен на жильё TCMB, данными TÜİK и актуальными ценами за квадратный метр по районам. Индекс цен на жильё — официальный индикатор, измеряющий изменение цен на жильё по стране; мы интерпретируем его в разбивке по округам и районам Измира. За последние годы Измир пережил сильный рост стоимости; удельная цена за квадратный метр в некоторых районах выросла более чем на 100%, а по индексу аренды Измир время от времени показывал одни из самых высоких годовых темпов роста в Турции. Однако не каждый район дорожает с одинаковой скоростью: в премиальных районах, таких как Çeşme, цены за квадратный метр очень высоки, и срок окупаемости может удлиняться, тогда как в развивающихся округах цена входа может быть низкой, а потенциал — высоким. Мы предлагаем вам не просто объект, а вместе с ним прошлый тренд района, в котором он находится, текущий баланс спроса и предложения и потенциал роста стоимости, который создадут будущие инфраструктурные и транспортные проекты. Так вы принимаете решение о покупке, продаже или ожидании не интуитивно, а на основе индекса и данных о сопоставимых объектах.","zh":"在正确的时机选择正确的区域，决定了房产收益的很大一部分。Meridyen Gayrimenkul 以 TCMB 住房价格指数、TÜİK 数据和最新的按街区每平方米价格等官方与市场指标支撑其决策。住房价格指数是衡量全国住房价格变动的官方指标；我们将其细化到伊兹密尔的区县和街区层面加以解读。伊兹密尔近年来经历了强劲的价值增长；每平方米单价在部分区域上涨超过 100%，而在租金指数上，伊兹密尔时常拥有土耳其最高的年度涨幅。然而并非每个街区都以同样的速度升值：在 Çeşme 这样的高端区域，每平方米价格极高，回本周期可能拉长；而在发展中的区县，入手价格低、潜力高。我们向您呈现的不仅是一套房产，还有该房产所在区域的历史趋势、当前供需平衡，以及未来基建-交通项目将带来的价值潜力。由此，您的买入、卖出或持币观望决策便不再凭直觉，而是依据指数和可比数据。","ar":"اختيار المنطقة الصحيحة في الوقت الصحيح يحدّد الجزء الأكبر من الربح في العقار. تدعم Meridyen Gayrimenkul قراراتها بمؤشرات رسمية وسوقية مثل مؤشر أسعار المساكن الصادر عن TCMB وبيانات TÜİK وأسعار المتر المربع المحدّثة على مستوى الأحياء. ومؤشر أسعار المساكن مؤشر رسمي يقيس تغيّر أسعار المساكن على مستوى البلاد؛ ونحن نفسّره بتنزيله إلى تقسيم أقضية وأحياء إزمير. شهدت إزمير في السنوات الأخيرة ارتفاعاً قوياً في القيمة؛ فقد ازدادت قيم وحدة المتر المربع في بعض المناطق بأكثر من 100%، وامتلكت إزمير من حين لآخر أعلى معدلات الارتفاع السنوي في تركيا ضمن مؤشر الإيجار. غير أن كل حي لا يرتفع بالسرعة نفسها: ففي المناطق المتميزة (premium) مثل Çeşme تكون أسعار المتر المربع مرتفعة جداً وقد تطول مدة الاسترداد، بينما قد يكون سعر الدخول منخفضاً والإمكانات مرتفعة في الأقضية النامية. لا نقدّم لكم عقاراً فقط، بل نقدّم مجتمعةً الاتجاه التاريخي للمنطقة التي يقع فيها ذلك العقار وتوازن العرض والطلب الحالي وإمكانات القيمة التي ستخلقها مشاريع البنية التحتية والنقل المستقبلية. وهكذا تتخذون قرار الشراء أو البيع أو الانتظار بالمؤشر والبيانات المماثلة لا بالحدس."},"Hedef bölge tanımı":{"en":"Target region definition","ru":"Определение целевого района","zh":"目标区域界定","ar":"تحديد المنطقة المستهدفة"},"TCMB/TÜİK endeks incelemesi":{"en":"TCMB/TÜİK index review","ru":"Изучение индексов TCMB/TÜİK","zh":"TCMB/TÜİK 指数分析","ar":"دراسة مؤشرات TCMB/TÜİK"},"Semt bazlı m² & kira verisi":{"en":"Neighborhood-level m² & rent data","ru":"Данные о цене за м² и аренде по районам","zh":"按街区的 m² 与租金数据","ar":"بيانات المتر المربع والإيجار على مستوى الأحياء"},"Trend & altyapı projesi analizi":{"en":"Trend & infrastructure project analysis","ru":"Анализ трендов и инфраструктурных проектов","zh":"趋势与基建项目分析","ar":"تحليل الاتجاهات ومشاريع البنية التحتية"},"Bölge fırsat raporu":{"en":"Regional opportunity report","ru":"Отчёт о возможностях района","zh":"区域机会报告","ar":"تقرير فرص المنطقة"},"Karar desteği (al/sat/bekle)":{"en":"Decision support (buy/sell/hold)","ru":"Поддержка решений (купить/продать/ждать)","zh":"决策支持（买入/卖出/观望）","ar":"دعم القرار (شراء/بيع/انتظار)"},"Analizler TCMB Konut Fiyat Endeksi ve resmi TÜİK verileriyle desteklenir.":{"en":"Analyses are supported by the TCMB Housing Price Index and official TÜİK data.","ru":"Анализы подкрепляются Индексом цен на жильё TCMB и официальными данными TÜİK.","zh":"分析以 TCMB 住房价格指数和官方 TÜİK 数据为支撑。","ar":"تُدعَم التحليلات بمؤشر أسعار المساكن الصادر عن TCMB وبيانات TÜİK الرسمية."},"Semt bazlı metrekare ve kira verileri güncel emsallerle raporlanır.":{"en":"Neighborhood-level per-square-meter and rent data are reported with current comparables.","ru":"Данные о цене за квадратный метр и аренде по районам отражаются в отчёте на основе актуальных сопоставимых объектов.","zh":"按街区的每平方米和租金数据以最新可比案例报告。","ar":"تُقدَّم بيانات المتر المربع والإيجار على مستوى الأحياء بتقارير مع أمثلة مماثلة محدّثة."},"Gelecek değer potansiyeli, planlanan altyapı ve ulaşım projelerine göre değerlendirilir.":{"en":"Future value potential is assessed according to planned infrastructure and transport projects.","ru":"Будущий потенциал стоимости оценивается исходя из запланированных инфраструктурных и транспортных проектов.","zh":"未来价值潜力依据规划中的基建和交通项目评估。","ar":"تُقيَّم إمكانات القيمة المستقبلية وفق مشاريع البنية التحتية والنقل المخطَّطة."},"İzmir'de hangi bölge yatırım için mantıklı?":{"en":"Which area in İzmir makes sense for investment?","ru":"Какой район в Измире разумен для инвестиций?","zh":"在伊兹密尔，哪个区域适合投资？","ar":"أي منطقة في إزمير منطقية للاستثمار؟"},"Bu, bütçenize ve vade beklentinize göre değişir. Prim yapmış premium bölgelerle henüz gelişen bölgeler farklı risk-getiri sunar; size özel bir bölge kıyas raporu hazırlarız.":{"en":"This varies according to your budget and time-horizon expectations. Premium areas that have already appreciated and areas that are still developing offer different risk-return profiles; we prepare a tailored regional comparison report for you.","ru":"Это зависит от вашего бюджета и ожидаемого срока. Подорожавшие премиальные районы и ещё развивающиеся районы предлагают разное соотношение риска и доходности; мы подготовим для вас индивидуальный сравнительный отчёт по районам.","zh":"这取决于您的预算和期限预期。已升值的高端区域与尚在发展的区域提供不同的风险-收益；我们会为您准备专属的区域对比报告。","ar":"يختلف ذلك حسب ميزانيتكم وتوقّعكم للمدى. فالمناطق المتميزة التي ارتفعت قيمتها والمناطق النامية بعدُ تقدّمان توازناً مختلفاً بين المخاطر والعائد؛ نُعِد لكم تقرير مقارنة مناطق مخصّصاً."},"Fiyat endeksi bana nasıl yarar sağlar?":{"en":"How does the price index benefit me?","ru":"Какую пользу мне приносит ценовой индекс?","zh":"价格指数对我有何帮助？","ar":"كيف يفيدني مؤشر الأسعار؟"},"Endeks, bir bölgenin fiyatlarının reel olarak mı arttığını yoksa balon mu olduğunu ayırt etmenizi sağlar. Alım-satım zamanlamanızı bu veriyle optimize ederiz.":{"en":"The index lets you tell whether a region's prices are rising in real terms or whether it is a bubble. We optimize the timing of your buy-sell with this data.","ru":"Индекс позволяет различить, действительно ли цены района растут в реальном выражении или это пузырь. С помощью этих данных мы оптимизируем время вашей купли-продажи.","zh":"指数能让您分辨一个区域的价格是真实上涨还是泡沫。我们据此为您优化买卖时机。","ar":"يتيح لكم المؤشر التمييز بين ما إذا كانت أسعار منطقةٍ ترتفع فعلياً أم أنها فقاعة. ونُحسّن توقيت البيع والشراء لديكم بهذه البيانات."},"Tapu & Hukuk":{"en":"Title Deed & Legal","ru":"Тапу и право","zh":"房产证与法律","ar":"سند الملكية والقانون"},"Tapu devri, alım-satımın en kritik ve geri dönüşü zor adımıdır; bir eksik evrak veya yanlış harç hesabı süreci günlerce geciktirebilir. Meridyen Gayrimenkul, TKGM Web Tapu sistemi üzerinden e-Devlet ile başlatılan satış başvurusunu, taşınmaz ve taraf bilgilerinin doğru girilmesini, tapu müdürlüğü onayını ve randevu oluşturulmasını uçtan uca takip eder. Süreçte taraflara, tapu harcı ve döner sermaye bedeli için referans numarası içeren bir SMS gönderilir; bu ödemelerin randevu saatinden önce mutlaka yapılmış olması gerekir. 2025 itibarıyla tapu harcı satış bedelinin yüzde 4'ü olarak hesaplanır ve buna döner sermaye bedeli eklenir. Biz bu tutarları önceden şeffafça hesaplar, sürpriz maliyet yaşamamanızı sağlarız. Ayrıca ipotek tesisi ve fekki, intikal (miras), cins değişikliği, ifraz-tevhit gibi işlemlerde ve tapudaki şerh, haciz veya ihtiyati tedbir gibi engellerin kontrolünde yol gösteririz. Gerektiğinde anlaşmalı hukuk müşavirlerimizle koordineli çalışarak sözleşme, tahliye taahhüdü ve devir güvenliğini sağlarız. Devir gününde her iki tarafın da tapu müdürlüğünde eksiksiz hazır olmasını organize ederiz.":{"en":"The title-deed transfer is the most critical and hard-to-reverse step of a buy-sell; a single missing document or a wrong fee calculation can delay the process by days. Meridyen Gayrimenkul follows end-to-end the sale application initiated via e-Devlet through the TKGM Web Tapu system, the correct entry of the property and party details, the land registry directorate's approval and the creation of the appointment. During the process, an SMS containing a reference number for the title-deed fee and the revolving fund fee is sent to the parties; these payments must be made before the appointment time. As of 2025, the title-deed fee is calculated as 4% of the sale price, and the revolving fund fee is added to it. We calculate these amounts transparently in advance so that you do not face surprise costs. We also guide you in transactions such as establishing and releasing a mortgage, transfer (inheritance), change of type, and subdivision-consolidation, and in checking for obstacles on the title deed such as annotations, attachments or precautionary injunctions. When needed, we work in coordination with our partner legal counsel to ensure the contract, eviction undertaking and transfer security. On transfer day, we organize both parties being fully present at the land registry directorate.","ru":"Переоформление тапу — самый ответственный и труднообратимый шаг купли-продажи; один недостающий документ или неверный расчёт пошлины может задержать процесс на дни. Meridyen Gayrimenkul от начала до конца сопровождает заявку на продажу, поданную через систему TKGM Web Tapu и e-Devlet: корректный ввод данных об объекте и сторонах, одобрение управления кадастра и запись на приём. В ходе процесса сторонам направляется SMS с референс-номером для уплаты пошлины за тапу и сбора оборотного фонда; эти платежи обязательно должны быть совершены до времени приёма. По состоянию на 2025 год пошлина за тапу рассчитывается как 4% от суммы продажи, к ней добавляется сбор оборотного фонда. Мы заранее прозрачно рассчитываем эти суммы, чтобы вы не столкнулись с неожиданными расходами. Кроме того, мы направляем вас при операциях установления и снятия ипотеки, переоформления по наследству (intikal), изменения вида объекта, выделения и объединения (ifraz-tevhit), а также при проверке препятствий в тапу — отметок, ареста или обеспечительных мер. При необходимости мы работаем в координации с нашими партнёрскими юрисконсультами, обеспечивая надёжность договора, обязательства о выселении и переоформления. В день переоформления мы организуем, чтобы обе стороны были полностью готовы в управлении кадастра.","zh":"房产证过户是买卖中最关键且难以逆转的一步；一份缺失的文件或一次错误的税费计算，都可能让流程延误数日。Meridyen Gayrimenkul 通过 TKGM Web Tapu 系统，全程跟进经由 e-Devlet 发起的销售申请、房产和当事方信息的正确录入、房产证登记处的审批以及预约的创建。流程中会向当事方发送一条含参考号的短信，用于房产证费和周转基金费；这些款项务必在预约时间之前完成缴纳。截至 2025 年，房产证费按成交价的 4% 计算，并在此基础上加收周转基金费。我们会提前透明地计算这些金额，确保您不会遭遇意外成本。此外，在抵押设立与注销、继承过户（intikal）、性质变更、分割-合并（ifraz-tevhit）等手续中，以及在房产证上的批注（şerh）、查封（haciz）或临时保全（ihtiyati tedbir）等障碍的核查中，我们为您指引方向。必要时，我们与合作的法律顾问协同工作，保障合同、清退承诺书和过户安全。在过户当天，我们安排双方在房产证登记处齐备到场。","ar":"نقل سند الملكية هو الخطوة الأكثر حسماً والأصعب رجوعاً في البيع والشراء؛ فورقة ناقصة أو حساب رسم خاطئ قد يؤخّر العملية أياماً. تتابع Meridyen Gayrimenkul من البداية إلى النهاية طلب البيع المُبدَأ عبر e-Devlet ضمن نظام TKGM Web Tapu، وإدخال معلومات العقار والأطراف بشكل صحيح، وموافقة مديرية سند الملكية، وإنشاء الموعد. خلال العملية يُرسَل إلى الأطراف رسالة SMS تحوي رقم مرجع لرسم سند الملكية وبدل الصندوق الدوّار؛ ويجب حتماً سداد هذه المدفوعات قبل موعد الموعد. اعتباراً من 2025 يُحسَب رسم سند الملكية بنسبة 4% من قيمة البيع ويُضاف إليه بدل الصندوق الدوّار. نحسب هذه المبالغ مسبقاً وبشفافية لنجنّبكم أي تكلفة مفاجئة. كما نرشدكم في معاملات مثل تأسيس الرهن وفكّه والانتقال (الميراث) وتغيير النوع والإفراز والتوحيد، وفي فحص العوائق مثل الإشارة والحجز والتدبير الاحترازي على سند الملكية. وعند اللزوم نعمل بتنسيق مع مستشارينا القانونيين المتعاقدين لتأمين العقد وتعهد الإخلاء وسلامة النقل. وننظّم في يوم النقل حضور الطرفين كاملاً في مديرية سند الملكية."},"Tapu kaydı & şerh kontrolü":{"en":"Title-deed record & annotation check","ru":"Проверка записи тапу и отметок","zh":"房产证登记与批注（şerh）核查","ar":"فحص قيد سند الملكية والإشارات"},"Web Tapu başvurusu":{"en":"Web Tapu application","ru":"Заявка через Web Tapu","zh":"Web Tapu 申请","ar":"طلب Web Tapu"},"Harç & döner sermaye hesabı":{"en":"Fee & revolving fund calculation","ru":"Расчёт пошлины и сбора оборотного фонда","zh":"税费与周转基金费计算","ar":"حساب الرسم ورسم الصندوق الدوّار"},"Ödeme ve randevu oluşturma":{"en":"Payment and appointment creation","ru":"Оплата и запись на приём","zh":"缴费与创建预约","ar":"السداد وإنشاء الموعد"},"Devir günü organizasyonu":{"en":"Transfer-day organization","ru":"Организация дня переоформления","zh":"过户当天的安排","ar":"تنظيم يوم النقل"},"Yeni tapu teslimi":{"en":"Delivery of the new title deed","ru":"Выдача нового тапу","zh":"新房产证交付","ar":"تسليم سند الملكية الجديد"},"Tapu üzerindeki haciz, ipotek ve şerhler devirden önce kontrol edilir.":{"en":"Attachments, mortgages and annotations on the title deed are checked before the transfer.","ru":"Арест, ипотека и отметки в тапу проверяются до переоформления.","zh":"房产证上的查封、抵押和批注在过户前核查。","ar":"تُفحَص الحجوزات والرهون والإشارات على سند الملكية قبل النقل."},"Harç ve döner sermaye bedelleri işlem öncesi net olarak hesaplanır.":{"en":"Fees and revolving fund charges are calculated clearly before the transaction.","ru":"Пошлина и сбор оборотного фонда чётко рассчитываются до операции.","zh":"税费和周转基金费在交易前明确计算。","ar":"تُحسَب رسوم الرسم والصندوق الدوّار بوضوح قبل المعاملة."},"Devir randevusu ve evrak süreci tarafların adına eksiksiz koordine edilir.":{"en":"The transfer appointment and paperwork process are coordinated in full on the parties' behalf.","ru":"Запись на переоформление и процесс документооборота полностью координируются от имени сторон.","zh":"过户预约和文件流程以当事方名义完整协调。","ar":"يُنسَّق موعد النقل وعملية الأوراق كاملةً نيابةً عن الأطراف."},"Tapu harcı ne kadar ve kim öder?":{"en":"How much is the title-deed fee and who pays it?","ru":"Каков размер пошлины за тапу и кто её платит?","zh":"房产证费是多少，由谁支付？","ar":"كم رسم سند الملكية ومن يدفعه؟"},"2025'te tapu harcı satış bedelinin yüzde 4'üdür; genelde alıcı ve satıcı arasında paylaşılır ancak taraflar aksini kararlaştırabilir. Ayrıca döner sermaye bedeli ödenir.":{"en":"In 2025 the title-deed fee is 4% of the sale price; it is generally shared between the buyer and seller, but the parties may agree otherwise. A revolving fund fee is also paid.","ru":"В 2025 году пошлина за тапу составляет 4% от суммы продажи; обычно делится между покупателем и продавцом, но стороны могут договориться об ином. Дополнительно уплачивается сбор оборотного фонда.","zh":"2025 年房产证费为成交价的 4%；一般由买卖双方分摊，但双方可另行约定。此外还需缴纳周转基金费。","ar":"في 2025 يبلغ رسم سند الملكية 4% من قيمة البيع؛ ويُقتسَم عادةً بين المشتري والبائع، لكن يمكن للطرفين الاتفاق على خلاف ذلك. كما يُدفَع بدل الصندوق الدوّار."},"Tapu randevusunu siz mi alıyorsunuz?":{"en":"Do you take the title-deed appointment?","ru":"Вы сами записываете на приём в кадастр?","zh":"房产证预约是由你们办理吗？","ar":"هل تأخذون أنتم موعد سند الملكية؟"},"Evet. Web Tapu üzerinden başvuru, ödeme ve randevu adımlarını sizin adınıza takip eder, devir gününü organize ederiz.":{"en":"Yes. We follow the application, payment and appointment steps via Web Tapu on your behalf and organize the transfer day.","ru":"Да. Мы от вашего имени ведём шаги подачи заявки, оплаты и записи через Web Tapu и организуем день переоформления.","zh":"是的。我们以您的名义跟进 Web Tapu 上的申请、缴费和预约步骤，并安排过户当天。","ar":"نعم. نتابع نيابةً عنكم خطوات الطلب والسداد والموعد عبر Web Tapu، وننظّم يوم النقل."},"Finansman":{"en":"Financing","ru":"Финансирование","zh":"融资","ar":"التمويل"},"Konut kredisi, alım kararının finansal bel kemiğidir; doğru banka ve doğru ödeme planı, uzun vadede ciddi tasarruf sağlar. Meridyen Gayrimenkul, kredi uygunluğunuzu değerlendirir, bankaların güncel faiz oranlarını ve maliyetlerini karşılaştırır ve bütçenize en uygun kredi yapısını kurgulamanıza yardımcı olur. İlk Evim gibi devlet destekli düşük faizli kredi seçeneklerinden yararlanma imkanınızı da değerlendiririz. Süreçte banka, mülkün kullanımını, imara uygunluğunu ve piyasa değerini tespit için uzman bir eksper gönderir. Kredi tutarı, ekspertiz raporundaki değerin en fazla yüzde 90'ı kadar çıkar; bu nedenle genellikle mülk değerinin en az yüzde 10'u kadar peşinatınız olması gerekir. Biz bu ekspertiz aşamasını ve gerçekçi kredi tavanını önceden hesaplayarak bütçe planınızı netleştiririz. Kredi tahsis ücreti (genelde kredi tutarının binde 5'i) ve ekspertiz ücreti gibi ek maliyetleri baştan sunar, sürpriz yaşamanızı önleriz. Başvuru süreci ortalama 5-7 iş gününde sonuçlanır; biz evrak hazırlığı ve banka koordinasyonuyla bu süreyi mümkün olduğunca kısaltırız. Ayrıca sabit ve değişken faiz seçenekleri arasında sizin risk profilinize uygun olanı seçmenizde yol gösteririz.":{"en":"A mortgage is the financial backbone of a purchase decision; the right bank and the right payment plan provide serious savings over the long term. Meridyen Gayrimenkul assesses your loan eligibility, compares banks' current interest rates and costs, and helps you structure the mortgage best suited to your budget. We also assess your ability to benefit from state-backed low-interest loan options such as İlk Evim. During the process, the bank sends an expert appraiser to determine the property's use, zoning compliance and market value. The loan amount can be up to at most 90% of the value in the appraisal report; therefore you generally need a down payment of at least 10% of the property's value. By calculating this appraisal stage and a realistic loan ceiling in advance, we clarify your budget plan. We present additional costs such as the loan allocation fee (generally 0.5% of the loan amount) and the appraisal fee from the outset, preventing surprises. The application process is concluded on average within 5-7 business days; with document preparation and bank coordination we shorten this time as much as possible. We also guide you in choosing, between fixed and variable interest options, the one suited to your risk profile.","ru":"Ипотека — финансовый стержень решения о покупке; правильный банк и правильный план платежей дают в долгосрочной перспективе существенную экономию. Meridyen Gayrimenkul оценивает вашу кредитоспособность, сравнивает актуальные процентные ставки и издержки банков и помогает выстроить наиболее подходящую для вашего бюджета структуру кредита. Мы также оцениваем вашу возможность воспользоваться государственными льготными кредитами с низкой ставкой, такими как İlk Evim. В ходе процесса банк направляет профессионального эксперта для определения использования объекта, соответствия зонированию и рыночной стоимости. Сумма кредита составляет не более 90% от стоимости в отчёте об оценке; поэтому, как правило, вам нужен первоначальный взнос не менее 10% от стоимости объекта. Заранее рассчитывая этот этап оценки и реалистичный лимит кредита, мы проясняем ваш бюджетный план. Мы заранее сообщаем о дополнительных издержках — комиссии за выдачу кредита (обычно 0,5% от суммы кредита) и плате за оценку, — чтобы вы не столкнулись с неожиданностями. Процесс рассмотрения заявки завершается в среднем за 5-7 рабочих дней; подготовкой документов и координацией с банком мы максимально сокращаем этот срок. Кроме того, мы помогаем вам выбрать между вариантами с фиксированной и плавающей ставкой тот, что соответствует вашему профилю риска.","zh":"住房贷款是购买决策的财务支柱；正确的银行和正确的还款计划，在长期能带来可观的节省。Meridyen Gayrimenkul 评估您的贷款资格，比较各银行最新的利率和成本，帮助您搭建最合适的贷款结构。我们还会评估您享受 İlk Evim 等政府支持的低息贷款选项的可能性。流程中，银行会派遣专业估价师，勘定房产的用途、规划合规性和市场价值。贷款金额最多为估价报告中价值的 90%；因此通常您需要有房产价值至少 10% 的首付。我们会提前计算这一估价环节和现实的贷款上限，厘清您的预算计划。贷款发放费（一般为贷款金额的千分之五）和估价费等额外成本会从一开始提供给您，避免让您遭遇意外。申请流程平均在 5-7 个工作日内完成；我们通过文件准备和银行协调，尽可能缩短这一时间。此外，我们会指引您在固定和浮动利率选项中选择契合您风险画像的一种。","ar":"القرض السكني هو العمود المالي لقرار الشراء؛ والبنك الصحيح وخطة السداد الصحيحة يوفّران على المدى الطويل ادخاراً كبيراً. تُقيّم Meridyen Gayrimenkul أهليتكم للقرض، وتقارن أسعار الفائدة والتكاليف المحدّثة للبنوك، وتساعدكم على تصميم أنسب هيكل قرض لميزانيتكم. كما نُقيّم إمكانية استفادتكم من خيارات القروض المدعومة حكومياً منخفضة الفائدة مثل İlk Evim. خلال العملية يرسل البنك خبير تقييم مختصاً لتحديد استخدام العقار وموافقته للتنظيم العمراني وقيمته السوقية. يبلغ مبلغ القرض بحد أقصى 90% من القيمة الواردة في تقرير التقييم؛ لذلك يلزمكم عادةً دفعة أولى لا تقل عن 10% من قيمة العقار. نحسب لكم مرحلة التقييم هذه وسقف القرض الواقعي مسبقاً لنوضّح خطة ميزانيتكم. ونعرض من البداية التكاليف الإضافية مثل رسم تخصيص القرض (عادةً 5 في الألف من مبلغ القرض) ورسم التقييم، لنجنّبكم المفاجآت. تُنجَز عملية الطلب في المتوسط خلال 5-7 أيام عمل؛ ونختصر هذه المدة قدر الإمكان بإعداد الأوراق والتنسيق مع البنك. كما نرشدكم في اختيار ما يناسب ملف مخاطركم بين خياري الفائدة الثابتة والمتغيرة."},"Kredi uygunluk & bütçe analizi":{"en":"Loan eligibility & budget analysis","ru":"Анализ кредитоспособности и бюджета","zh":"贷款资格与预算分析","ar":"تحليل أهلية القرض والميزانية"},"Banka ve faiz karşılaştırması":{"en":"Bank and interest comparison","ru":"Сравнение банков и ставок","zh":"银行与利率比较","ar":"مقارنة البنوك والفائدة"},"Peşinat & kredi tavanı hesabı":{"en":"Down payment & loan ceiling calculation","ru":"Расчёт первоначального взноса и лимита кредита","zh":"首付与贷款上限计算","ar":"حساب الدفعة الأولى وسقف القرض"},"Ekspertiz sürecinin takibi":{"en":"Follow-up of the appraisal process","ru":"Сопровождение процесса оценки","zh":"估价流程的跟进","ar":"متابعة عملية التقييم"},"Evrak hazırlığı & başvuru":{"en":"Document preparation & application","ru":"Подготовка документов и подача заявки","zh":"文件准备与申请","ar":"إعداد الأوراق والطلب"},"Onay ve kullandırım":{"en":"Approval and disbursement","ru":"Одобрение и выдача","zh":"审批与放款","ar":"الموافقة والصرف"},"Birden fazla bankanın faiz ve maliyeti karşılaştırılarak en uygun seçenek sunulur.":{"en":"By comparing the interest and costs of several banks, the most suitable option is presented.","ru":"Сравнивая ставки и издержки нескольких банков, мы предлагаем наиболее подходящий вариант.","zh":"通过比较多家银行的利率和成本，提供最合适的选项。","ar":"تُقدَّم أنسب الخيارات عبر مقارنة فائدة وتكاليف عدة بنوك."},"Ekspertiz değeri ve kredi tavanı önceden hesaplanır, bütçeniz gerçekçi kurulur.":{"en":"The appraisal value and loan ceiling are calculated in advance, so your budget is set realistically.","ru":"Стоимость по оценке и лимит кредита рассчитываются заранее, ваш бюджет выстраивается реалистично.","zh":"提前计算估价值和贷款上限，让您的预算切合实际。","ar":"تُحسَب قيمة التقييم وسقف القرض مسبقاً، وتُبنى ميزانيتكم بشكل واقعي."},"Tahsis ve ekspertiz ücretleri dahil tüm maliyetler baştan şeffaf paylaşılır.":{"en":"All costs, including allocation and appraisal fees, are shared transparently from the outset.","ru":"Все издержки, включая комиссию за выдачу и плату за оценку, прозрачно сообщаются заранее.","zh":"包括发放费和估价费在内的全部成本从一开始透明告知。","ar":"تُشارَك جميع التكاليف بما فيها رسوم التخصيص والتقييم بشفافية من البداية."},"Ne kadar peşinat gerekir?":{"en":"How much down payment is required?","ru":"Какой первоначальный взнос требуется?","zh":"需要多少首付？","ar":"كم يلزم من دفعة أولى؟"},"Kredi, ekspertiz değerinin en fazla yüzde 90'ı kadar çıktığı için genelde mülk değerinin en az yüzde 10'u kadar peşinat gerekir. Devlet destekli kampanyalarda oranlar değişebilir.":{"en":"Because the loan can be up to at most 90% of the appraisal value, a down payment of at least 10% of the property's value is generally required. Rates may change under state-backed campaigns.","ru":"Поскольку кредит составляет не более 90% от стоимости по оценке, обычно требуется первоначальный взнос не менее 10% от стоимости объекта. В государственных льготных программах пропорции могут меняться.","zh":"由于贷款最多为估价值的 90%，通常需要房产价值至少 10% 的首付。在政府支持的活动中，比例可能有所不同。","ar":"بما أن القرض يبلغ بحد أقصى 90% من قيمة التقييم، يلزم عادةً دفعة أولى لا تقل عن 10% من قيمة العقار. وقد تتغير النسب في الحملات المدعومة حكومياً."},"Kredi süreci ne kadar sürer?":{"en":"How long does the loan process take?","ru":"Сколько длится процесс получения кредита?","zh":"贷款流程需要多久？","ar":"كم تستغرق عملية القرض؟"},"Evraklar tamamsa ortalama 5-7 iş günü içinde sonuçlanır. Ekspertiz ve evrak koordinasyonunu üstlenerek bu süreyi kısaltmaya çalışırız.":{"en":"If the documents are complete, it is concluded within an average of 5-7 business days. By taking on the appraisal and document coordination, we try to shorten this time.","ru":"Если документы в порядке, он завершается в среднем за 5-7 рабочих дней. Беря на себя координацию оценки и документов, мы стараемся сократить этот срок.","zh":"若文件齐全，平均在 5-7 个工作日内完成。我们承担估价和文件协调，努力缩短这一时间。","ar":"إذا اكتملت الأوراق تُنجَز في المتوسط خلال 5-7 أيام عمل. ونسعى لاختصار هذه المدة بتولّي تنسيق التقييم والأوراق."},"Portföy Yönetimi":{"en":"Portfolio Management","ru":"Управление портфелем","zh":"投资组合管理","ar":"إدارة المحفظة"},"Birden fazla gayrimenkule sahip olmak, tek başına bir gelir garantisi değildir; asıl kazanç, portföyün profesyonel yönetiminden gelir. Gayrimenkul portföy yönetimi, sahip olunan mülklerin değerini artırmak ve kira-yatırım süreçlerini optimize etmek için uygulanan bütünsel bir süreçtir. Meridyen Gayrimenkul, mülk takibi, kira ve gelir yönetimi, bakım ve operasyon yönetimi, finansal analiz-raporlama ile risk yönetimini tek çatı altında toplar. Her mülkünüzün kira geliri, boşluk süresi, bakım maliyeti ve piyasa değeri düzenli olarak izlenir ve size sade raporlar halinde sunulur. Hangi mülkün elde tutulması, hangisinin satılıp yeniden değerlendirilmesi gerektiğini veriyle gösterir; portföyünüzü bölge ve varlık türü açısından çeşitlendirerek riski dağıtırız. Böylece gelir akışınız hem düzenli hem de büyümeye açık hale gelir. Birden fazla mülkün kirasını tek panelden izleyebileceğiniz dijital takip, vergi ve aidat yükümlülüklerinin zamanında hatırlatılması, bakım-onarım süreçlerinin koordinasyonu ve gerektiğinde yeni yatırım fırsatlarının önünüze getirilmesi bu hizmetin parçasıdır. Amacımız, mülk sahibi olmanın getirdiği operasyonel yükü sizden alıp, sizi yalnızca stratejik kararlarla ilgilenen bir yatırımcı konumuna taşımaktır.":{"en":"Owning more than one property is not, on its own, a guarantee of income; the real gain comes from professional management of the portfolio. Real estate portfolio management is a holistic process applied to increase the value of the owned properties and to optimize rental-investment processes. Meridyen Gayrimenkul brings together property tracking, rent and income management, maintenance and operations management, financial analysis-reporting and risk management under one roof. Each of your properties' rental income, vacancy period, maintenance cost and market value is monitored regularly and presented to you in clear reports. We show with data which property should be held and which should be sold and reallocated; we spread risk by diversifying your portfolio across regions and asset types. This makes your income flow both steady and open to growth. Digital tracking that lets you monitor the rent of multiple properties from a single panel, timely reminders of tax and dues obligations, coordination of maintenance-repair processes and, when needed, bringing new investment opportunities to you are part of this service. Our aim is to take the operational burden of property ownership off you and move you into the position of an investor concerned only with strategic decisions.","ru":"Владение несколькими объектами недвижимости само по себе не является гарантией дохода; настоящий выигрыш приходит от профессионального управления портфелем. Управление портфелем недвижимости — это целостный процесс, применяемый для повышения стоимости имеющихся объектов и оптимизации арендных и инвестиционных процессов. Meridyen Gayrimenkul объединяет под одной крышей контроль объектов, управление арендой и доходом, управление обслуживанием и операциями, финансовый анализ и отчётность, а также управление рисками. Доход от аренды, срок простоя, стоимость обслуживания и рыночная стоимость каждого вашего объекта регулярно отслеживаются и предоставляются вам в виде понятных отчётов. Мы на основе данных показываем, какой объект стоит удерживать, а какой — продать и переоценить; диверсифицируя ваш портфель по региону и типу актива, мы распределяем риск. Так ваш поток дохода становится и регулярным, и открытым для роста. Частью этой услуги являются цифровой мониторинг, позволяющий отслеживать аренду нескольких объектов с единой панели, своевременное напоминание о налоговых обязательствах и взносах, координация процессов обслуживания и ремонта и вынесение вам новых инвестиционных возможностей при необходимости. Наша цель — снять с вас операционную нагрузку, которую несёт владение недвижимостью, и перевести вас в положение инвестора, занимающегося только стратегическими решениями.","zh":"拥有多套房产，本身并不构成收入的保证；真正的收益来自投资组合的专业管理。房产投资组合管理是一套为提升所持房产价值、优化租赁-投资流程而实施的整体化流程。Meridyen Gayrimenkul 将房产跟踪、租金和收入管理、维护和运营管理、财务分析-报告以及风险管理汇集于同一屋檐下。您每套房产的租金收入、空置时长、维护成本和市场价值都会被定期监测，并以简明报告呈交给您。我们以数据向您展示应持有哪套房产、应卖出并重新配置哪套；通过在区域和资产类型上使您的投资组合多元化来分散风险。由此，您的收入流既稳定又向增长敞开。在单一面板中监测多套房产租金的数字化跟踪、对税费和物业费义务的及时提醒、维护维修流程的协调，以及在必要时把新的投资机会呈现在您面前，都是这项服务的一部分。我们的目标是把拥有房产所带来的运营负担从您身上卸下，让您成为只需关注战略决策的投资者。","ar":"امتلاك أكثر من عقار ليس وحده ضماناً للدخل؛ فالربح الحقيقي يأتي من الإدارة الاحترافية للمحفظة. وإدارة المحفظة العقارية عملية شاملة تُطبَّق لزيادة قيمة العقارات المملوكة وتحسين عمليات الإيجار والاستثمار. تجمع Meridyen Gayrimenkul تحت سقف واحد متابعة العقار وإدارة الإيجار والدخل وإدارة الصيانة والتشغيل والتحليل المالي والتقارير مع إدارة المخاطر. يُراقَب بانتظام دخل إيجار كل عقار من عقاراتكم ومدة شغوره وتكلفة صيانته وقيمته السوقية، ويُقدَّم لكم في صورة تقارير مبسّطة. ونُظهر بالبيانات أي عقار ينبغي الاحتفاظ به وأيها ينبغي بيعه وإعادة تقييمه؛ ونوزّع المخاطر بتنويع محفظتكم من حيث المنطقة ونوع الأصل. وهكذا يصبح تدفق دخلكم منتظماً وقابلاً للنمو معاً. ومن أجزاء هذه الخدمة: المتابعة الرقمية التي تتيح لكم رصد إيجار عدة عقارات من لوحة واحدة، والتذكير في الوقت المناسب بالتزامات الضريبة ورسوم الإدارة، وتنسيق عمليات الصيانة والإصلاح، وعرض فرص استثمارية جديدة أمامكم عند اللزوم. هدفنا أن نرفع عنكم العبء التشغيلي الناجم عن ملكية العقار، وننقلكم إلى موقع مستثمر يُعنى بالقرارات الاستراتيجية فقط."},"Portföy envanteri & durum tespiti":{"en":"Portfolio inventory & status assessment","ru":"Инвентаризация портфеля и оценка состояния","zh":"投资组合盘点与状况评定","ar":"جرد المحفظة وتحديد الحالة"},"Getiri ve boşluk analizi":{"en":"Return and vacancy analysis","ru":"Анализ доходности и простоя","zh":"收益与空置分析","ar":"تحليل العائد والشغور"},"Kira & gider yönetimi kurulumu":{"en":"Rent & expense management setup","ru":"Настройка управления арендой и расходами","zh":"租金与支出管理搭建","ar":"إعداد إدارة الإيجار والنفقات"},"Bakım/operasyon koordinasyonu":{"en":"Maintenance/operations coordination","ru":"Координация обслуживания/операций","zh":"维护/运营协调","ar":"تنسيق الصيانة/التشغيل"},"Periyodik performans raporu":{"en":"Periodic performance report","ru":"Периодический отчёт о результатах","zh":"定期业绩报告","ar":"تقرير أداء دوري"},"Optimizasyon ve yeniden yatırım":{"en":"Optimization and reinvestment","ru":"Оптимизация и реинвестирование","zh":"优化与再投资","ar":"التحسين وإعادة الاستثمار"},"Tüm mülklerin kira, gider ve değer performansı düzenli ve sade raporlarla sunulur.":{"en":"The rent, expense and value performance of all properties is presented in regular, clear reports.","ru":"Показатели аренды, расходов и стоимости всех объектов предоставляются регулярными и понятными отчётами.","zh":"所有房产的租金、支出和价值表现以定期且简明的报告呈现。","ar":"يُقدَّم أداء الإيجار والنفقات والقيمة لجميع العقارات بتقارير منتظمة ومبسّطة."},"Portföy risk dağılımı bölge ve varlık türüne göre çeşitlendirilerek yönetilir.":{"en":"Portfolio risk distribution is managed by diversifying across regions and asset types.","ru":"Распределение риска портфеля управляется через диверсификацию по региону и типу актива.","zh":"投资组合风险分布按区域和资产类型多元化管理。","ar":"يُدار توزيع مخاطر المحفظة بالتنويع حسب المنطقة ونوع الأصل."},"Vergi, aidat ve bakım yükümlülükleri zamanında hatırlatılıp koordine edilir.":{"en":"Tax, dues and maintenance obligations are reminded and coordinated in a timely manner.","ru":"О налоговых обязательствах, взносах и обслуживании своевременно напоминают и координируют их.","zh":"税费、物业费和维护义务及时提醒并协调。","ar":"يُذكَّر بالتزامات الضريبة ورسوم الإدارة والصيانة في الوقت المناسب وتُنسَّق."},"Kaç mülkten sonra portföy yönetimi mantıklı olur?":{"en":"After how many properties does portfolio management make sense?","ru":"С какого количества объектов управление портфелем становится разумным?","zh":"拥有多少套房产后，投资组合管理才合理？","ar":"بعد كم عقار تصبح إدارة المحفظة منطقية؟"},"Birden fazla mülkte bile takip yükü hızla artar. İki-üç mülkten itibaren profesyonel yönetim, hem zaman hem getiri açısından fark yaratmaya başlar.":{"en":"Even with more than one property, the tracking burden grows quickly. From two or three properties onward, professional management begins to make a difference in both time and return.","ru":"Уже при нескольких объектах нагрузка по контролю быстро растёт. Начиная с двух-трёх объектов профессиональное управление начинает создавать разницу как во времени, так и в доходности.","zh":"即便只有几套房产，跟踪负担也会迅速增加。从两三套房产起，专业管理便开始在时间和收益上带来差别。","ar":"حتى مع أكثر من عقار يزداد عبء المتابعة بسرعة. واعتباراً من عقارين إلى ثلاثة تبدأ الإدارة الاحترافية في إحداث فرق من حيث الوقت والعائد معاً."},"Mülklerimi satmadan da yönetiyor musunuz?":{"en":"Do you manage my properties without selling them too?","ru":"Вы управляете моими объектами и без их продажи?","zh":"在不卖出我房产的情况下，你们也管理吗？","ar":"هل تديرون عقاراتي دون بيعها أيضاً؟"},"Evet. Amacımız satış değil, portföyünüzün getirisini artırmaktır. Satış yalnızca veriler bir mülkü elde tutmanın verimsiz olduğunu gösterdiğinde önerilir.":{"en":"Yes. Our aim is not to sell but to increase your portfolio's return. A sale is recommended only when the data show that holding a property is inefficient.","ru":"Да. Наша цель — не продажа, а повышение доходности вашего портфеля. Продажа рекомендуется только тогда, когда данные показывают, что удерживать объект неэффективно.","zh":"是的。我们的目标不是卖出，而是提升您投资组合的收益。只有当数据表明持有某套房产效率低下时，才会建议卖出。","ar":"نعم. هدفنا ليس البيع بل زيادة عائد محفظتكم. ولا يُقترَح البيع إلا عندما تُظهر البيانات أن الاحتفاظ بعقار غير مجدٍ."},"Satışa Hazırlık":{"en":"Sale Preparation","ru":"Подготовка к продаже","zh":"售前准备","ar":"الإعداد للبيع"},"Alıcıların çoğu bir evi artık sokakta değil ekranda, fotoğraflara bakarak değerlendiriyor; ilk izlenim satış hızını doğrudan belirliyor. Home staging, mülkü alıcı veya kiracı için en cazip hale getirme sürecidir ve doğru uygulandığında hem satış süresini kısaltır hem de algılanan değeri yükseltir. Meridyen Gayrimenkul, mülkünüzü satışa çıkmadan önce görsel ve fonksiyonel olarak hazırlar. Süreç; profesyonel temizlik, fazla eşyaların kaldırılarak ferah ve geniş bir algı yaratılması, bej-gri-beyaz gibi geniş kitleye hitap eden nötr tonların öne çıkarılması ve mobilyanın alanı daraltmayacak şekilde yeniden düzenlenmesini kapsar. Küçük ama etkili tadilat ve bakım önerileriyle mülkün zayıf noktalarını güçlü yönlere çeviririz. Ardından profesyonel fotoğrafçıyla doğru ışık, açı ve kompozisyonda çekim yaparız. Bunu hedefli dijital pazarlama tamamlar: portal ilanları, sosyal medya ve Meta reklamlarıyla mülkünüz doğru alıcı kitlesinin karşısına çıkar. Doğru satış zamanlaması da stratejinin parçasıdır; piyasanın hareketli olduğu dönemlerde çıkış yapmak sonucu iyileştirir. Tüm bunların temelinde ise en kritik adım olan doğru fiyatlandırma vardır; çünkü satılamayan evlerin çoğu piyasa değerinin üzerinde fiyatlanmış evlerdir.":{"en":"Most buyers now assess a home not on the street but on a screen, by looking at photos; the first impression directly determines the speed of sale. Home staging is the process of making a property as attractive as possible for a buyer or tenant, and when done right it both shortens the sale time and raises the perceived value. Meridyen Gayrimenkul prepares your property visually and functionally before it goes on sale. The process covers professional cleaning, removing excess items to create a sense of airiness and spaciousness, bringing forward neutral tones such as beige-grey-white that appeal to a broad audience, and rearranging the furniture so that it does not narrow the space. With small but effective renovation and maintenance suggestions, we turn the property's weak points into strong ones. Then, with a professional photographer, we shoot in the right light, angle and composition. Targeted digital marketing completes this: with portal listings, social media and Meta ads, your property comes before the right buyer audience. The right sale timing is also part of the strategy; going to market when the market is active improves the outcome. And at the foundation of all this lies the most critical step, correct pricing; because most homes that do not sell are homes priced above market value.","ru":"Большинство покупателей оценивают дом теперь не на улице, а на экране, глядя на фотографии; первое впечатление напрямую определяет скорость продажи. Home staging — это процесс придания объекту максимальной привлекательности для покупателя или арендатора, и при правильном применении он и сокращает срок продажи, и повышает воспринимаемую стоимость. Meridyen Gayrimenkul визуально и функционально готовит вашу недвижимость перед выходом на продажу. Процесс включает профессиональную уборку, создание ощущения простора и объёма за счёт удаления лишних вещей, акцент на нейтральных тонах, привлекательных для широкой аудитории, — бежевом, сером, белом — и перестановку мебели так, чтобы она не сужала пространство. С помощью небольших, но эффективных рекомендаций по ремонту и обслуживанию мы превращаем слабые стороны объекта в сильные. Затем мы проводим съёмку с профессиональным фотографом при правильном свете, ракурсе и композиции. Это дополняет таргетированный цифровой маркетинг: с помощью объявлений на порталах, социальных сетей и рекламы Meta ваш объект предстаёт перед правильной аудиторией покупателей. Правильный выбор времени продажи также часть стратегии; выход на рынок в периоды его активности улучшает результат. В основе всего этого лежит самый важный шаг — правильное ценообразование; ведь большинство непроданных домов — это дома, оценённые выше рыночной стоимости.","zh":"如今多数买家不再是在街上、而是在屏幕上看着照片来评估一套房；第一印象直接决定销售速度。Home staging 是让房产对买家或租客最具吸引力的过程，正确实施时既能缩短销售时间，又能提升被感知的价值。Meridyen Gayrimenkul 在您的房产挂牌前，从视觉和功能上加以准备。流程包括：专业清洁，移除多余物品以营造宽敞开阔的观感，突出米色-灰色-白色等迎合广泛受众的中性色调，以及重新布置家具使其不压缩空间。我们以虽小却有效的翻修和维护建议，把房产的薄弱之处转为强项。随后由专业摄影师以正确的光线、角度和构图拍摄。精准的数字营销随之补足：通过门户网站挂牌、社交媒体和 Meta 广告，让您的房产出现在正确的买家群体面前。正确的销售时机也是策略的一部分；在市场活跃期出手会改善结果。而这一切的基础，是最关键的一步——正确定价；因为卖不出去的房子多数是定价高于市场价值的房子。","ar":"صار معظم المشترين يقيّمون المنزل اليوم على الشاشة عبر الصور لا في الشارع؛ والانطباع الأول يحدّد مباشرةً سرعة البيع. والـ Home Staging هو عملية جعل العقار في أكثر صوره جاذبيةً للمشتري أو المستأجر، وإذا طُبِّق بشكل صحيح فإنه يختصر مدة البيع ويرفع القيمة المدرَكة معاً. تُهيّئ Meridyen Gayrimenkul عقاركم بصرياً ووظيفياً قبل طرحه للبيع. تشمل العملية التنظيف الاحترافي، وخلق إحساس بالرحابة والاتساع بإزالة الأغراض الزائدة، وإبراز الألوان المحايدة التي تخاطب جمهوراً واسعاً مثل البيج والرمادي والأبيض، وإعادة ترتيب الأثاث بما لا يضيّق المساحة. ونحوّل نقاط ضعف العقار إلى نقاط قوة باقتراحات ترميم وصيانة صغيرة لكن فعّالة. ثم نلتقط الصور مع مصوّر محترف بالإضاءة والزاوية والتكوين الصحيح. ويكمّل ذلك تسويق رقمي مستهدف: بإعلانات البوابات ووسائل التواصل وإعلانات Meta يظهر عقاركم أمام جمهور المشترين الصحيح. وتوقيت البيع الصحيح جزء من الاستراتيجية أيضاً؛ فالطرح في فترات حركة السوق يحسّن النتيجة. وفي أساس كل ذلك تأتي الخطوة الأكثر حسماً وهي التسعير الصحيح؛ لأن معظم المنازل التي لا تُباع هي منازل مُسعّرة فوق قيمتها السوقية."},"Mülk ön değerlendirme & eksik tespiti":{"en":"Property pre-assessment & shortfall identification","ru":"Предварительная оценка объекта и выявление недостатков","zh":"房产初步评估与缺陷查明","ar":"التقييم المبدئي للعقار وتحديد النواقص"},"Temizlik & sadeleştirme":{"en":"Cleaning & decluttering","ru":"Уборка и упрощение обстановки","zh":"清洁与精简","ar":"التنظيف والتبسيط"},"Nötr düzenleme / mini iyileştirme":{"en":"Neutral styling / minor improvement","ru":"Нейтральное оформление / небольшие улучшения","zh":"中性布置／微改善","ar":"التنسيق المحايد / التحسين الصغير"},"Profesyonel fotoğraf & sunum":{"en":"Professional photography & presentation","ru":"Профессиональные фотографии и презентация","zh":"专业摄影与呈现","ar":"التصوير الاحترافي والعرض"},"İlan metni ve hedefli pazarlama":{"en":"Listing copy and targeted marketing","ru":"Текст объявления и таргетированный маркетинг","zh":"挂牌文案与精准营销","ar":"نص الإعلان والتسويق المستهدف"},"Gösterim & geri bildirim":{"en":"Viewing & feedback","ru":"Показ и обратная связь","zh":"带看与反馈","ar":"المعاينة والتغذية الراجعة"},"Profesyonel fotoğraf ve sunumla mülkünüz rakip ilanlardan öne çıkar.":{"en":"With professional photography and presentation, your property stands out from competing listings.","ru":"Благодаря профессиональным фотографиям и презентации ваш объект выделяется среди конкурирующих объявлений.","zh":"通过专业摄影和呈现，让您的房产在竞争挂牌中脱颖而出。","ar":"يبرز عقاركم بين الإعلانات المنافسة بالتصوير الاحترافي والعرض."},"Düzenleme önerileri düşük maliyet-yüksek etki ilkesiyle sunulur, gereksiz masraf yaptırılmaz.":{"en":"Styling suggestions are offered on a low-cost, high-impact principle; no unnecessary expense is imposed.","ru":"Рекомендации по оформлению даются по принципу «низкие затраты — высокий эффект», без лишних расходов.","zh":"布置建议以低成本-高效果为原则提出，不让您做不必要的花费。","ar":"تُقدَّم اقتراحات التنسيق بمبدأ التكلفة المنخفضة والأثر العالي، دون تحميلكم نفقات غير ضرورية."},"Doğru fiyatlandırma ile piyasa üzeri fiyattan kaynaklanan bekleme riski azaltılır.":{"en":"With correct pricing, the waiting risk arising from above-market pricing is reduced.","ru":"Правильное ценообразование снижает риск простоя из-за завышенной относительно рынка цены.","zh":"通过正确定价，降低因高于市场定价而带来的等待风险。","ar":"يُقلَّل خطر الانتظار الناجم عن السعر فوق السوق عبر التسعير الصحيح."},"Home staging masraflı mı?":{"en":"Is home staging expensive?","ru":"Дорого ли обходится home staging?","zh":"Home staging 花费大吗？","ar":"هل الـ Home Staging مكلف؟"},"Genelde büyük tadilat değil, temizlik, sadeleştirme ve doğru sunum gerektirir. Küçük yatırım, çoğu zaman satış fiyatına ve hızına belirgin şekilde geri döner.":{"en":"It generally requires not major renovation but cleaning, decluttering and correct presentation. A small investment usually returns noticeably in the sale price and speed.","ru":"Обычно он требует не крупного ремонта, а уборки, упрощения обстановки и правильной презентации. Небольшие вложения чаще всего заметно окупаются в цене и скорости продажи.","zh":"通常不需要大规模翻修，而是需要清洁、精简和正确的呈现。小额投入往往会在成交价格和速度上明显回报。","ar":"لا يتطلب عادةً ترميماً كبيراً، بل تنظيفاً وتبسيطاً وعرضاً صحيحاً. والاستثمار الصغير يعود غالباً بوضوح على سعر البيع وسرعته."},"Boş evde de home staging işe yarar mı?":{"en":"Does home staging work in an empty home too?","ru":"Работает ли home staging и в пустом доме?","zh":"在空置的房子里，home staging 也有用吗？","ar":"هل ينفع الـ Home Staging في المنزل الفارغ أيضاً؟"},"Evet. Boş ev soğuk ve küçük algılanabilir; temel sahneleme ve profesyonel fotoğraf, mekanı yaşanabilir ve ferah gösterip alıcı ilgisini artırır.":{"en":"Yes. An empty home can feel cold and small; basic staging and professional photography make the space look livable and airy, increasing buyer interest.","ru":"Да. Пустой дом может восприниматься холодным и маленьким; базовая постановка и профессиональная съёмка показывают пространство пригодным для жизни и просторным и повышают интерес покупателей.","zh":"有用。空房可能给人冷清而狭小的感觉；基本的陈列和专业摄影能让空间显得宜居而宽敞，提升买家兴趣。","ar":"نعم. قد يُدرَك المنزل الفارغ بارداً وصغيراً؛ والتهيئة الأساسية والتصوير الاحترافي يُظهران المكان قابلاً للعيش ورحباً ويزيدان اهتمام المشتري."},"Kentsel Dönüşüm":{"en":"Urban Regeneration","ru":"Городская реновация","zh":"城市更新","ar":"التحول الحضري"},"İzmir, 30 Ekim 2020 depreminin ardından kentsel dönüşümde Türkiye'nin en aktif şehirlerinden biri haline geldi; Bayraklı, Buca, Bornova, Karabağlar, Konak ve Gaziemir gibi ilçelerde dönüşüm hızla ilerliyor. Meridyen Gayrimenkul, mülk sahiplerini bu karmaşık sürecin her aşamasında yönlendirir: riskli yapı tespiti (6306 sayılı Kanun kapsamında), hak sahipliğinin belirlenmesi, kat maliklerinin haklarının korunması ve müteahhitle yapılacak sözleşmenin adil müzakeresi. Devletin sunduğu desteklerden tam yararlanmanızı sağlarız. Yarısı Bizden kampanyası kapsamında riskli konut ve iş yerlerinin dönüşümü için düşük faizli proje kredisi, kira yardımı, taşınma yardımı ve geçici konut desteği sağlanmaktadır; İzmir Büyükşehir Belediyesi'nin imar teşvikleri buna eklenir. Hangi desteğe hak kazandığınızı ve başvuru sürecini net olarak açıklarız. Yeni proje danışmanlığında ise güvenilir müteahhit ve markalı proje seçimi, kat karşılığı sözleşmelerinde metrekare, kat ve teslim şartlarının müzakeresi, teslim garantileri ve depreme dayanıklı yapı standartlarının denetimi konularında yol gösteririz. Amacımız, dönüşümü mülk sahibi için bir belirsizlik değil, güvenli ve değer artıran bir yatırım fırsatına dönüştürmektir.":{"en":"After the 30 October 2020 earthquake, İzmir became one of Turkey's most active cities in urban regeneration; regeneration is advancing rapidly in districts such as Bayraklı, Buca, Bornova, Karabağlar, Konak and Gaziemir. Meridyen Gayrimenkul guides property owners through every stage of this complex process: risky-building assessment (under Law No. 6306), determination of rights-holder status, protection of the co-owners' rights, and fair negotiation of the contract to be made with the contractor. We ensure that you fully benefit from the support the state offers. Under the Yarısı Bizden campaign, low-interest project loans, rent assistance, moving assistance and temporary housing support are provided for the transformation of risky residences and workplaces; İzmir Metropolitan Municipality's zoning incentives are added to these. We explain clearly which support you qualify for and the application process. In new-project advisory, we guide you on choosing a reliable contractor and a branded project, negotiating the square meters, floors and delivery terms in construction-in-return (kat karşılığı) contracts, delivery guarantees and the inspection of earthquake-resistant building standards. Our aim is to turn the transformation into a safe, value-adding investment opportunity for the owner rather than an uncertainty.","ru":"После землетрясения 30 октября 2020 года Измир стал одним из самых активных городов Турции в сфере городской реновации; в округах Bayraklı, Buca, Bornova, Karabağlar, Konak и Gaziemir реновация продвигается быстро. Meridyen Gayrimenkul направляет собственников на каждом этапе этого сложного процесса: признание здания аварийным (в рамках Закона № 6306), определение прав собственности, защита прав владельцев квартир и справедливые переговоры по договору с застройщиком. Мы обеспечиваем вам полное использование предоставляемых государством субсидий. В рамках программы Yarısı Bizden для реновации аварийного жилья и коммерческих помещений предоставляются льготный проектный кредит, помощь на аренду, помощь на переезд и временное жильё; к этому добавляются стимулы по зонированию от муниципалитета Большого Измира. Мы чётко объясняем, на какую субсидию вы имеете право, и процесс подачи заявки. В консультациях по новым проектам мы направляем вас в вопросах выбора надёжного застройщика и брендового проекта, переговоров об условиях по площади, этажам и срокам сдачи в договорах строительства в обмен на долю (kat karşılığı), гарантий сдачи и контроля стандартов сейсмостойкого строительства. Наша цель — превратить реновацию для собственника не в неопределённость, а в безопасную и повышающую стоимость инвестиционную возможность.","zh":"伊兹密尔在 2020年10月30日 地震之后，成为土耳其城市更新最活跃的城市之一；在 Bayraklı、Buca、Bornova、Karabağlar、Konak 和 Gaziemir 等区县，更新正快速推进。Meridyen Gayrimenkul 在这一复杂流程的每个阶段为业主指引方向：危房鉴定（在第6306号法律框架下）、权属确定、区分所有权人权利的保护，以及与承建商所签合同的公平谈判。我们确保您充分利用国家提供的补助。在 Yarısı Bizden 活动框架下，为危险住宅和营业场所的更新提供低息项目贷款、租金补助、搬迁补助和临时住房支持；伊兹密尔都市自治市的规划激励也在此之列。我们清楚地说明您有资格获得哪些补助以及申请流程。在新项目顾问方面，我们在可靠承建商和品牌项目的选择、以楼换地（kat karşılığı）合同中面积、楼层和交付条件的谈判、交付担保以及抗震建筑标准的监督等方面为您指引。我们的目标是把更新对业主而言从一种不确定，转变为安全且增值的投资机会。","ar":"صارت إزمير بعد زلزال 30 أكتوبر 2020 من أنشط مدن تركيا في التحول الحضري؛ ويمضي التحول بسرعة في أقضية مثل Bayraklı وBuca وBornova وKarabağlar وKonak وGaziemir. تُرشد Meridyen Gayrimenkul مالكي العقارات في كل مرحلة من هذه العملية المعقّدة: تحديد المبنى المعرّض للخطر (في نطاق القانون رقم 6306)، وإثبات الاستحقاق، وحماية حقوق ملّاك الطبقات، والتفاوض العادل على العقد مع المقاول. ونضمن استفادتكم الكاملة من الدعم الذي تقدّمه الدولة. ففي إطار حملة Yarısı Bizden يُقدَّم لتحويل المساكن وأماكن العمل المعرّضة للخطر قرض مشروع منخفض الفائدة ومساعدة إيجار ومساعدة انتقال ودعم سكن مؤقت؛ وتُضاف إليها حوافز التنظيم العمراني من بلدية إزمير الكبرى. ونوضّح بجلاء أي دعم تستحقونه وعملية التقديم. أما في استشارات المشاريع الجديدة فنرشدكم في اختيار المقاول الموثوق والمشروع ذي العلامة، والتفاوض على المتر المربع والطابق وشروط التسليم في عقود البناء مقابل حصة (kat karşılığı)، وضمانات التسليم، ومراقبة معايير البناء المقاوم للزلازل. هدفنا أن نحوّل التحول من حالة عدم يقين لمالك العقار إلى فرصة استثمارية آمنة ورافعة للقيمة."},"Riskli yapı tespiti yönlendirmesi":{"en":"Referral for risky-building assessment","ru":"Направление на признание здания аварийным","zh":"危房鉴定转介","ar":"الإرشاد إلى تحديد المبنى المعرّض للخطر"},"Hak sahipliği & pay analizi":{"en":"Rights-holder status & share analysis","ru":"Анализ прав собственности и долей","zh":"权属与份额分析","ar":"تحليل الاستحقاق والحصص"},"Müteahhit / proje değerlendirmesi":{"en":"Contractor / project evaluation","ru":"Оценка застройщика / проекта","zh":"承建商／项目评估","ar":"تقييم المقاول / المشروع"},"Kat karşılığı sözleşme müzakeresi":{"en":"Construction-in-return (kat karşılığı) contract negotiation","ru":"Переговоры по договору строительства в обмен на долю (kat karşılığı)","zh":"以楼换地（kat karşılığı）合同谈判","ar":"التفاوض على عقد البناء مقابل حصة (kat karşılığı)"},"Devlet desteği & kredi başvurusu":{"en":"State support & loan application","ru":"Государственная субсидия и заявка на кредит","zh":"国家补助与贷款申请","ar":"الدعم الحكومي وطلب القرض"},"İnşaat takibi & yeni tapu":{"en":"Construction follow-up & new title deed","ru":"Контроль строительства и новый тапу","zh":"施工跟进与新房产证","ar":"متابعة البناء وسند الملكية الجديد"},"6306 sayılı Kanun kapsamındaki tüm haklarınız ve devlet destekleri net olarak aktarılır.":{"en":"All your rights under Law No. 6306 and the state supports are communicated clearly.","ru":"Все ваши права и государственные субсидии в рамках Закона № 6306 чётко разъясняются.","zh":"第6306号法律框架下您的全部权利和国家补助都会清楚传达。","ar":"تُنقَل بجلاء جميع حقوقكم والدعم الحكومي في نطاق القانون رقم 6306."},"Kat karşılığı sözleşmeleri metrekare, teslim ve garanti maddeleriyle mülk sahibi lehine müzakere edilir.":{"en":"Construction-in-return (kat karşılığı) contracts are negotiated in the owner's favor with square-meter, delivery and guarantee clauses.","ru":"Договоры строительства в обмен на долю (kat karşılığı) обсуждаются в пользу собственника с положениями о площади, сроках сдачи и гарантиях.","zh":"以楼换地（kat karşılığı）合同就面积、交付和担保条款以有利于业主的方式谈判。","ar":"يُتفاوَض على عقود البناء مقابل حصة (kat karşılığı) لصالح مالك العقار ببنود المتر المربع والتسليم والضمان."},"Müteahhit ve proje seçiminde güvenilirlik ve depreme dayanıklılık öne alınır.":{"en":"In choosing the contractor and project, reliability and earthquake resistance are prioritized.","ru":"При выборе застройщика и проекта в приоритете надёжность и сейсмостойкость.","zh":"在承建商和项目选择中，可靠性和抗震性被置于优先。","ar":"تُقدَّم الموثوقية ومقاومة الزلازل في اختيار المقاول والمشروع."},"Kentsel dönüşümde kira yardımı alabilir miyim?":{"en":"Can I receive rent assistance in urban regeneration?","ru":"Могу ли я получить помощь на аренду при городской реновации?","zh":"在城市更新中我能获得租金补助吗？","ar":"هل يمكنني الحصول على مساعدة إيجار في التحول الحضري؟"},"Riskli yapı olarak tespit edilen binalarda mülk sahipleri kira yardımı, taşınma yardımı ve Yarısı Bizden kapsamında düşük faizli kredi gibi desteklerden yararlanabilir; uygunluğunuzu birlikte değerlendiririz.":{"en":"In buildings assessed as risky, owners can benefit from supports such as rent assistance, moving assistance and, under Yarısı Bizden, low-interest loans; we assess your eligibility together.","ru":"В зданиях, признанных аварийными, собственники могут воспользоваться такими субсидиями, как помощь на аренду, помощь на переезд и льготный кредит в рамках Yarısı Bizden; вашу правомочность мы оценим вместе.","zh":"在被鉴定为危房的建筑中，业主可享受租金补助、搬迁补助以及 Yarısı Bizden 框架下的低息贷款等补助；我们会与您一同评估您的资格。","ar":"في المباني المحدَّدة كمعرّضة للخطر يمكن لمالكي العقارات الاستفادة من دعم مثل مساعدة الإيجار ومساعدة الانتقال والقرض منخفض الفائدة في إطار Yarısı Bizden؛ ونُقيّم أهليتكم معاً."},"Kat karşılığında ne kadar pay alırım?":{"en":"How large a share do I get in construction-in-return?","ru":"Какую долю я получу при строительстве в обмен на долю (kat karşılığı)?","zh":"以楼换地我能获得多少份额？","ar":"كم حصة أحصل عليها مقابل البناء (kat karşılığı)؟"},"Pay oranı bölgeye, arsa değerine ve inşaat maliyetine göre değişir. Emsal projeleri ve arsa değerini analiz ederek adil bir oran için müzakereyi sizin adınıza yürütürüz.":{"en":"The share ratio varies according to the region, land value and construction cost. By analyzing comparable projects and the land value, we conduct the negotiation on your behalf for a fair ratio.","ru":"Доля зависит от района, стоимости участка и стоимости строительства. Анализируя сопоставимые проекты и стоимость участка, мы ведём переговоры о справедливой доле от вашего имени.","zh":"份额比例视区域、地块价值和施工成本而异。我们会分析可比项目和地块价值，为争取公平的比例以您的名义进行谈判。","ar":"تختلف نسبة الحصة حسب المنطقة وقيمة الأرض وتكلفة البناء. نُجري التفاوض نيابةً عنكم للوصول إلى نسبة عادلة عبر تحليل المشاريع المماثلة وقيمة الأرض."},"Yabancı Yatırımcı":{"en":"Foreign Investor","ru":"Иностранный инвестор","zh":"外国投资者","ar":"المستثمر الأجنبي"},"Türkiye ve özellikle Ege sahilleri, yabancı yatırımcılar için cazip bir gayrimenkul pazarı; ancak yabancıya satış süreci yerel alımdan farklı, ek adımlar ve mevzuat uyumu gerektirir. Meridyen Gayrimenkul, yabancı alıcılara ve onlara satış yapmak isteyen mülk sahiplerine, tüm sürecin mevzuata uygun ve pürüzsüz ilerlemesi için danışmanlık verir. 400.000 ABD Doları (veya TL karşılığı) değerinde gayrimenkul alan ve 3 yıl satmama taahhüdü veren yabancılar Türk vatandaşlığına başvuru hakkı kazanır; başvuru sahibi, eşi ve 18 yaşından küçük çocukları bu haktan yararlanır. Süreç genelde 6-8 ay sürer ve mülk bulma, SPK lisanslı ekspertiz raporu alma, döviz alım belgesi düzenleme ve uygunluk belgeli tapu devri gibi kritik adımları içerir. Vatandaşlık hedeflemeyen yabancılar ise gayrimenkul alarak kısa dönem oturma izni (ikamet) için başvurabilir. Biz bu süreçte; vatandaşlığa uygun (kat mülkiyeti veya kat irtifakı) nitelikte mülk seçimini doğrular, SPK ekspertizini ve döviz bozdurma belgesini organize eder, tapu devrini ve uygunluk yazısını takip eder, ikamet izni başvurusunda yol gösteririz. Yabancı alıcının askeri bölge kısıtı ve tapu uygunluğu gibi konularını önceden kontrol ederek işlemin reddedilmesini önleriz.":{"en":"Turkey, and especially the Aegean coast, is an attractive real estate market for foreign investors; however, the sale process to foreigners differs from a local purchase and requires additional steps and regulatory compliance. Meridyen Gayrimenkul provides advisory to foreign buyers and to owners wishing to sell to them, so that the entire process proceeds smoothly and in compliance with the legislation. Foreigners who buy real estate worth USD 400,000 (or its TL equivalent) and give an undertaking not to sell for 3 years earn the right to apply for Turkish citizenship; the applicant, their spouse and their children under 18 benefit from this right. The process generally takes 6-8 months and includes critical steps such as finding a property, obtaining an SPK-licensed appraisal report, issuing a foreign-currency purchase certificate and a certified title-deed transfer. Foreigners not aiming for citizenship can apply for a short-term residence permit by buying real estate. In this process we verify the selection of a property of a nature suitable for citizenship (condominium ownership or condominium easement), organize the SPK appraisal and the foreign-currency exchange certificate, follow the title-deed transfer and the certificate of conformity, and guide you in the residence-permit application. By checking matters such as the foreign buyer's military-zone restriction and title-deed eligibility in advance, we prevent the transaction from being rejected.","ru":"Турция, и особенно эгейское побережье, — привлекательный рынок недвижимости для иностранных инвесторов; однако процесс продажи иностранцу отличается от местной покупки и требует дополнительных шагов и соответствия законодательству. Meridyen Gayrimenkul консультирует иностранных покупателей и собственников, желающих им продать, чтобы весь процесс шёл в соответствии с законодательством и без сбоев. Иностранцы, приобретающие недвижимость стоимостью 400 000 долларов США (или эквивалент в TL) и дающие обязательство не продавать её в течение 3 лет, получают право подать заявление на турецкое гражданство; этим правом пользуются заявитель, его супруг(а) и дети младше 18 лет. Процесс обычно занимает 6-8 месяцев и включает такие ключевые шаги, как поиск объекта, получение отчёта об оценке с лицензией SPK, оформление справки о покупке валюты и переоформление тапу со справкой о соответствии. Иностранцы, не нацеленные на гражданство, могут, приобретя недвижимость, подать заявление на краткосрочный вид на жительство (ikamet). В этом процессе мы подтверждаем выбор объекта надлежащего назначения, пригодного для гражданства (kat mülkiyeti или kat irtifakı — этажная собственность или право этажной застройки), организуем оценку SPK и справку о конвертации валюты, сопровождаем переоформление тапу и справку о соответствии, направляем при подаче заявления на вид на жительство. Заранее проверяя такие вопросы, как ограничение военной зоны и пригодность тапу для иностранного покупателя, мы предотвращаем отказ в операции.","zh":"土耳其，尤其是爱琴海地区的海岸，是外国投资者颇具吸引力的房产市场；然而向外国人销售的流程与本地购买不同，需要额外步骤和法规合规。Meridyen Gayrimenkul 为外国买家以及希望向他们出售的业主提供顾问服务，使整个流程合规且顺畅推进。购入价值 40 万美元（或等值 TL）房产并作出 3 年不出售承诺的外国人，可获得申请土耳其国籍的资格；申请人本人、其配偶及 18 岁以下子女均可享此权利。流程通常需 6-8 个月，包含寻找房产、取得 SPK 牌照估价报告、办理换汇证明以及带合规证明的房产证过户等关键步骤。不以入籍为目标的外国人，则可通过购买房产申请短期居留许可（居留）。在此过程中，我们核实符合入籍条件（区分所有权或区分地上权）性质的房产选择，组织 SPK 估价和换汇证明，跟进房产证过户和合规函，并在居留许可申请中为您指引。我们通过提前核查外国买家的军事区限制和房产证合规性等事项，避免手续被驳回。","ar":"تُعد تركيا وسواحل بحر إيجه خصوصاً سوقاً عقارياً جذاباً للمستثمرين الأجانب؛ غير أن عملية البيع للأجنبي تختلف عن الشراء المحلي وتتطلب خطوات إضافية وتوافقاً مع التشريعات. تقدّم Meridyen Gayrimenkul الاستشارة للمشترين الأجانب ولمالكي العقارات الراغبين في البيع لهم، لتسير كامل العملية متوافقةً مع التشريعات وبسلاسة. يكتسب حق التقدم للجنسية التركية الأجانب الذين يشترون عقاراً بقيمة 400,000 دولار أمريكي (أو ما يعادلها بالـ TL) ويقدّمون تعهداً بعدم البيع لمدة 3 سنوات؛ ويستفيد من هذا الحق مقدّم الطلب وزوجه وأولاده دون سن 18 عاماً. تستغرق العملية عادةً 6-8 أشهر وتشمل خطوات حاسمة مثل إيجاد العقار والحصول على تقرير تقييم مرخّص من SPK وإصدار وثيقة شراء العملة ونقل سند الملكية بوثيقة مطابقة. أما الأجانب الذين لا يستهدفون الجنسية فيمكنهم التقدم بشراء عقار للحصول على تصريح إقامة قصير المدى. نحن في هذه العملية نؤكّد اختيار عقار ذي وصف مناسب للجنسية (ملكية طابقية أو حق ارتفاق طابقي)، وننظّم تقييم SPK ووثيقة صرف العملة، ونتابع نقل سند الملكية وكتاب المطابقة، ونرشدكم في طلب تصريح الإقامة. ونمنع رفض المعاملة بفحص أمور المشتري الأجنبي مثل قيد المنطقة العسكرية ومطابقة سند الملكية مسبقاً."},"Uygunluk & mülk kriteri belirleme":{"en":"Eligibility & property criteria determination","ru":"Определение соответствия и критериев объекта","zh":"合规性与房产标准确定","ar":"تحديد المطابقة ومعايير العقار"},"SPK lisanslı ekspertiz raporu":{"en":"SPK-licensed appraisal report","ru":"Отчёт об оценке с лицензией SPK","zh":"SPK 牌照估价报告","ar":"تقرير تقييم مرخّص من SPK"},"Döviz alım belgesi düzenleme":{"en":"Issuing the foreign-currency purchase certificate","ru":"Оформление справки о покупке валюты","zh":"换汇证明办理","ar":"إصدار وثيقة شراء العملة"},"Tapu devri & uygunluk yazısı":{"en":"Title-deed transfer & certificate of conformity","ru":"Переоформление тапу и справка о соответствии","zh":"房产证过户与合规函","ar":"نقل سند الملكية وكتاب المطابقة"},"İkamet izni başvurusu":{"en":"Residence-permit application","ru":"Заявление на вид на жительство","zh":"居留许可申请","ar":"طلب تصريح الإقامة"},"Vatandaşlık başvurusu (opsiyonel)":{"en":"Citizenship application (optional)","ru":"Заявление на гражданство (по желанию)","zh":"入籍申请（可选）","ar":"طلب الجنسية (اختياري)"},"Mülkün vatandaşlığa/uygunluğa elverişli nitelikte olduğu (kat mülkiyeti/irtifakı) baştan doğrulanır.":{"en":"It is verified from the outset that the property is of a nature suitable for citizenship/eligibility (condominium ownership/easement).","ru":"Пригодность объекта для гражданства/соответствия (kat mülkiyeti/irtifakı) подтверждается заранее.","zh":"房产具备入籍/合规资格（区分所有权/区分地上权）的性质从一开始就予以核实。","ar":"يُتحقَّق من البداية من أن العقار ذو وصف صالح للجنسية/المطابقة (ملكية طابقية/حق ارتفاق طابقي)."},"Döviz alım belgesi ve SPK ekspertizi gibi zorunlu adımlar eksiksiz koordine edilir.":{"en":"Mandatory steps such as the foreign-currency purchase certificate and the SPK appraisal are coordinated in full.","ru":"Обязательные шаги, такие как справка о покупке валюты и оценка SPK, полностью координируются.","zh":"换汇证明和 SPK 估价等必需步骤完整协调。","ar":"تُنسَّق كاملةً الخطوات الإلزامية مثل وثيقة شراء العملة وتقييم SPK."},"Askeri bölge ve tapu kısıtı kontrolüyle başvurunun reddedilme riski en aza indirilir.":{"en":"With military-zone and title-deed restriction checks, the risk of the application being rejected is minimized.","ru":"Проверкой военной зоны и ограничений тапу риск отказа по заявлению сводится к минимуму.","zh":"通过军事区和房产证限制核查，把申请被驳回的风险降至最低。","ar":"يُقلَّل خطر رفض الطلب إلى أدنى حد بفحص المنطقة العسكرية وقيد سند الملكية."},"Ne kadarlık alımda vatandaşlık hakkı doğar?":{"en":"At what purchase amount does the right to citizenship arise?","ru":"При какой сумме покупки возникает право на гражданство?","zh":"购买多少金额才产生入籍资格？","ar":"عند أي مبلغ شراء ينشأ حق الجنسية؟"},"400.000 ABD Doları veya TL karşılığı değerinde gayrimenkul alıp 3 yıl satmama taahhüdü veren yabancılar vatandaşlığa başvurabilir; eş ve 18 yaş altı çocuklar da kapsanır.":{"en":"Foreigners who buy real estate worth USD 400,000 or its TL equivalent and give an undertaking not to sell for 3 years can apply for citizenship; the spouse and children under 18 are also covered.","ru":"Иностранцы, приобретающие недвижимость стоимостью 400 000 долларов США или эквивалент в TL и дающие обязательство не продавать её в течение 3 лет, могут подать заявление на гражданство; супруг(а) и дети младше 18 лет также охватываются.","zh":"购入价值 40 万美元或等值 TL 房产并作出 3 年不出售承诺的外国人可申请入籍；配偶及 18 岁以下子女也在涵盖范围内。","ar":"يمكن للأجانب الذين يشترون عقاراً بقيمة 400,000 دولار أمريكي أو ما يعادلها بالـ TL ويقدّمون تعهداً بعدم البيع لمدة 3 سنوات التقدم للجنسية؛ ويشمل ذلك الزوج والأولاد دون سن 18 عاماً."},"Süreç ne kadar sürer?":{"en":"How long does the process take?","ru":"Сколько длится процесс?","zh":"流程需要多久？","ar":"كم تستغرق العملية؟"},"Tapu aşaması yaklaşık 1 ay, tüm vatandaşlık süreci ise genellikle 6-8 ay sürer. Adımları koordine ederek gecikmeleri en aza indiririz.":{"en":"The title-deed stage takes approximately 1 month, and the entire citizenship process generally 6-8 months. By coordinating the steps, we minimize delays.","ru":"Этап тапу занимает приблизительно 1 месяц, а весь процесс получения гражданства обычно 6-8 месяцев. Координируя шаги, мы сводим задержки к минимуму.","zh":"房产证阶段约 1 个月，整个入籍流程通常需 6-8 个月。我们通过协调各步骤把延误降至最低。","ar":"تستغرق مرحلة سند الملكية نحو شهر واحد، وتستغرق كامل عملية الجنسية عادةً 6-8 أشهر. ونقلّل التأخيرات إلى أدنى حد بتنسيق الخطوات."},"Tatil & Kısa Dönem":{"en":"Holiday & Short-Term","ru":"Курорты и краткосрочная аренда","zh":"度假与短租","ar":"العطلات والمدى القصير"},"Ege bölgesinin turizm potansiyeli, sahil şeridini yalnızca yaşam değil güçlü bir yatırım cazibesi merkezi haline getiriyor. Çeşme, Alaçatı, Urla, Seferihisar ve Kuşadası gibi lokasyonlarda yazlık daire, müstakil villa ve premium konutlar; hem uzun vadeli değer artışı hem de yüksek sezonluk kira geliri sunar. Meridyen Gayrimenkul, bu özel segment için hem alım danışmanlığı hem de kısa dönem kiralama yönetimi sağlar. Alım tarafında, tatil bölgelerinin kendine özgü dinamiklerini analiz ederiz: sahile mesafe, imar ve yapılaşma kısıtları, sezon dışı likidite ve premium bölgelerde uzayabilen amortisman süresi gibi faktörleri baştan raporlarız. Çeşme gibi metrekare fiyatları çok yüksek bölgelerde alım kararını duygusal beklentiyle değil, gerçekçi kira çarpanı ve doğrulanmış emsallerle veririz. Kısa dönem kiralama yönetiminde ise mülkünüzü sezon boyunca değerlendirir; dinamik fiyatlama, misafir organizasyonu, temizlik-bakım koordinasyonu ve yeni turizm amaçlı kiralama mevzuatına (izin belgesi) uyum konularında yönetimi üstleniriz. Böylece yazlık mülkünüz, siz kullanmadığınız dönemlerde atıl kalmak yerine düzenli gelir üreten bir varlığa dönüşür.":{"en":"The Aegean region's tourism potential has turned the coastline into a center of strong investment appeal, not just of living. In locations such as Çeşme, Alaçatı, Urla, Seferihisar and Kuşadası, summer apartments, detached villas and premium residences offer both long-term appreciation and high seasonal rental income. Meridyen Gayrimenkul provides both purchase advisory and short-term rental management for this special segment. On the purchase side, we analyze the distinctive dynamics of holiday areas: from the outset we report factors such as distance to the shore, zoning and construction restrictions, off-season liquidity and the payback period that may lengthen in premium areas. In areas where per-square-meter prices are very high, such as Çeşme, we make the purchase decision not with emotional expectations but with a realistic rent multiplier and verified comparables. In short-term rental management, we make the most of your property throughout the season; we take on management in matters such as dynamic pricing, guest organization, cleaning-maintenance coordination and compliance with the new tourism-purpose rental legislation (permit certificate). This turns your summer property, instead of sitting idle during the periods you do not use it, into an asset that generates regular income.","ru":"Туристический потенциал Эгейского региона делает прибрежную полосу центром притяжения не только для жизни, но и для сильных инвестиций. В таких локациях, как Çeşme, Alaçatı, Urla, Seferihisar и Kuşadası, летние квартиры, отдельные виллы и премиальное жильё дают и долгосрочный прирост стоимости, и высокий сезонный доход от аренды. Для этого особого сегмента Meridyen Gayrimenkul предоставляет и консультации по покупке, и управление краткосрочной арендой. Со стороны покупки мы анализируем присущую курортным районам динамику: такие факторы, как расстояние до моря, ограничения зонирования и застройки, ликвидность вне сезона и удлиняющийся в премиальных районах срок окупаемости, мы отражаем в отчёте заранее. В районах с очень высокой ценой за квадратный метр, таких как Çeşme, решение о покупке мы принимаем не на основе эмоциональных ожиданий, а на основе реалистичного мультипликатора аренды и проверенных сопоставимых объектов. В управлении краткосрочной арендой мы задействуем ваш объект в течение всего сезона; берём на себя управление вопросами динамического ценообразования, организации гостей, координации уборки и обслуживания и соответствия новому законодательству о туристической аренде (разрешительный документ). Так ваш летний объект вместо простоя в периоды, когда вы им не пользуетесь, превращается в актив, приносящий регулярный доход.","zh":"爱琴海地区的旅游潜力，使海岸线不仅成为生活之地，更成为强劲的投资引力中心。在 Çeşme、Alaçatı、Urla、Seferihisar 和 Kuşadası 等地，度假公寓、独栋别墅和高端住宅既提供长期价值增长，也提供高额的季节性租金收入。Meridyen Gayrimenkul 为这一特殊细分市场既提供购入顾问，也提供短租管理。在购入端，我们分析度假区域独有的动态：到海岸的距离、规划和建设限制、淡季流动性以及高端区域可能拉长的回本周期等因素，我们从一开始就加以报告。在 Çeşme 这类每平方米价格极高的区域，我们做购入决策依据的不是情绪化预期，而是现实的租金倍数和经核实的可比案例。在短租管理中，我们在整个季节内利用您的房产；承担动态定价、宾客接待、清洁-维护协调，以及对新的旅游用途租赁法规（许可证）合规等管理工作。由此，您的度假房产在您不使用的时段不再闲置，而是转变为持续产生收入的资产。","ar":"إمكانات السياحة في منطقة بحر إيجه تجعل الشريط الساحلي مركز جذب استثماري قوي لا مكان عيش فحسب. في مواقع مثل Çeşme وAlaçatı وUrla وSeferihisar وKuşadası تقدّم الشقق الصيفية والفلل المستقلة والمساكن المتميزة ارتفاعاً في القيمة على المدى الطويل ودخل إيجار موسمياً مرتفعاً معاً. تقدّم Meridyen Gayrimenkul لهذا القطاع الخاص استشارات الشراء وإدارة التأجير قصير المدى معاً. في جانب الشراء نحلّل الديناميكيات الخاصة بمناطق العطلات: فنُقدّم من البداية تقريراً عن عوامل مثل المسافة إلى الساحل وقيود التنظيم العمراني والبناء والسيولة خارج الموسم ومدة الاسترداد التي قد تطول في المناطق المتميزة. وفي مناطق مرتفعة جداً في سعر المتر المربع مثل Çeşme نتخذ قرار الشراء بمضاعف إيجار واقعي وأمثلة مماثلة مؤكَّدة لا بتوقع عاطفي. أما في إدارة التأجير قصير المدى فنقيّم عقاركم طوال الموسم؛ ونتولّى الإدارة في التسعير الديناميكي وتنظيم الضيوف وتنسيق التنظيف والصيانة والتوافق مع التشريعات الجديدة للتأجير لأغراض سياحية (وثيقة التصريح). وهكذا يتحوّل عقاركم الصيفي، بدل أن يبقى عاطلاً في الفترات التي لا تستخدمونه فيها، إلى أصل يدرّ دخلاً منتظماً."},"Tatil bölgesi & mülk analizi":{"en":"Holiday area & property analysis","ru":"Анализ курортного района и объекта","zh":"度假区域与房产分析","ar":"تحليل منطقة العطلات والعقار"},"Sezonluk getiri projeksiyonu":{"en":"Seasonal return projection","ru":"Прогноз сезонной доходности","zh":"季节性收益预测","ar":"إسقاط العائد الموسمي"},"Alım / devir danışmanlığı":{"en":"Purchase / transfer advisory","ru":"Консультации по покупке / переоформлению","zh":"购入／过户顾问","ar":"استشارات الشراء / النقل"},"Turizm kiralama izni uyumu":{"en":"Tourism rental permit compliance","ru":"Соответствие разрешению на туристическую аренду","zh":"旅游租赁许可合规","ar":"التوافق مع تصريح التأجير السياحي"},"Dinamik fiyat & misafir yönetimi":{"en":"Dynamic pricing & guest management","ru":"Динамическое ценообразование и управление гостями","zh":"动态定价与宾客管理","ar":"التسعير الديناميكي وإدارة الضيوف"},"Bakım, temizlik & gelir raporu":{"en":"Maintenance, cleaning & income report","ru":"Обслуживание, уборка и отчёт о доходе","zh":"维护、清洁与收入报告","ar":"الصيانة والتنظيف وتقرير الدخل"},"Tatil bölgelerinde sezon dışı likidite ve gerçek amortisman süresi baştan raporlanır.":{"en":"In holiday areas, off-season liquidity and the real payback period are reported from the outset.","ru":"В курортных районах ликвидность вне сезона и реальный срок окупаемости отражаются в отчёте заранее.","zh":"度假区域的淡季流动性和真实回本周期从一开始就予以报告。","ar":"تُقدَّم من البداية السيولة خارج الموسم ومدة الاسترداد الحقيقية في مناطق العطلات."},"Kısa dönem kiralama, güncel turizm amaçlı kiralama mevzuatına ve izin belgesine uygun yürütülür.":{"en":"Short-term rental is conducted in compliance with current tourism-purpose rental legislation and the permit certificate.","ru":"Краткосрочная аренда ведётся в соответствии с действующим законодательством о туристической аренде и разрешительным документом.","zh":"短租依照最新的旅游用途租赁法规和许可证合规进行。","ar":"يُدار التأجير قصير المدى بما يتوافق مع التشريعات الجديدة للتأجير لأغراض سياحية ومع وثيقة التصريح."},"Sezonluk gelir dinamik fiyatlama ve misafir yönetimiyle optimize edilir.":{"en":"Seasonal income is optimized with dynamic pricing and guest management.","ru":"Сезонный доход оптимизируется динамическим ценообразованием и управлением гостями.","zh":"季节性收入通过动态定价和宾客管理加以优化。","ar":"يُحسَّن الدخل الموسمي بالتسعير الديناميكي وإدارة الضيوف."},"Yazlığımı hem kendim kullanıp hem kiraya verebilir miyim?":{"en":"Can I both use my summer home myself and rent it out?","ru":"Могу ли я одновременно и сам пользоваться летним домом, и сдавать его в аренду?","zh":"我能既自用度假屋、又把它出租吗？","ar":"هل يمكنني استخدام منزلي الصيفي بنفسي وتأجيره في آنٍ واحد؟"},"Evet. Kullanmayı planladığınız dönemleri takvimden ayırır, kalan sezonu kısa dönem kiralama ile değerlendirerek atıl kalmasını önleriz.":{"en":"Yes. We set aside the periods you plan to use on the calendar and make the most of the remaining season with short-term rental, preventing it from sitting idle.","ru":"Да. Мы резервируем в календаре периоды, когда вы планируете пользоваться, а оставшийся сезон задействуем краткосрочной арендой, предотвращая простой.","zh":"可以。我们会在日历上预留您计划使用的时段，把余下的季节用于短租，避免其闲置。","ar":"نعم. نفصل من التقويم الفترات التي تخطّطون لاستخدامها، ونقيّم بقية الموسم بالتأجير قصير المدى لنمنع بقاءه عاطلاً."},"Kısa dönem kiralama için izin gerekiyor mu?":{"en":"Is a permit required for short-term rental?","ru":"Требуется ли разрешение для краткосрочной аренды?","zh":"短租需要许可吗？","ar":"هل يلزم تصريح للتأجير قصير المدى؟"},"Evet, turizm amaçlı kısa dönem kiralamalar için izin belgesi gerekmektedir. Bu sürecin mevzuata uygun yürütülmesinde size rehberlik ederiz.":{"en":"Yes, a permit certificate is required for tourism-purpose short-term rentals. We guide you in conducting this process in compliance with the legislation.","ru":"Да, для краткосрочной аренды в туристических целях требуется разрешительный документ. Мы направляем вас в ведении этого процесса в соответствии с законодательством.","zh":"需要，旅游用途的短租需要许可证。我们会在这一流程的合规办理中为您提供指引。","ar":"نعم، يلزم للتأجير قصير المدى لأغراض سياحية وثيقة تصريح. ونرشدكم في إجراء هذه العملية بما يتوافق مع التشريعات."},"Özel Masa · Miras & İntikal":{"en":"Dedicated Desk · Inheritance & Transfer","ru":"Специальная служба · Наследство и переход имущества","zh":"专属服务台 · 遗产与继承","ar":"المكتب الخاص · الميراث والانتقال"},"Miras kalan gayrimenkulü, hak kaybı yaşamadan devralın":{"en":"Take over inherited real estate without losing your rights","ru":"Примите унаследованную недвижимость без потери прав","zh":"继承而来的房产，不失权利地完成承接","ar":"استلموا العقار الموروث دون فقدان أي حق"},"Miras kalan bir gayrimenkul; duygusal bir değer taşımasının yanında, çoğu zaman birden fazla mirasçıyı, karmaşık hukuki süreçleri ve sıkı vergi takvimlerini içeren teknik bir dosyaya dönüşür. Bir taşınmazın mirasçılar adına geçmesi için önce mirasçılığın resmen belgelenmesi (veraset ilamı), ardından tapuda intikal işleminin yapılması ve Veraset ve İntikal Vergisi yükümlülüğünün tamamlanması gerekir. Bu üç halka birbirine bağlıdır: vergi ödenmeden tapuda devir ve ferağ yapılamaz, intikal tamamlanmadan da miras kalan mülk satılamaz. Süreç yanlış kurgulandığında hem gecikme cezaları hem de mirasçılar arası anlaşmazlıklar hızla büyüyebilir.":{"en":"An inherited property, besides carrying emotional value, often turns into a technical file involving multiple heirs, complex legal processes and strict tax deadlines. For a property to pass into the heirs' names, first the heirship must be formally documented (certificate of inheritance), then the transfer must be carried out at the land registry, and the Inheritance and Transfer Tax obligation must be completed. These three links are connected to one another: without the tax being paid, transfer and conveyance cannot be made at the land registry, and without the transfer being completed, the inherited property cannot be sold. When the process is structured wrongly, both late-payment penalties and disputes among heirs can grow quickly.","ru":"Унаследованная недвижимость, помимо эмоциональной ценности, часто превращается в техническое дело, включающее нескольких наследников, сложные юридические процессы и жёсткие налоговые сроки. Чтобы недвижимость перешла к наследникам, сначала необходимо официально задокументировать право наследования (свидетельство о праве на наследство — Veraset İlamı), затем провести переоформление в тапу и выполнить обязательство по налогу на наследство и переход имущества. Эти три звена связаны друг с другом: без уплаты налога нельзя провести переоформление и отчуждение в тапу, а без завершения переоформления унаследованную недвижимость нельзя продать. При неправильном выстраивании процесса и штрафы за просрочку, и споры между наследниками могут быстро нарастать.","zh":"继承而来的房产，除了承载情感价值外，往往会演变为一份牵涉多位继承人、复杂法律流程和严格税务时限的技术性案卷。一处房产要过到继承人名下，需先对继承资格进行正式证明（继承权证明，Veraset İlamı），随后在房产证上办理继承过户，并完成遗产与继承税的义务。这三个环节环环相扣：税款未缴则无法在房产证上办理过户与让渡（ferağ），继承过户未完成则继承的房产无法出售。流程若安排错误，逾期罚款和继承人之间的纠纷都可能迅速扩大。","ar":"العقار الموروث؛ إلى جانب حمله قيمةً عاطفية، يتحوّل غالباً إلى ملف تقني يشمل أكثر من وارث وإجراءات قانونية معقّدة وتقاويم ضريبية صارمة. لكي ينتقل العقار باسم الورثة يجب أولاً توثيق صفة الإرث رسمياً (حجة الوراثة (Veraset İlamı))، ثم إجراء معاملة الانتقال في سند الملكية، وإتمام التزام ضريبة الميراث والانتقال. وهذه الحلقات الثلاث مترابطة: لا يمكن إجراء النقل والتنازل في سند الملكية قبل سداد الضريبة، ولا يمكن بيع العقار الموروث قبل إتمام الانتقال. وإذا صُمِّمت العملية بشكل خاطئ فقد تتضخم بسرعة غرامات التأخير والنزاعات بين الورثة معاً."},"Meridyen Gayrimenkul olarak yaklaşımımız veri odaklıdır: miras kalan taşınmazın güncel rayiç değerini bölge analizleriyle belirler, hisse yapısını ve mirasçı sayısını netleştirir, satış mı yoksa mirasçılar arası pay birleştirmesi mi daha verimli sonuç verir sorusunu rakamlarla ortaya koyarız. Emlak ofisi bu denklemde değerleme, alıcı bulma, hisseli mülk satışı ve pazarlama tarafını üstlenir; noter, tapu müdürlüğü ve mahkeme süreçlerinde ise sizi güvenilir hukuk ortaklarımıza yönlendiririz. Böylece miras dosyanız hem hukuken sağlam hem de piyasa değeri korunacak biçimde yönetilir.":{"en":"As Meridyen Gayrimenkul, our approach is data-driven: we determine the current market value of the inherited property through regional analyses, clarify the share structure and the number of heirs, and set out in figures the question of whether a sale or a consolidation of shares among the heirs yields the more efficient result. In this equation, the real estate office takes on the valuation, finding a buyer, the sale of the shared property and the marketing side; in notary, land registry and court processes, we direct you to our trusted legal partners. This way your inheritance file is managed in a way that is both legally sound and preserves market value.","ru":"Наш подход в Meridyen Gayrimenkul опирается на данные: мы определяем текущую рыночную стоимость унаследованной недвижимости с помощью анализа района, проясняем структуру долей и число наследников и в цифрах показываем, что даёт более эффективный результат — продажа или объединение долей между наследниками. В этом уравнении агентство берёт на себя оценку, поиск покупателя, продажу долевой недвижимости и маркетинг; в процессах у нотариуса, в управлении кадастра и в суде мы направляем вас к нашим надёжным юридическим партнёрам. Так ваше наследственное дело ведётся и юридически надёжно, и с сохранением рыночной стоимости.","zh":"作为 Meridyen Gayrimenkul，我们的做法以数据为核心：通过区域分析确定继承房产的当前市场价值（rayiç），厘清份额结构和继承人数量，用数字摆明是出售、还是继承人之间合并份额更能带来高效的结果。房产中介在这一等式中承担估价、寻找买家、共有房产出售和营销的部分；而在公证处、房产证登记处和法院流程中，我们会将您转介至可信赖的法律合作伙伴。由此，您的遗产案卷得以既在法律上稳妥、又在市场价值得到保全的方式下管理。","ar":"نهجنا في Meridyen Gayrimenkul قائم على البيانات: نحدد القيمة الرائجة الحالية للعقار الموروث بتحليلات المنطقة، ونوضّح بنية الحصص وعدد الورثة، ونضع بالأرقام إجابة السؤال: هل البيع أم دمج الحصص بين الورثة يعطي نتيجة أجدى. يتولّى المكتب العقاري في هذه المعادلة جانب التقييم وإيجاد المشتري وبيع العقار المشاع والتسويق؛ أما في إجراءات الكاتب بالعدل ومديرية سند الملكية والمحكمة فنحيلكم إلى شركائنا القانونيين الموثوقين. وهكذا يُدار ملف ميراثكم بشكل سليم قانونياً وبما يحفظ قيمته السوقية معاً."},"Aşağıdaki tüm rakam, harç, süre ve oranlar yaklaşık ve bilgilendirme amaçlıdır; her yıl yeniden değerleme oranıyla güncellenir ve somut olaya göre değişir. Bağlayıcı bir işlem yapmadan önce mutlaka güncel mevzuata, ilgili tapu müdürlüğüne, vergi dairesine veya bir hukuk danışmanına başvurunuz.":{"en":"All figures, fees, durations and rates below are approximate and for information only; they are updated each year with the revaluation rate and change according to the specific case. Before making any binding transaction, be sure to consult the current legislation, the relevant land registry directorate, the tax office or a legal advisor.","ru":"Все приведённые ниже цифры, пошлины, сроки и ставки являются приблизительными и носят информационный характер; они ежегодно обновляются с учётом коэффициента переоценки и меняются в зависимости от конкретного случая. Прежде чем совершать обязывающую операцию, обязательно обратитесь к действующему законодательству, в соответствующее управление кадастра, налоговую инспекцию или к юридическому консультанту.","zh":"以下所有数字、税费、时限和比率均为近似值，仅供参考；每年按重估率更新，并因具体案情而异。在进行任何具约束力的交易前，请务必查阅现行法规、相关房产证登记处、税务局或法律顾问。","ar":"جميع الأرقام والرسوم والمدد والنسب الواردة أدناه تقريبية ولأغراض إعلامية؛ وتُحدَّث كل عام بمعدل إعادة التقييم وتتغير حسب الواقعة المحدّدة. قبل إجراء أي معاملة ملزِمة راجعوا حتماً التشريعات السارية والمديرية المعنية لسند الملكية ودائرة الضرائب أو مستشاراً قانونياً."},"Veraset İlamı (Mirasçılık Belgesi) Alınması":{"en":"Obtaining the Certificate of Inheritance (Veraset İlamı)","ru":"Получение свидетельства о праве на наследство (Veraset İlamı / документ о наследовании)","zh":"取得继承权证明（Veraset İlamı，继承人证明）","ar":"الحصول على حجة الوراثة (Veraset İlamı) (وثيقة صفة الإرث)"},"Veraset ilamı, kimlerin hangi paylarla mirasçı olduğunu resmen gösteren belgedir ve intikal sürecinin ilk adımıdır. İki yoldan alınabilir: noter veya Sulh Hukuk Mahkemesi. Noter yolu genellikle çok daha hızlıdır; gerekli belgeler eksiksizse çoğu durumda aynı gün içinde belge düzenlenebilir. Mahkeme yolu ise birkaç gün ile birkaç hafta arasında sürebilir. Yetkili merci, miras bırakanın son yerleşim yeri veya mirasçılardan her birinin yerleşim yeri makamıdır.":{"en":"The certificate of inheritance is the document that formally shows who the heirs are and with what shares, and it is the first step of the transfer process. It can be obtained in two ways: from a notary or from the Civil Court of Peace. The notary route is generally much faster; if the required documents are complete, in most cases the document can be issued on the same day. The court route can take from a few days to a few weeks. The competent authority is that of the deceased's last place of residence or that of the place of residence of any of the heirs.","ru":"Свидетельство о праве на наследство (Veraset İlamı) — это документ, официально указывающий, кто и в каких долях является наследником, и это первый шаг процесса переоформления. Его можно получить двумя путями: у нотариуса или в мировом суде по гражданским делам. Путь через нотариуса, как правило, гораздо быстрее; если необходимые документы в порядке, в большинстве случаев документ может быть оформлен в тот же день. Судебный путь может занять от нескольких дней до нескольких недель. Компетентный орган — по последнему месту жительства наследодателя или по месту жительства каждого из наследников.","zh":"继承权证明（Veraset İlamı）是正式载明何人以何种份额为继承人的文件，也是继承过户流程的第一步。可通过两种途径取得：公证处或民事和平法院。公证处途径通常快得多；若所需文件齐全，多数情况下可在当天出具文件。而法院途径可能需数天至数周。有权机关为被继承人最后居所地或各继承人居所地的机关。","ar":"حجة الوراثة (Veraset İlamı) هي الوثيقة التي تُظهر رسمياً من هم الورثة وبأي حصص، وهي الخطوة الأولى في عملية الانتقال. يمكن الحصول عليها بطريقين: الكاتب بالعدل أو محكمة الصلح المدنية. وطريق الكاتب بالعدل أسرع بكثير عادةً؛ فإذا كانت الوثائق اللازمة كاملة يمكن في معظم الحالات إصدار الوثيقة في اليوم نفسه. أما طريق المحكمة فقد يستغرق بين بضعة أيام وبضعة أسابيع. والجهة المختصة هي مرجع محل الإقامة الأخير للمورّث أو محل إقامة أيٍّ من الورثة."},"Bazı hallerde noter belge veremez ve mutlaka Sulh Hukuk Mahkemesine başvurulması gerekir: muris ile mirasçı arasındaki soy bağının nüfus kayıtlarından net tespit edilemediği durumlarda, kayıtların yeterli açıklıkta olmadığı hallerde, ortada bir vasiyetname bulunduğunda veya mirasçılardan en az birinin yabancı uyruklu olduğu durumlarda mahkeme yolu zorunludur.":{"en":"In some cases the notary cannot issue the document and application to the Civil Court of Peace is mandatory: where the lineage between the deceased and the heir cannot be clearly determined from the population records, where the records are not sufficiently clear, where there is a will, or where at least one of the heirs is a foreign national, the court route is compulsory.","ru":"В некоторых случаях нотариус не может выдать документ, и обязательно необходимо обратиться в мировой суд по гражданским делам: когда родственную связь между наследодателем и наследником невозможно чётко установить по записям актов гражданского состояния, когда записи недостаточно ясны, когда имеется завещание или когда хотя бы один из наследников является иностранным гражданином, судебный путь обязателен.","zh":"在某些情形下公证处不能出具文件，必须向民事和平法院申请：在被继承人（muris）与继承人之间的血亲关系无法从户籍记录明确确定时、记录不够清晰时、存在遗嘱时，或至少一名继承人为外国国籍时，法院途径为强制。","ar":"في بعض الحالات لا يستطيع الكاتب بالعدل إصدار الوثيقة ويجب حتماً اللجوء إلى محكمة الصلح المدنية: في الحالات التي لا يمكن فيها تحديد صلة النسب بين المورّث والوارث بوضوح من سجلات الأحوال، أو حين لا تكون السجلات واضحة بما يكفي، أو عند وجود وصية، أو حين يكون أحد الورثة على الأقل من جنسية أجنبية، يكون طريق المحكمة إلزامياً."},"Miras bırakanın (murisin) nüfus kayıt örneği":{"en":"Population registration copy of the deceased (muris)","ru":"Выписка из записей актов гражданского состояния наследодателя (muris)","zh":"被继承人（muris）的户籍记录副本","ar":"نموذج قيد الأحوال المدنية للمورّث (muris)"},"Ölüm belgesi":{"en":"Death certificate","ru":"Свидетельство о смерти","zh":"死亡证明","ar":"شهادة الوفاة"},"Varsa vasiyetname veya miras sözleşmesi":{"en":"Will or inheritance agreement, if any","ru":"Завещание или наследственный договор при наличии","zh":"如有，遗嘱或继承合同","ar":"الوصية أو عقد الميراث إن وُجد"},"Başvuran mirasçıların kimlik belgeleri":{"en":"Identity documents of the applying heirs","ru":"Документы, удостоверяющие личность подающих заявление наследников","zh":"申请继承人的身份证件","ar":"وثائق هوية الورثة المتقدمين"},"Süre:":{"en":"Duration:","ru":"Срок:","zh":"时限：","ar":"المدة:"},"Noterde çoğu zaman aynı gün; Sulh Hukuk Mahkemesinde birkaç gün ile birkaç hafta (yaklaşık, dosyaya göre değişir)":{"en":"At the notary, often the same day; at the Civil Court of Peace, from a few days to a few weeks (approximate, varies by case)","ru":"У нотариуса чаще всего в тот же день; в мировом суде по гражданским делам — от нескольких дней до нескольких недель (приблизительно, зависит от дела)","zh":"在公证处多为当天；在民事和平法院为数天至数周（约值，因案卷而异）","ar":"لدى الكاتب بالعدل غالباً في اليوم نفسه؛ وفي محكمة الصلح المدنية بين بضعة أيام وبضعة أسابيع (تقريبًا، تتغير حسب الملف)"},"İpucu:":{"en":"Tip:","ru":"Совет:","zh":"提示：","ar":"نصيحة:"},"Yabancı uyruklu mirasçı, vasiyetname veya karışık nüfus kaydı yoksa hızlı ve ekonomik olan noter yolunu tercih edin. Belgeyi birden fazla asıl nüsha halinde alın; tapu, vergi dairesi ve banka işlemlerinde ayrı ayrı istenebilir.":{"en":"If there is no foreign-national heir, will or complicated population record, choose the fast and economical notary route. Obtain the document in several original copies; it may be requested separately in title-deed, tax office and bank transactions.","ru":"Если нет наследника-иностранца, завещания или запутанных записей актов гражданского состояния, выбирайте быстрый и экономичный путь через нотариуса. Получите документ в нескольких оригинальных экземплярах; он может отдельно потребоваться при операциях с тапу, в налоговой инспекции и в банке.","zh":"如无外国国籍继承人、遗嘱或混乱的户籍记录，请选择快速且经济的公证处途径。请领取多份正本；房产证、税务局和银行手续中可能会分别索要。","ar":"إذا لم يكن هناك وارث أجنبي الجنسية أو وصية أو قيد أحوال متشابك، ففضّلوا طريق الكاتب بالعدل السريع والاقتصادي. واحصلوا على الوثيقة بعدة نسخ أصلية؛ فقد تُطلَب على حدة في معاملات سند الملكية ودائرة الضرائب والبنك."},"Veraset ve İntikal Vergisi Beyannamesinin Verilmesi":{"en":"Filing the Inheritance and Transfer Tax Return","ru":"Подача декларации по налогу на наследство и переход имущества","zh":"提交遗产与继承税申报表","ar":"تقديم إقرار ضريبة الميراث والانتقال"},"Miras yoluyla intikal eden mal varlığı için mirasçıların, ölüm tarihinden itibaren kural olarak 4 ay içinde ilgili vergi dairesine Veraset ve İntikal Vergisi beyannamesi vermesi gerekir. Ölüm yurt dışında gerçekleşmişse süre uzayabilir (yaklaşık 6 ila 8 ay arası; duruma göre değişir). Beyanname, murisin son ikametgahının bulunduğu yer vergi dairesine verilir. Önemli bir kural: intikal eden taşınmaza isabet eden vergi tamamen ödenmedikçe tapuda devir ve ferağ yapılamaz, dolayısıyla mülk satılamaz.":{"en":"For assets transferred by inheritance, the heirs must, as a rule, file an Inheritance and Transfer Tax return with the relevant tax office within 4 months of the date of death. If the death occurred abroad, the period may be extended (approximately 6 to 8 months; varies by case). The return is filed with the tax office of the deceased's last place of residence. An important rule: until the tax attributable to the transferred property is paid in full, transfer and conveyance cannot be made at the land registry, and therefore the property cannot be sold.","ru":"По имуществу, переходящему по наследству, наследники по общему правилу обязаны в течение 4 месяцев с даты смерти подать в соответствующую налоговую инспекцию декларацию по налогу на наследство и переход имущества. Если смерть наступила за границей, срок может продлеваться (приблизительно от 6 до 8 месяцев; зависит от ситуации). Декларация подаётся в налоговую инспекцию по последнему месту жительства наследодателя. Важное правило: пока налог, приходящийся на переходящую недвижимость, не уплачен полностью, нельзя провести переоформление и отчуждение в тапу, а следовательно, недвижимость нельзя продать.","zh":"对于通过继承过户的财产，继承人原则上须自死亡之日起 4 个月内向相关税务局提交遗产与继承税申报表。若死亡发生在国外，时限可能延长（约 6 至 8 个月之间；视情况而异）。申报表向被继承人最后居所所在地的税务局提交。一条重要规则：在归属于所过户房产的税款未全部缴清前，房产证上无法办理过户与让渡（ferağ），因而房产无法出售。","ar":"يجب على الورثة، بالنسبة للأموال المنتقلة عن طريق الميراث، تقديم إقرار ضريبة الميراث والانتقال إلى دائرة الضرائب المعنية كقاعدة خلال 4 أشهر من تاريخ الوفاة. وإذا حدثت الوفاة في الخارج فقد تطول المدة (نحو 6 إلى 8 أشهر؛ تتغير حسب الحالة). يُقدَّم الإقرار إلى دائرة الضرائب في مكان محل الإقامة الأخير للمورّث. وثمة قاعدة مهمة: لا يمكن إجراء النقل والتنازل في سند الملكية ما لم تُسدَّد كاملةً الضريبة المستحقة على العقار المنتقل، وبالتالي لا يمكن بيع العقار."},"2026 yılı için miras (veraset) yoluyla intikallerde vergi oranları artan oranlı olup yaklaşık yüzde 1 ile yüzde 10 arasında; ivazsız (bağış, hibe) intikallerde ise yaklaşık yüzde 10 ile yüzde 30 arasında uygulanır. Füru (çocuklar, torunlar) ve eşten her birine düşen miras payı için önemli bir istisna tutarı bulunur; 2026 için bu tutar yaklaşık 2,9 milyon TL civarında açıklanmıştır (evlatlıklar dahil, güncel resmi tebliğe göre değişebilir). Ana, baba, eş ve çocuklardan yapılan ivazsız intikallerde tarifedeki oranların yarısı uygulanır. Rakamlar her yıl yeniden değerleme oranıyla güncellenir.":{"en":"For 2026, tax rates on transfers by inheritance (veraset) are progressive, ranging from approximately 1% to 10%; on gratuitous (donation, gift) transfers they are applied at approximately 10% to 30%. There is a significant exemption amount for the inheritance share falling to each of the descendants (children, grandchildren) and the spouse; for 2026 this amount has been announced at around 2.9 million TL (including adopted children, may change according to the current official communiqué). On gratuitous transfers from a mother, father, spouse and children, half of the rates in the tariff apply. The figures are updated each year with the revaluation rate.","ru":"На 2026 год при переходе имущества по наследству ставки налога прогрессивные и составляют приблизительно от 1% до 10%; при безвозмездном переходе (дарение, пожертвование) применяется приблизительно от 10% до 30%. Для доли наследства, приходящейся на каждого из нисходящих родственников (дети, внуки) и супруга, предусмотрена значительная сумма льготы; на 2026 год эта сумма объявлена около 2,9 млн TL (включая усыновлённых, может меняться согласно действующему официальному сообщению). При безвозмездном переходе от матери, отца, супруга и детей применяется половина ставок по тарифу. Цифры ежегодно обновляются с учётом коэффициента переоценки.","zh":"2026 年，通过遗产（继承）过户的税率为累进制，约在 1% 至 10% 之间；而对于无偿（赠与、捐赠）过户，则约在 10% 至 30% 之间适用。对直系卑亲属（子女、孙辈）和配偶各自应得的继承份额，有一项重要的免税额；2026 年该额度公布约为 2.9 百万 TL 左右（含养子女，可能因现行官方公告而变动）。对来自父、母、配偶和子女的无偿过户，适用税率表中比率的一半。数字每年按重估率更新。","ar":"لعام 2026 تكون نسب الضريبة في الانتقالات عن طريق الميراث (الوراثة) تصاعديةً وتتراوح تقريبًا بين 1% و10%؛ أما في الانتقالات بلا عوض (تبرّع، هبة) فتُطبَّق تقريبًا بين 10% و30%. ولكل من الفروع (الأولاد والأحفاد) والزوج مبلغ استثناء مهم عن حصة الميراث المستحقة له؛ ولعام 2026 أُعلِن هذا المبلغ عند نحو 2.9 مليون TL تقريبًا (بما في ذلك المتبنَّون، وقد يتغير حسب التبليغ الرسمي الساري). وفي الانتقالات بلا عوض من الأم والأب والزوج والأولاد يُطبَّق نصف النسب الواردة في التعرفة. وتُحدَّث الأرقام كل عام بمعدل إعادة التقييم."},"Veraset ilamı (mirasçılık belgesi)":{"en":"Certificate of inheritance (Veraset İlamı)","ru":"Свидетельство о праве на наследство (Veraset İlamı / документ о наследовании)","zh":"继承权证明（Veraset İlamı，继承人证明）","ar":"حجة الوراثة (Veraset İlamı) (وثيقة صفة الإرث)"},"Murisin nüfus kayıt örneği ve ölüm belgesi":{"en":"The deceased's population registration copy and death certificate","ru":"Выписка из записей актов гражданского состояния наследодателя и свидетельство о смерти","zh":"被继承人（muris）的户籍记录副本和死亡证明","ar":"نموذج قيد الأحوال المدنية للمورّث وشهادة الوفاة"},"Taşınmaza ait tapu bilgileri ve emlak (rayic) değeri belgesi":{"en":"Title-deed details of the property and property (market) value document","ru":"Данные тапу на недвижимость и документ о рыночной (кадастровой) стоимости имущества","zh":"房产的房产证信息和房产（rayiç，市场基准）价值证明","ar":"معلومات سند ملكية العقار ووثيقة القيمة العقارية (الرائجة)"},"Banka hesabı, araç, hisse gibi diğer tereke malvarlığına ilişkin belgeler":{"en":"Documents relating to other estate assets such as bank accounts, vehicles and shares","ru":"Документы по прочему наследственному имуществу — банковскому счёту, транспортному средству, акциям","zh":"银行账户、车辆、股份等其他遗产（tereke）财产的相关文件","ar":"الوثائق المتعلقة بباقي أموال التركة مثل الحساب المصرفي والمركبة والأسهم"},"Mirasçıların kimlik ve iletişim bilgileri":{"en":"Heirs' identity and contact details","ru":"Документы, удостоверяющие личность, и контактные данные наследников","zh":"继承人的身份和联系信息","ar":"معلومات هوية الورثة والاتصال بهم"},"Beyanname: ölümden itibaren yaklaşık 4 ay (yurt dışı ölümlerde daha uzun). Ödeme: taksitlendirmeyle 3 yıla yayılabilir":{"en":"Return: approximately 4 months from death (longer for deaths abroad). Payment: can be spread over 3 years in installments","ru":"Декларация: приблизительно 4 месяца с даты смерти (при смерти за границей — дольше). Оплата: может быть рассрочена на 3 года","zh":"申报表：自死亡起约 4 个月（国外死亡则更长）。缴纳：通过分期可延展至 3 年","ar":"الإقرار: نحو 4 أشهر من الوفاة (أطول في وفيات الخارج). السداد: يمكن توزيعه على 3 سنوات بالتقسيط"},"Vergi, beyannamenin verildiği yılı izleyen 3 yıl boyunca her yıl Mayıs ve Kasım aylarında olmak üzere 6 eşit taksitte ödenebilir ve bu yasal taksitlendirmede faiz uygulanmaz. İstisna tutarının altında kalan paylarda vergi çıkmayabilir; yine de beyanname verme yükümlülüğü ayrıca değerlendirilmelidir.":{"en":"The tax can be paid in 6 equal installments, in May and November each year over the 3 years following the year the return is filed, and no interest applies to this statutory installment plan. For shares below the exemption amount, no tax may arise; nonetheless, the obligation to file a return should be assessed separately.","ru":"Налог может уплачиваться 6 равными частями — в мае и ноябре каждого года в течение 3 лет, следующих за годом подачи декларации, — и на эту законную рассрочку проценты не начисляются. По долям, остающимся ниже суммы льготы, налога может не возникнуть; тем не менее обязанность подать декларацию должна оцениваться отдельно.","zh":"税款可在提交申报表年度的次年起 3 年内、每年 5 月和 11 月分 6 期等额缴纳，且此法定分期不计利息。份额低于免税额的可能无需缴税；但提交申报表的义务仍须另行考量。","ar":"يمكن سداد الضريبة على 6 أقساط متساوية في شهري مايو ونوفمبر من كل عام على مدى 3 سنوات تلي سنة تقديم الإقرار، ولا تُطبَّق فائدة على هذا التقسيط القانوني. وفي الحصص التي تبقى دون مبلغ الاستثناء قد لا تُستحَق ضريبة؛ ومع ذلك يجب تقييم التزام تقديم الإقرار على حدة."},"Tapuda İntikal (Mirasçılara Tescil) İşlemi":{"en":"Transfer at the Land Registry (Registration to the Heirs)","ru":"Переоформление в тапу (регистрация на наследников)","zh":"房产证继承过户（向继承人登记）手续","ar":"معاملة الانتقال في سند الملكية (التسجيل باسم الورثة)"},"Veraset ilamı alınıp vergi yükümlülüğü tamamlandıktan sonra, taşınmazın mirasçılar adına tescil edilmesi için tapu müdürlüğüne başvurulur. Başvuru mirasçılardan biri tarafından Web-Tapu üzerinden yapılabilir. Ardından tapu müdürlüğü döner sermaye hizmet bedelini SMS ile bildirir; ücret yatırıldıktan sonra verilen randevu saatinde ilgili tapu müdürlüğüne gidilerek imza aşaması tamamlanır ve intikal gerçekleştirilir. İntikal sonucunda taşınmaz, mirasçılar arasında elbirliği mülkiyeti veya talep halinde paylı (hisseli) mülkiyet olarak tescil edilir.":{"en":"After the certificate of inheritance is obtained and the tax obligation is completed, an application is made to the land registry directorate to register the property in the heirs' names. The application can be made by one of the heirs via Web-Tapu. The land registry directorate then notifies the revolving fund service fee by SMS; after the fee is paid, at the appointment time given, one goes to the relevant land registry directorate to complete the signing stage and the transfer is effected. As a result of the transfer, the property is registered among the heirs as joint ownership (elbirliği mülkiyeti) or, upon request, as shared (co-)ownership.","ru":"После получения свидетельства о праве на наследство и выполнения налогового обязательства для регистрации недвижимости на наследников подаётся заявка в управление кадастра. Заявку может подать один из наследников через Web-Tapu. Затем управление кадастра сообщает по SMS размер сбора оборотного фонда за услугу; после уплаты сбора в назначенное время приёма стороны являются в соответствующее управление кадастра, завершают этап подписания, и переоформление осуществляется. В результате переоформления недвижимость регистрируется между наследниками как совместная собственность или, по требованию, как долевая собственность.","zh":"在取得继承权证明（Veraset İlamı）并完成税务义务后，为将房产登记至继承人名下，向房产证登记处提出申请。申请可由其中一名继承人通过 Web-Tapu 办理。随后房产证登记处以短信告知周转基金服务费；费用缴纳后，在所给预约时间前往相关房产证登记处完成签字环节，继承过户即告实现。继承过户的结果是，房产在继承人之间以共同共有登记，或在提出请求时以按份（共有）所有登记。","ar":"بعد الحصول على حجة الوراثة (Veraset İlamı) وإتمام التزام الضريبة، يُقدَّم طلب إلى مديرية سند الملكية لتسجيل العقار باسم الورثة. ويمكن تقديم الطلب من أحد الورثة عبر Web-Tapu. ثم تُبلّغ مديرية سند الملكية عن بدل خدمة الصندوق الدوّار برسالة SMS؛ وبعد إيداع الرسم يُذهَب في موعد الموعد المحدّد إلى المديرية المعنية لسند الملكية لإتمام مرحلة التوقيع وتحقيق الانتقال. ونتيجةً للانتقال يُسجَّل العقار بين الورثة كملكية بالاشتراك (elbirliği mülkiyeti) أو كملكية مشاعة (على الحصص) عند الطلب."},"Miras yoluyla intikalde tapu harcı ödenmez; bu, normal satış devrinden temel farkıdır. Alınan tutar döner sermaye hizmet bedeli ve ilave hizmet bedelinden oluşur (2026 için toplam yaklaşık 2.500 TL civarı; her yıl güncellenir). Kritik nokta: intikale konu taşınmaza isabet eden Veraset ve İntikal Vergisi tamamen ödenmeden tapu devir ve ferağ işlemi yapılamaz.":{"en":"No title-deed fee is paid on transfer by inheritance; this is the fundamental difference from a normal sale transfer. The amount charged consists of the revolving fund service fee and an additional service fee (for 2026, approximately 2,500 TL in total; updated each year). Critical point: the transfer and conveyance transaction cannot be carried out at the land registry until the Inheritance and Transfer Tax attributable to the property subject to transfer is paid in full.","ru":"При переходе по наследству пошлина за тапу не уплачивается; это основное отличие от обычного переоформления при продаже. Взимаемая сумма состоит из сбора оборотного фонда за услугу и дополнительного сбора за услугу (на 2026 год в общей сложности около 2 500 TL; ежегодно обновляется). Ключевой момент: пока налог на наследство и переход имущества, приходящийся на переоформляемую недвижимость, не уплачен полностью, операцию переоформления и отчуждения в тапу провести нельзя.","zh":"通过遗产继承过户不缴纳房产证费；这是与普通买卖过户的根本区别。所收取的金额由周转基金服务费和附加服务费构成（2026 年合计约 2,500 TL 左右；每年更新）。关键点：在归属于继承标的房产的遗产与继承税未全部缴清前，无法办理房产证过户与让渡（ferağ）手续。","ar":"لا يُدفَع رسم سند الملكية في الانتقال عن طريق الميراث؛ وهذا هو الفرق الجوهري عن نقل البيع العادي. ويتكوّن المبلغ المأخوذ من بدل خدمة الصندوق الدوّار وبدل الخدمة الإضافي (لعام 2026 نحو 2.500 TL إجمالاً تقريبًا؛ يُحدَّث كل عام). النقطة الحرجة: لا يمكن إجراء نقل سند الملكية والتنازل ما لم تُسدَّد كاملةً ضريبة الميراث والانتقال المستحقة على العقار محل الانتقال."},"Sulh Hukuk Mahkemesinden veya noterden alınan veraset belgesinin aslı veya onaylı örneği":{"en":"The original or a certified copy of the inheritance certificate obtained from the Civil Court of Peace or a notary","ru":"Оригинал или заверенная копия свидетельства о праве на наследство, полученного в мировом суде по гражданским делам или у нотариуса","zh":"从民事和平法院或公证处取得的继承证明的正本或核证副本","ar":"أصل وثيقة الوراثة الصادرة عن محكمة الصلح المدنية أو الكاتب بالعدل أو نسخة مصدَّقة منها"},"Veraset ve İntikal Vergisinin ödendiğine veya ilişik olmadığına dair vergi dairesi yazısı/makbuz":{"en":"A letter/receipt from the tax office confirming that the Inheritance and Transfer Tax has been paid or that there is no outstanding liability","ru":"Письмо/квитанция налоговой инспекции об уплате налога на наследство и переход имущества или об отсутствии задолженности","zh":"税务局出具的关于遗产与继承税已缴纳或无欠税的函件/收据","ar":"كتاب/إيصال من دائرة الضرائب يفيد سداد ضريبة الميراث والانتقال أو براءة الذمة منها"},"Tarafların ve varsa temsilcilerin kimlik belgeleri":{"en":"Identity documents of the parties and of their representatives, if any","ru":"Документы, удостоверяющие личность сторон и, при наличии, их представителей","zh":"当事方及如有代理人的身份证件","ar":"وثائق هوية الأطراف والممثلين إن وُجدوا"},"Temsil varsa temsil belgesi (vekaletname, vasi kararı vb.)":{"en":"If there is representation, the document of representation (power of attorney, guardianship order, etc.)","ru":"При наличии представительства — документ о представительстве (доверенность, решение о назначении опекуна и т. п.)","zh":"如有代理，代理证明（授权委托书、监护人裁定等）","ar":"وثيقة التمثيل إن وُجد (وكالة، قرار وصاية، إلخ)"},"Taşınmazın tapu bilgileri":{"en":"Title-deed details of the property","ru":"Данные тапу на недвижимость","zh":"房产的房产证信息","ar":"معلومات سند ملكية العقار"},"Randevu ve evrak tamamsa genellikle kısa sürede (belge eksikliği süreci uzatabilir; yaklaşık)":{"en":"If the appointment and documents are complete, generally within a short time (missing documents can prolong the process; approximate)","ru":"Если запись на приём и документы в порядке — обычно в короткий срок (нехватка документов может удлинить процесс; приблизительно)","zh":"若预约和文件齐全，通常在短时间内（文件缺失可能拉长流程；约值）","ar":"إذا اكتمل الموعد والأوراق فعادةً في مدة قصيرة (نقص الوثائق قد يطيل العملية؛ تقريبًا)"},"Web-Tapu üzerinden ön başvuruyu erken yapıp döner sermaye bildirimini takip edin. Satış planlıyorsanız intikal ve vergi adımını mutlaka önce tamamlayın; çünkü kişi sahibi olmadığı bir malı devredemez, intikalsiz satış mümkün değildir.":{"en":"Make the preliminary application via Web-Tapu early and follow the revolving fund notification. If you plan a sale, be sure to complete the transfer and tax step first; because a person cannot transfer property they do not own, a sale without transfer is not possible.","ru":"Подайте предварительную заявку через Web-Tapu заранее и отслеживайте уведомление о сборе оборотного фонда. Если вы планируете продажу, обязательно сначала завершите шаг переоформления и налога; ведь человек не может передать имущество, которым не владеет, а продажа без переоформления невозможна.","zh":"请尽早通过 Web-Tapu 提交初步申请，并跟进周转基金通知。若您计划出售，务必先完成继承过户和税务步骤；因为人无法转让自己并不拥有的财产，未办继承过户的出售不可能实现。","ar":"قدّموا الطلب المبدئي مبكّراً عبر Web-Tapu وتابعوا تبليغ الصندوق الدوّار. وإذا كنتم تخطّطون للبيع فأتمّوا حتماً خطوة الانتقال والضريبة أولاً؛ لأن المرء لا يستطيع نقل مال لا يملكه، والبيع دون انتقال غير ممكن."},"Reddi Miras (Mirasın Reddi)":{"en":"Renunciation of Inheritance (Reddi Miras)","ru":"Отказ от наследства (Reddi Miras)","zh":"放弃继承（Reddi Miras，拒绝继承）","ar":"رفض الميراث (Reddi Miras) (ردّ التركة)"},"Mirasçı, murisin mal varlığıyla birlikte borçlarını da üstlenmek istemiyorsa mirası reddedebilir. Gerçek ret için süre kural olarak 3 aydır; bu süre yasal mirasçıda genellikle ölümü öğrenme tarihinden, atanmış mirasçıda ise tasarrufun resmen bildirildiği tarihten başlar. Ret beyanı, murisin son yerleşim yeri Sulh Hukuk Mahkemesine, kayıtsız ve şartsız olarak yapılmalıdır. Notere veya başka bir mahkemeye yapılan ret beyanı geçersizdir.":{"en":"If the heir does not wish to assume the deceased's debts along with the assets, they can renounce the inheritance. The period for actual renunciation is, as a rule, 3 months; this period generally starts, for a legal heir, from the date of learning of the death, and for an appointed heir, from the date the disposition is formally notified. The declaration of renunciation must be made, unconditionally and without reservation, to the Civil Court of Peace of the deceased's last place of residence. A declaration of renunciation made to a notary or another court is invalid.","ru":"Если наследник не желает вместе с имуществом наследодателя принимать и его долги, он может отказаться от наследства. Срок для действительного отказа по общему правилу составляет 3 месяца; этот срок для законного наследника обычно начинается с даты, когда он узнал о смерти, а для назначенного наследника — с даты официального уведомления о распоряжении. Заявление об отказе должно быть подано в мировой суд по гражданским делам по последнему месту жительства наследодателя безоговорочно и без условий. Заявление об отказе, поданное нотариусу или в другой суд, недействительно.","zh":"若继承人不愿在承接被继承人财产的同时也承接其债务，可放弃继承。真正放弃的时限原则上为 3 个月；对法定继承人，此期限通常自获知死亡之日起算，对指定继承人则自处分被正式告知之日起算。放弃声明须以无保留、无条件的方式向被继承人最后居所地的民事和平法院作出。向公证处或其他法院作出的放弃声明无效。","ar":"إذا لم يرغب الوارث في تحمّل ديون المورّث مع أمواله، فيمكنه رفض الميراث. ومدة الردّ الحقيقي كقاعدة 3 أشهر؛ وتبدأ هذه المدة لدى الوارث القانوني عادةً من تاريخ العلم بالوفاة، ولدى الوارث المعيَّن من تاريخ التبليغ الرسمي بالتصرف. ويجب أن يُقدَّم بيان الردّ إلى محكمة الصلح المدنية لمحل الإقامة الأخير للمورّث، دون قيد أو شرط. وبيان الردّ المقدَّم إلى الكاتب بالعدل أو إلى محكمة أخرى باطل."},"Mirası usulüne uygun reddeden mirasçı, murisin alacaklılarına karşı sorumluluktan kurtulur. Bir mirasçı reddederse payı diğer mirasçılara geçer; ancak birinci zümre mirasçılarının tamamı reddederse miras ikinci zümreye geçmez ve tereke Sulh Hukuk Mahkemesince iflas hükümlerine göre tasfiye edilir. Ret beyanı sonuç doğurduktan sonra kural olarak geri alınamaz. Terekeye sahip çıkan veya olağan dışı tasarrufta bulunan mirasçı ret hakkını kaybeder.":{"en":"An heir who duly renounces the inheritance is released from liability toward the deceased's creditors. If one heir renounces, their share passes to the other heirs; however, if all first-degree heirs renounce, the inheritance does not pass to the second degree and the estate is liquidated by the Civil Court of Peace according to bankruptcy provisions. Once the declaration of renunciation has taken effect, it cannot, as a rule, be withdrawn. An heir who takes possession of the estate or makes an extraordinary disposition loses the right to renounce.","ru":"Наследник, надлежащим образом отказавшийся от наследства, освобождается от ответственности перед кредиторами наследодателя. Если один наследник отказывается, его доля переходит к другим наследникам; однако если все наследники первой очереди отказываются, наследство не переходит ко второй очереди, и наследственная масса ликвидируется мировым судом по гражданским делам по правилам банкротства. Заявление об отказе после того, как оно вступило в силу, по общему правилу отозвать нельзя. Наследник, вступивший во владение наследственной массой или совершивший необычное распоряжение, теряет право на отказ.","zh":"依法定程序放弃继承的继承人，免于对被继承人债权人的责任。若一名继承人放弃，其份额转归其他继承人；但若第一顺位继承人全部放弃，遗产不转归第二顺位，遗产（tereke）由民事和平法院依破产规定清算。放弃声明产生效力后原则上不可撤回。接管遗产或作出非常处分的继承人丧失放弃权。","ar":"الوارث الذي يرفض الميراث وفق الأصول يتحرّر من المسؤولية تجاه دائني المورّث. وإذا رفض وارث فإن حصته تنتقل إلى بقية الورثة؛ لكن إذا رفض جميع ورثة الطبقة الأولى فلا ينتقل الميراث إلى الطبقة الثانية وتُصفّى التركة عن طريق محكمة الصلح المدنية وفق أحكام الإفلاس. ولا يمكن كقاعدة الرجوع عن بيان الردّ بعد ترتيبه أثره. والوارث الذي يستولي على التركة أو يقوم بتصرف غير اعتيادي يفقد حق الردّ."},"Ret dilekçesi":{"en":"Petition of renunciation","ru":"Заявление об отказе","zh":"放弃申请书","ar":"عريضة الردّ"},"Murisin ölüm belgesi ve nüfus kayıt örneği":{"en":"The deceased's death certificate and population registration copy","ru":"Свидетельство о смерти и выписка из записей актов гражданского состояния наследодателя","zh":"被继承人（muris）的死亡证明和户籍记录副本","ar":"شهادة وفاة المورّث ونموذج قيد الأحوال المدنية"},"Mirasçının kimlik belgesi":{"en":"The heir's identity document","ru":"Документ, удостоверяющий личность наследника","zh":"继承人的身份证件","ar":"وثيقة هوية الوارث"},"Mirasçılığı gösteren belgeler":{"en":"Documents showing heirship","ru":"Документы, подтверждающие право наследования","zh":"证明继承资格的文件","ar":"الوثائق المُظهِرة لصفة الإرث"},"3 ay (yasal süre; kaçırılması halinde hak kaybı doğar)":{"en":"3 months (statutory period; missing it results in loss of rights)","ru":"3 месяца (законный срок; при его пропуске возникает утрата права)","zh":"3 个月（法定期限；错过将导致权利丧失）","ar":"3 أشهر (مدة قانونية؛ يترتب على تفويتها فقدان الحق)"},"Miras kalan taşınmazın borçlu mu yoksa değerli mi olduğu belirsizse, 3 aylık süre içinde terekenin tespitini isteyin ve karar vermeden önce mal ile borç dengesini analiz ettirin. Süre çok kritik olduğundan bu adımda mutlaka hukuki destek alın.":{"en":"If it is unclear whether the inherited property is indebted or valuable, request a determination of the estate within the 3-month period and have the balance of assets and debts analyzed before deciding. Because the period is very critical, be sure to obtain legal support at this step.","ru":"Если неясно, обременена ли унаследованная недвижимость долгами или является ценной, в течение 3-месячного срока потребуйте установления состава наследственной массы и до принятия решения закажите анализ баланса имущества и долгов. Поскольку срок очень критичен, на этом шаге обязательно получите юридическую поддержку.","zh":"若继承房产是负债还是有价值尚不明确，请在 3 个月内申请对遗产（tereke）进行清点，并在做决定前分析财产与债务的平衡。由于时限极为关键，此步骤务必寻求法律支持。","ar":"إذا كان غير واضح هل العقار الموروث مدين أم ذو قيمة، فاطلبوا خلال مدة الـ 3 أشهر جرد التركة، واطلبوا تحليل توازن المال والدَّين قبل اتخاذ القرار. وبما أن المدة حرجة جداً فاحصلوا حتماً على دعم قانوني في هذه الخطوة."},"Miras Payının Devri, Feragat ve Mirasçılar Arası Hisse Satışı":{"en":"Transfer of the Inheritance Share, Waiver and Sale of Shares Among Heirs","ru":"Передача наследственной доли, отказ и продажа доли между наследниками","zh":"继承份额的转让、放弃与继承人之间的份额买卖","ar":"نقل حصة الميراث والتنازل وبيع الحصص بين الورثة"},"Mirasçılar terekenin tamamlanmasına kadar taşınmaz üzerinde elbirliği mülkiyeti halinde hak sahibidir ve kural olarak ancak birlikte hareket ederek tasarruf edebilirler. Bir mirasçı, kendi payını diğer mirasçılara veya üçüncü bir kişiye devrederek mirastan fiilen çekilebilir (feragat edebilir). Payın diğer mirasçılara devri için yazılı sözleşme yeterlidir; buna karşılık üçüncü kişiye yapılacak miras payı devri sözleşmesinin geçerliliği daha sıkı şekil şartlarına bağlıdır ve genellikle noterde düzenlenmesi gerekir (güncel mevzuata göre teyit ediniz).":{"en":"Until the estate is settled, the heirs hold rights over the property as joint ownership (elbirliği mülkiyeti) and, as a rule, can dispose of it only by acting together. An heir can effectively withdraw from the inheritance (waive) by transferring their own share to the other heirs or to a third party. A written contract is sufficient for transferring the share to the other heirs; by contrast, the validity of an inheritance-share transfer contract to a third party is subject to stricter formal requirements and generally must be drawn up before a notary (confirm according to current legislation).","ru":"До завершения формирования наследственной массы наследники являются правообладателями недвижимости в режиме совместной собственности и по общему правилу могут распоряжаться ею только действуя сообща. Наследник может фактически выйти из наследства (отказаться), передав свою долю другим наследникам или третьему лицу. Для передачи доли другим наследникам достаточно письменного договора; напротив, действительность договора передачи наследственной доли третьему лицу зависит от более строгих требований к форме и, как правило, требует нотариального оформления (уточните согласно действующему законодательству).","zh":"在遗产清算完成前，继承人对房产以共同共有的形式享有权利，原则上只能共同行动方可处分。一名继承人可将自己的份额转让给其他继承人或第三人，从而实际退出继承（可作出放弃）。份额向其他继承人转让，书面合同即可；相对地，向第三人转让继承份额的合同其效力取决于更严格的形式要件，通常须在公证处订立（请依现行法规确认）。","ar":"يكون الورثة حتى إتمام التركة أصحاب حق على العقار على شكل ملكية بالاشتراك (elbirliği mülkiyeti)، ولا يمكنهم كقاعدة التصرف إلا بالعمل مجتمعين. ويمكن لوارث أن ينسحب فعلياً من الميراث (يتنازل) بنقل حصته إلى بقية الورثة أو إلى شخص ثالث. ويكفي لنقل الحصة إلى بقية الورثة عقد مكتوب؛ في المقابل تخضع صحة عقد نقل حصة الميراث إلى شخص ثالث لشروط شكلية أشد وعادةً يجب تنظيمه لدى الكاتب بالعدل (تأكّدوا وفق التشريعات السارية)."},"Payların birleştirilmesiyle bir mirasçı diğerlerinin payını satın alarak mülkü tek elde toplayabilir; bu, hem satışı kolaylaştırır hem de değeri korur. Dikkat: paylı mülkiyette bir paydaş payını dışarıdan üçüncü bir kişiye satarsa, diğer paydaşların yasal önalım (şufa) hakkı devreye girer. Önalım hakkı, satışın noter bildirimiyle öğrenilmesinden itibaren yaklaşık 3 ay ve her halde satış tarihinden itibaren en geç 2 yıl içinde kullanılabilir; süresinde açılan davada paydaş, payı aynı satış şartlarıyla satın alabilir.":{"en":"By consolidating shares, one heir can gather the property into single ownership by buying the others' shares; this both facilitates the sale and preserves value. Note: in shared ownership, if one co-owner sells their share to an outside third party, the other co-owners' statutory right of pre-emption (şufa) comes into play. The right of pre-emption can be exercised within approximately 3 months of learning of the sale through notary notification and, in any event, within at most 2 years from the date of sale; in a suit filed within the time limit, the co-owner can buy the share on the same terms as the sale.","ru":"Путём объединения долей один наследник может собрать недвижимость в одних руках, выкупив доли остальных; это и облегчает продажу, и сохраняет стоимость. Внимание: если при долевой собственности один из сособственников продаёт свою долю постороннему третьему лицу, вступает в действие законное право преимущественной покупки (şufa) других сособственников. Право преимущественной покупки может быть реализовано приблизительно в течение 3 месяцев с момента, когда о продаже стало известно из нотариального уведомления, и в любом случае не позднее чем в течение 2 лет с даты продажи; по иску, поданному в срок, сособственник может выкупить долю на тех же условиях продажи.","zh":"通过合并份额，一名继承人可买下其他人的份额，将房产集于一手；这既便于出售，也保全价值。注意：在按份共有中，若一名共有人将其份额出售给外部第三人，其他共有人的法定优先购买权（şufa）即被触发。优先购买权自通过公证通知获知出售之日起约 3 个月内、且无论如何自出售之日起最迟 2 年内可行使；在期限内提起的诉讼中，共有人可按相同的出售条件买下该份额。","ar":"بدمج الحصص يمكن لوارث أن يجمع العقار في يد واحدة بشراء حصص الآخرين؛ وهذا يسهّل البيع ويحفظ القيمة معاً. انتبهوا: في الملكية المشاعة إذا باع أحد الشركاء حصته إلى شخص ثالث من الخارج، فإن حق الشفعة (şufa) القانوني لبقية الشركاء يدخل حيّز التطبيق. ويمكن استعمال حق الشفعة تقريبًا خلال 3 أشهر من العلم بالبيع عبر تبليغ الكاتب بالعدل وفي كل الأحوال خلال سنتين كحد أقصى من تاريخ البيع؛ وفي الدعوى المرفوعة في المدة يمكن للشريك شراء الحصة بالشروط نفسها للبيع."},"Miras payı devri / feragat sözleşmesi (üçüncü kişiye devirde çoğunlukla noter şekli)":{"en":"Inheritance-share transfer / waiver contract (mostly in notarial form when transferred to a third party)","ru":"Договор передачи наследственной доли / отказа (при передаче третьему лицу — чаще всего в нотариальной форме)","zh":"继承份额转让／放弃合同（向第三人转让多为公证形式）","ar":"عقد نقل حصة الميراث / التنازل (في النقل إلى شخص ثالث غالباً بشكل الكاتب بالعدل)"},"Veraset ilamı":{"en":"Certificate of inheritance (Veraset İlamı)","ru":"Свидетельство о праве на наследство (Veraset İlamı)","zh":"继承权证明（Veraset İlamı）","ar":"حجة الوراثة (Veraset İlamı)"},"Tarafların kimlik belgeleri":{"en":"Identity documents of the parties","ru":"Документы, удостоверяющие личность сторон","zh":"当事方的身份证件","ar":"وثائق هوية الأطراف"},"Tapu kayıt bilgileri":{"en":"Title-deed record details","ru":"Данные записи в тапу","zh":"房产证登记信息","ar":"معلومات قيد سند الملكية"},"Diğer paydaşlara yapılacak noter önalım bildirimi (dış satışta önerilir)":{"en":"Notarial pre-emption notice to be served on the other co-owners (recommended in an outside sale)","ru":"Нотариальное уведомление других сособственников о преимущественной покупке (рекомендуется при продаже на сторону)","zh":"向其他共有人作出的公证优先购买权（şufa）通知（外部出售时建议）","ar":"تبليغ الشفعة عبر الكاتب بالعدل إلى بقية الشركاء (يُنصَح به في البيع الخارجي)"},"Sözleşme aşaması kısa; anlaşmazlık halinde önalım/dava süreci aylara yayılabilir (yaklaşık)":{"en":"The contract stage is short; in the event of dispute, the pre-emption/litigation process can extend over months (approximate)","ru":"Этап договора короткий; при споре процесс преимущественной покупки/суда может растянуться на месяцы (приблизительно)","zh":"合同阶段短暂；如有争议，优先购买权/诉讼流程可延展至数月（约值）","ar":"مرحلة العقد قصيرة؛ وفي حالة النزاع قد تمتد عملية الشفعة/الدعوى إلى أشهر (تقريبًا)"},"Dışarıya hisse satışında ileride şufa davasıyla satışın bozulmasını önlemek için diğer paydaşlara noter aracılığıyla usulüne uygun önalım bildirimi yapın. Mümkünse önce mirasçılar arası pay birleştirmesini değerlendirin; tek malikli bir tapu piyasada çok daha kolay ve yüksek değerle satılır.":{"en":"In a sale of shares to outsiders, serve a duly executed pre-emption notice on the other co-owners through a notary to prevent the sale from later being undone by a pre-emption (şufa) suit. If possible, consider consolidating shares among the heirs first; a single-owner title deed sells far more easily and at a higher value on the market.","ru":"При продаже доли на сторону, чтобы в будущем предотвратить аннулирование продажи иском о преимущественной покупке (şufa), направьте другим сособственникам надлежащее нотариальное уведомление о преимущественной покупке. По возможности сначала рассмотрите объединение долей между наследниками; тапу с единственным собственником продаётся на рынке гораздо легче и по более высокой стоимости.","zh":"在向外部出售份额时，为避免日后因优先购买权（şufa）之诉而使出售被推翻，请通过公证向其他共有人作出符合程序的优先购买权通知。若可能，请先考虑继承人之间的份额合并；单一所有权人的房产证在市场上更易且以更高价值售出。","ar":"في بيع الحصة إلى الخارج، ولتفادي إبطال البيع مستقبلاً بدعوى شفعة، وجّهوا إلى بقية الشركاء تبليغ شفعة أصولياً عبر الكاتب بالعدل. وإن أمكن، فقيّموا أولاً دمج الحصص بين الورثة؛ فسند الملكية بمالك واحد يُباع في السوق بسهولة أكبر وقيمة أعلى بكثير."},"İzale-i Şuyu (Ortaklığın Giderilmesi) Davası":{"en":"Partition Action (İzale-i Şuyu / Dissolution of Co-ownership)","ru":"Иск о разделе общей собственности (İzale-i Şuyu / прекращение общей собственности)","zh":"共有物分割之诉（İzale-i Şuyu，消除共有）","ar":"دعوى إزالة الشيوع (İzale-i Şuyu) (إنهاء الشراكة)"},"Mirasçılar taşınmazın ne yapılacağında anlaşamazsa (kimi satmak, kimi tutmak isterse), paylı veya elbirliği mülkiyetini sona erdirmek için Sulh Hukuk Mahkemesinde ortaklığın giderilmesi (izale-i şuyu) davası açılabilir. Ortaklık iki yolla giderilir: aynen taksim (malın fiziksel olarak bölüştürülmesi) veya satış suretiyle paylaşma (mahkeme kararıyla açık artırmayla satılıp bedelin paylara göre dağıtılması). Uygulamada bölünmesi mümkün olmayan daire, ev gibi taşınmazlarda genellikle satış yolu uygulanır. Görevli mahkeme Sulh Hukuk Mahkemesi, yetkili yer ise taşınmazın bulunduğu yerdir.":{"en":"If the heirs cannot agree on what to do with the property (some wishing to sell, some to keep), a partition action (İzale-i Şuyu / dissolution of co-ownership) can be filed at the Civil Court of Peace to end shared or joint ownership. Co-ownership is dissolved in two ways: partition in kind (physically dividing the property) or division by sale (sale by public auction under a court decision, with the proceeds distributed according to the shares). In practice, for properties that cannot be divided, such as an apartment or a house, the sale route is generally applied. The competent court is the Civil Court of Peace, and the competent venue is the place where the property is located.","ru":"Если наследники не могут договориться о том, что делать с недвижимостью (одни хотят продать, другие — сохранить), для прекращения долевой или совместной собственности в мировом суде по гражданским делам может быть подан иск о разделе общей собственности (İzale-i Şuyu). Общая собственность прекращается двумя способами: раздел в натуре (физическое разделение имущества) или раздел путём продажи (продажа с публичных торгов по решению суда с распределением выручки по долям). На практике для неделимых объектов, таких как квартира или дом, обычно применяется путь продажи. Компетентный суд — мировой суд по гражданским делам, а надлежащее место — по месту нахождения недвижимости.","zh":"若继承人对房产如何处置无法达成一致（有人想卖、有人想留），为终止按份或共同共有，可向民事和平法院提起消除共有（共有物分割，izale-i şuyu）之诉。共有以两种方式消除：实物分割（将财产以物理方式分开）或以出售方式分配（依法院裁定通过公开拍卖出售，并按份额分配价款）。在实务中，对公寓、住宅等无法分割的房产，通常适用出售途径。管辖法院为民事和平法院，有权地点则为房产所在地。","ar":"إذا لم يتفق الورثة على مصير العقار (فبعضهم يريد البيع وبعضهم الاحتفاظ)، يمكن رفع دعوى إزالة الشيوع (İzale-i Şuyu) في محكمة الصلح المدنية لإنهاء الملكية المشاعة أو الملكية بالاشتراك. وتُزال الشراكة بطريقين: القسمة العينية (تقسيم المال فيزيائياً) أو القسمة عن طريق البيع (البيع بالمزاد العلني بقرار المحكمة وتوزيع الثمن حسب الحصص). وفي التطبيق يُطبَّق غالباً طريق البيع في العقارات التي يتعذّر تقسيمها مثل الشقة والمنزل. والمحكمة المختصة هي محكمة الصلح المدنية، والمكان المختص هو مكان وجود العقار."},"1 Eylül 2023 tarihinden itibaren ortaklığın giderilmesi davalarında dava açılmadan önce zorunlu arabuluculuk şartı getirilmiştir; arabuluculuk süreci tamamlanmadan dava açılamaz. Süreç genellikle uzundur: ilk derece mahkemesinde yaklaşık 1 ila 1,5 yıl, istinaf ve temyiz aşamalarıyla toplam yaklaşık 3 ila 5 yıla kadar uzayabilir (paydaş sayısı ve tebligatlar süreyi etkiler). Masraflar (harç, gider avansı, bilirkişi, keşif, avukatlık) dava sonunda tüm hissedarlara payları oranında paylaştırılır.":{"en":"As of 1 September 2023, in partition actions a mandatory mediation requirement was introduced before the suit is filed; the suit cannot be filed until the mediation process is completed. The process is generally long: approximately 1 to 1.5 years at the court of first instance, and, with the appeal and cassation stages, it can extend to a total of approximately 3 to 5 years (the number of co-owners and service of process affect the duration). The costs (fees, expense advance, expert witness, on-site inspection, attorney) are apportioned among all co-owners according to their shares at the end of the suit.","ru":"С 1 сентября 2023 года по искам о разделе общей собственности введено требование обязательной медиации до подачи иска; без завершения процедуры медиации иск подать нельзя. Процесс обычно длительный: в суде первой инстанции приблизительно от 1 до 1,5 лет, а со стадиями апелляции и кассации может растянуться в общей сложности приблизительно до 3-5 лет (число сособственников и извещения влияют на срок). Расходы (пошлина, аванс на издержки, эксперт, выезд на осмотр, услуги адвоката) по завершении дела распределяются между всеми дольщиками пропорционально их долям.","zh":"自 2023年9月1日 起，消除共有诉讼在起诉前须先经强制调解；调解流程未完成则无法起诉。流程通常漫长：一审约 1 至 1.5 年，加上上诉和最高法院阶段，合计可延展至约 3 至 5 年（共有人数量和送达会影响时长）。费用（诉讼费、费用预付款、鉴定人、勘验、律师费）在诉讼结束时按份额比例分摊给全体共有人。","ar":"اعتباراً من 1 سبتمبر 2023 أُقرّ شرط الوساطة الإلزامية قبل رفع دعوى إزالة الشيوع؛ ولا يمكن رفع الدعوى قبل إتمام عملية الوساطة. والعملية طويلة عادةً: نحو سنة إلى سنة ونصف في محكمة الدرجة الأولى، وقد تمتد إجمالاً إلى نحو 3 إلى 5 سنوات مع مرحلتَي الاستئناف والتمييز (يؤثر عدد الشركاء والتبليغات في المدة). وتُوزَّع المصاريف (الرسم وسلفة النفقات والخبير والكشف وأتعاب المحاماة) على جميع الشركاء بنسبة حصصهم في نهاية الدعوى."},"Arabuluculuk son tutanağı (anlaşmama)":{"en":"Final mediation report (non-agreement)","ru":"Итоговый протокол медиации (недостижение соглашения)","zh":"调解最终笔录（未达成一致）","ar":"المحضر الأخير للوساطة (عدم الاتفاق)"},"Dava dilekçesi":{"en":"Statement of claim","ru":"Исковое заявление","zh":"起诉书","ar":"عريضة الدعوى"},"Veraset ilamı ve tapu kaydı":{"en":"Certificate of inheritance (Veraset İlamı) and title-deed record","ru":"Свидетельство о праве на наследство и запись в тапу","zh":"继承权证明（Veraset İlamı）和房产证登记","ar":"حجة الوراثة (Veraset İlamı) وقيد سند الملكية"},"Taşınmaza ilişkin belgeler":{"en":"Documents relating to the property","ru":"Документы, относящиеся к недвижимости","zh":"与房产相关的文件","ar":"الوثائق المتعلقة بالعقار"},"Paydaşların bilgileri":{"en":"Co-owners' details","ru":"Данные сособственников","zh":"共有人的信息","ar":"معلومات الشركاء"},"İlk derece yaklaşık 1-1,5 yıl; istinaf/temyiz ile toplam yaklaşık 3-5 yıl (yaklaşık, dosyaya göre değişir)":{"en":"First instance approximately 1-1.5 years; with appeal/cassation, a total of approximately 3-5 years (approximate, varies by case)","ru":"Первая инстанция — приблизительно 1-1,5 года; с апелляцией/кассацией в общей сложности приблизительно 3-5 лет (приблизительно, зависит от дела)","zh":"一审约 1-1.5 年；加上上诉/最高法院合计约 3-5 年（约值，因案卷而异）","ar":"الدرجة الأولى نحو 1-1.5 سنة؛ مع الاستئناف/التمييز إجمالاً نحو 3-5 سنوات (تقريبًا، تتغير حسب الملف)"},"Mahkeme satışı (icra/ihale) genellikle piyasa değerinin altında sonuçlanır ve uzun sürer. Bu yüzden dava açmadan önce anlaşmalı serbest piyasa satışını deneyin; profesyonel değerleme ve tarafsız bir emlak ofisi çoğu zaman izale-i şuyudan daha yüksek ve hızlı sonuç verir. Tüm paydaşlar isterse mahkeme ihalesi yalnızca paydaşlar arasında da yapılabilir.":{"en":"A court sale (enforcement/auction) generally concludes below market value and takes a long time. For this reason, before filing suit, try an agreed open-market sale; a professional valuation and an impartial real estate office often deliver a higher and faster result than a partition action. If all co-owners wish, the court auction can also be held among the co-owners only.","ru":"Судебная продажа (исполнительное производство/торги) обычно завершается ниже рыночной стоимости и длится долго. Поэтому до подачи иска попробуйте согласованную продажу на свободном рынке; профессиональная оценка и беспристрастное агентство недвижимости чаще всего дают более высокий и быстрый результат, чем иск о разделе общей собственности (İzale-i Şuyu). Если все сособственники согласны, судебные торги могут проводиться и только между сособственниками.","zh":"法院拍卖（强制执行/竞拍）通常以低于市场价值成交，且历时漫长。因此在起诉前请先尝试协议式的自由市场出售；专业估价和中立的房产中介往往比共有物分割之诉带来更高、更快的结果。若全体共有人愿意，法院拍卖也可仅在共有人之间进行。","ar":"بيع المحكمة (التنفيذ/المزاد) ينتهي عادةً دون القيمة السوقية ويستغرق وقتاً طويلاً. لذلك جرّبوا قبل رفع الدعوى البيع الرضائي في السوق الحرة؛ فالتقييم الاحترافي والمكتب العقاري المحايد يعطيان في الغالب نتيجة أعلى وأسرع من إزالة الشيوع. وإذا رغب جميع الشركاء يمكن إجراء مزاد المحكمة بين الشركاء وحدهم فقط."},"Maliyet & harç notları":{"en":"Cost & fee notes","ru":"Заметки о затратах и пошлинах","zh":"成本与税费须知","ar":"ملاحظات التكلفة والرسوم"},"Miras ve intikal sürecindeki başlıca kalemler şunlardır (tümü yaklaşık ve güncel mevzuata göre değişir):":{"en":"The main items in the inheritance and transfer process are as follows (all approximate and subject to change according to current legislation):","ru":"Основные статьи в процессе наследства и перехода имущества таковы (все приблизительны и меняются согласно действующему законодательству):","zh":"遗产与继承过户流程中的主要项目如下（均为近似值，并因现行法规而异）：","ar":"أبرز البنود في عملية الميراث والانتقال هي التالية (جميعها تقريبية وتتغير حسب التشريعات السارية):"},"Veraset ilamı ücreti noterde veya mahkemede binlerce TL düzeyinde bir masraf gerektirir.":{"en":"The certificate of inheritance fee entails a cost in the thousands of TL at a notary or court.","ru":"Стоимость свидетельства о праве на наследство у нотариуса или в суде требует расхода на уровне нескольких тысяч TL.","zh":"继承权证明费用在公证处或法院需数千 TL 级别的支出。","ar":"يتطلب رسم حجة الوراثة لدى الكاتب بالعدل أو في المحكمة مصروفاً بمستوى آلاف الـ TL."},"Tapu intikalinde miras yoluyla devirde tapu harcı ödenmez; yalnızca döner sermaye ve ilave hizmet bedeli alınır (2026 için toplam yaklaşık 2.500 TL civarı, her yıl güncellenir).":{"en":"In transfer by inheritance, no title-deed fee is paid on the conveyance; only the revolving fund and additional service fee are charged (for 2026, approximately 2,500 TL in total, updated each year).","ru":"При переоформлении тапу в порядке перехода по наследству пошлина за тапу не уплачивается; взимаются только сбор оборотного фонда и дополнительный сбор за услугу (на 2026 год в общей сложности около 2 500 TL, ежегодно обновляется).","zh":"在房产证继承过户中，通过遗产继承的过户不缴纳房产证费；仅收取周转基金费和附加服务费（2026 年合计约 2,500 TL 左右，每年更新）。","ar":"في انتقال سند الملكية عن طريق الميراث لا يُدفَع رسم سند الملكية؛ ويُؤخَذ فقط الصندوق الدوّار وبدل الخدمة الإضافي (لعام 2026 نحو 2.500 TL إجمالاً تقريبًا، يُحدَّث كل عام)."},"Veraset ve İntikal Vergisi artan oranlıdır (veraset yoluyla intikalde yaklaşık yüzde 1-10); füru ve eşe düşen paylarda yüksek bir istisna tutarı uygulanır (2026 için kişi başı yaklaşık 2,9 milyon TL civarı, resmi tebliğe göre değişir)":{"en":"The Inheritance and Transfer Tax is progressive (approximately 1-10% on transfer by inheritance); a high exemption amount applies to the shares falling to descendants and the spouse (for 2026, approximately 2.9 million TL per person, changing according to the official communiqué)","ru":"Налог на наследство и переход имущества прогрессивный (при переходе по наследству приблизительно 1-10%); для долей, приходящихся на нисходящих родственников и супруга, применяется высокая сумма льготы (на 2026 год около 2,9 млн TL на человека, меняется согласно официальному сообщению)","zh":"遗产与继承税为累进制（通过遗产过户约 1-10%）；对直系卑亲属和配偶应得的份额适用较高的免税额（2026 年每人约 2.9 百万 TL 左右，因官方公告而变动）","ar":"ضريبة الميراث والانتقال تصاعدية (في الانتقال عن طريق الميراث نحو 1-10%)؛ ويُطبَّق في الحصص المستحقة للفروع والزوج مبلغ استثناء مرتفع (لعام 2026 نحو 2.9 مليون TL للفرد تقريبًا، يتغير حسب التبليغ الرسمي)"},"ve vergi 3 yıla yayılı 6 taksitte faizsiz ödenebilir.":{"en":"and the tax can be paid interest-free in 6 installments spread over 3 years.","ru":"и налог может уплачиваться без процентов 6 частями с рассрочкой на 3 года.","zh":"且税款可分 6 期、延展至 3 年无息缴纳。","ar":"ويمكن سداد الضريبة بلا فائدة على 6 أقساط موزّعة على 3 سنوات."},"İzale-i şuyu davasında maktu harç, gider avansı, bilirkişi, keşif ve avukatlık ücretleri doğar; bu masraflar dava sonunda paydaşlara payları oranında bölüştürülür.":{"en":"In a partition (İzale-i Şuyu) action, a fixed fee, expense advance, expert-witness, on-site inspection and attorney fees arise; these costs are apportioned among the co-owners according to their shares at the end of the suit.","ru":"По иску о разделе общей собственности (İzale-i Şuyu) возникают фиксированная пошлина, аванс на издержки, оплата эксперта, выезда на осмотр и услуг адвоката; эти расходы по завершении дела распределяются между сособственниками пропорционально их долям.","zh":"在共有物分割之诉中会产生固定诉讼费、费用预付款、鉴定人、勘验和律师费；这些费用在诉讼结束时按份额比例分摊给共有人。","ar":"في دعوى إزالة الشيوع تنشأ رسوم مقطوعة وسلفة نفقات وأتعاب خبير وكشف ومحاماة؛ وتُوزَّع هذه المصاريف على الشركاء بنسبة حصصهم في نهاية الدعوى."},"Satış aşamasında ayrıca alıcı-satıcı tapu devir harcı (satış bedeli üzerinden, taraflara ait), varsa değer artış kazancı vergisi ve emlak komisyonu gündeme gelir.":{"en":"At the sale stage, the buyer-seller title-deed transfer fee (on the sale price, borne by the parties), any capital gains tax and the real estate commission also come into play.","ru":"На этапе продажи дополнительно возникают пошлина за переоформление тапу для покупателя и продавца (от суммы продажи, за счёт сторон), при наличии — налог на прирост стоимости и комиссия за недвижимость.","zh":"在出售阶段还会涉及买卖双方的房产证过户费（按成交价、由当事方承担）、如有的增值收益税以及房产中介佣金。","ar":"في مرحلة البيع تُطرَح إضافةً إلى ذلك رسوم نقل سند الملكية للمشتري-البائع (على قيمة البيع، على الأطراف)، وضريبة أرباح ارتفاع القيمة إن وُجدت، وعمولة العقار."},"Kesin tutarlar için mutlaka ilgili tapu müdürlüğü, vergi dairesi ve güncel resmi tarifelere başvurulmalıdır.":{"en":"For exact amounts, the relevant land registry directorate, tax office and current official tariffs must be consulted.","ru":"За точными суммами обязательно следует обратиться в соответствующее управление кадастра, налоговую инспекцию и к действующим официальным тарифам.","zh":"关于确切金额，务必查阅相关房产证登记处、税务局和最新的官方费率表。","ar":"للمبالغ القطعية يجب حتماً مراجعة المديرية المعنية لسند الملكية ودائرة الضرائب والتعرفات الرسمية السارية."},"Miras & intikal · Sık sorulanlar":{"en":"Inheritance & transfer · FAQ","ru":"Наследство и переход имущества · Часто задаваемые вопросы","zh":"遗产与继承 · 常见问题","ar":"الميراث والانتقال · الأسئلة الشائعة"},"Miras kalan bir evi satmak için ne gerekir?":{"en":"What is needed to sell an inherited home?","ru":"Что нужно, чтобы продать унаследованный дом?","zh":"出售继承而来的房子需要什么？","ar":"ما الذي يلزم لبيع منزل موروث؟"},"Önce veraset ilamı (mirasçılık belgesi) alınmalı, Veraset ve İntikal Vergisi beyannamesi verilip vergi tamamlanmalı ve taşınmaz tapuda mirasçılar adına intikal ettirilmelidir. Ancak bu üç adım tamamlandıktan sonra satış yapılabilir. Birden fazla mirasçı varsa satış için kural olarak tüm paydaşların onayı gerekir.":{"en":"First the certificate of inheritance (Veraset İlamı) must be obtained, the Inheritance and Transfer Tax return filed and the tax completed, and the property transferred at the land registry into the heirs' names. Only after these three steps are completed can the sale take place. If there is more than one heir, the sale, as a rule, requires the consent of all co-owners.","ru":"Сначала нужно получить свидетельство о праве на наследство (Veraset İlamı / документ о наследовании), подать декларацию по налогу на наследство и переход имущества и уплатить налог, а также переоформить недвижимость в тапу на наследников. Продажу можно совершить только после завершения этих трёх шагов. Если наследников несколько, для продажи по общему правилу требуется согласие всех сособственников.","zh":"首先须取得继承权证明（Veraset İlamı，继承人证明），提交遗产与继承税申报表并完成税款，再将房产在房产证上过户至继承人名下。只有在这三个步骤完成后，方可出售。若有多位继承人，出售原则上需全体共有人同意。","ar":"يجب أولاً الحصول على حجة الوراثة (Veraset İlamı) (وثيقة صفة الإرث)، وتقديم إقرار ضريبة الميراث والانتقال وإتمام الضريبة، ونقل العقار في سند الملكية باسم الورثة. ولا يمكن البيع إلا بعد إتمام هذه الخطوات الثلاث. وإذا وُجد أكثر من وارث فيلزم كقاعدة موافقة جميع الشركاء للبيع."},"İntikal yapmadan miras kalan mülk satılabilir mi?":{"en":"Can inherited property be sold without carrying out the transfer?","ru":"Можно ли продать унаследованную недвижимость без переоформления?","zh":"未办继承过户，继承而来的房产可以出售吗？","ar":"هل يمكن بيع العقار الموروث دون إجراء الانتقال؟"},"Hayır. Kişi sahibi olmadığı bir malı devredemez; bu nedenle önce tapuda intikal işlemi tamamlanmalı, sonra satış yapılmalıdır. Ayrıca taşınmaza isabet eden Veraset ve İntikal Vergisi tamamen ödenmeden tapuda devir ve ferağ da yapılamaz.":{"en":"No. A person cannot transfer property they do not own; therefore the transfer at the land registry must be completed first, and then the sale can take place. In addition, until the Inheritance and Transfer Tax attributable to the property is paid in full, transfer and conveyance cannot be made at the land registry.","ru":"Нет. Человек не может передать имущество, которым не владеет; поэтому сначала нужно завершить переоформление в тапу, а затем совершать продажу. Кроме того, пока налог на наследство и переход имущества, приходящийся на недвижимость, не уплачен полностью, переоформление и отчуждение в тапу также невозможны.","zh":"不可以。人无法转让自己并不拥有的财产；因此须先在房产证上完成继承过户，再进行出售。此外，在归属于该房产的遗产与继承税未全部缴清前，房产证上也无法办理过户与让渡（ferağ）。","ar":"لا. لا يستطيع المرء نقل مال لا يملكه؛ لذلك يجب أولاً إتمام معاملة الانتقال في سند الملكية ثم البيع. كما لا يمكن إجراء النقل والتنازل في سند الملكية ما لم تُسدَّد كاملةً ضريبة الميراث والانتقال المستحقة على العقار."},"Veraset ve İntikal Vergisi ne kadardır ve ne zaman ödenir?":{"en":"How much is the Inheritance and Transfer Tax and when is it paid?","ru":"Каков размер налога на наследство и переход имущества и когда он уплачивается?","zh":"遗产与继承税是多少，何时缴纳？","ar":"كم ضريبة الميراث والانتقال ومتى تُسدَّد؟"},"Vergi artan oranlıdır; veraset yoluyla intikallerde yaklaşık yüzde 1 ile yüzde 10 arasında değişir. Çocuklara, torunlara ve eşe düşen paylarda yüksek bir istisna tutarı uygulanır (2026 için kişi başı yaklaşık 2,9 milyon TL civarı, resmi tebliğe göre güncellenir) ve bu tutarın altındaki paylarda vergi çıkmayabilir. Beyanname ölümden itibaren yaklaşık 4 ay içinde verilir; vergi ise izleyen 3 yıl boyunca her Mayıs ve Kasım ayında toplam 6 taksitte, faizsiz ödenebilir.":{"en":"The tax is progressive; on transfers by inheritance it ranges from approximately 1% to 10%. A high exemption amount applies to the shares falling to children, grandchildren and the spouse (for 2026, approximately 2.9 million TL per person, updated according to the official communiqué), and no tax may arise on shares below this amount. The return is filed within approximately 4 months of death; the tax can then be paid interest-free in 6 installments, each May and November over the following 3 years.","ru":"Налог прогрессивный; при переходе по наследству он составляет приблизительно от 1% до 10%. Для долей, приходящихся на детей, внуков и супруга, применяется высокая сумма льготы (на 2026 год около 2,9 млн TL на человека, обновляется согласно официальному сообщению), и по долям ниже этой суммы налога может не возникнуть. Декларация подаётся приблизительно в течение 4 месяцев с даты смерти; а налог может уплачиваться без процентов в общей сложности 6 частями — в мае и ноябре каждого из следующих 3 лет.","zh":"税款为累进制；通过遗产过户约在 1% 至 10% 之间变动。对子女、孙辈和配偶应得的份额适用较高的免税额（2026 年每人约 2.9 百万 TL 左右，因官方公告更新），低于该额度的份额可能无需缴税。申报表自死亡起约 4 个月内提交；税款则可在其后 3 年内、每年 5 月和 11 月分共 6 期无息缴纳。","ar":"الضريبة تصاعدية؛ وتتراوح في الانتقالات عن طريق الميراث تقريبًا بين 1% و10%. ويُطبَّق في الحصص المستحقة للأولاد والأحفاد والزوج مبلغ استثناء مرتفع (لعام 2026 نحو 2.9 مليون TL للفرد تقريبًا، يُحدَّث حسب التبليغ الرسمي) وقد لا تُستحَق ضريبة في الحصص دون هذا المبلغ. ويُقدَّم الإقرار خلال نحو 4 أشهر من الوفاة؛ أما الضريبة فيمكن سدادها بلا فائدة على 6 أقساط في شهري مايو ونوفمبر من كل عام على مدى 3 سنوات تالية."},"İzale-i şuyu (ortaklığın giderilmesi) davası ne kadar sürer?":{"en":"How long does a partition action (İzale-i Şuyu / dissolution of co-ownership) take?","ru":"Сколько длится иск о разделе общей собственности (İzale-i Şuyu / прекращение общей собственности)?","zh":"共有物分割之诉（İzale-i Şuyu，消除共有）需要多久？","ar":"كم تستغرق دعوى إزالة الشيوع (İzale-i Şuyu) (إنهاء الشراكة)؟"},"İlk derece mahkemesinde yaklaşık 1 ila 1,5 yıl sürer; istinaf ve temyiz aşamalarıyla toplam yaklaşık 3 ila 5 yıla kadar uzayabilir. Süre paydaş sayısına, tebligatlara ve dosyanın yoğunluğuna göre değişir. 1 Eylül 2023 sonrası bu davalarda önce zorunlu arabuluculuğa gidilmesi gerekir.":{"en":"It takes approximately 1 to 1.5 years at the court of first instance; with the appeal and cassation stages it can extend to a total of approximately 3 to 5 years. The duration varies according to the number of co-owners, service of process and the caseload. After 1 September 2023, these suits must first go through mandatory mediation.","ru":"В суде первой инстанции он длится приблизительно от 1 до 1,5 лет; со стадиями апелляции и кассации может растянуться в общей сложности приблизительно до 3-5 лет. Срок зависит от числа сособственников, извещений и загруженности дела. После 1 сентября 2023 года по таким искам сначала необходимо пройти обязательную медиацию.","zh":"一审约需 1 至 1.5 年；加上上诉和最高法院阶段，合计可延展至约 3 至 5 年。时长因共有人数量、送达和案卷繁重程度而异。2023年9月1日 之后，此类诉讼须先经强制调解。","ar":"تستغرق في محكمة الدرجة الأولى نحو سنة إلى سنة ونصف؛ وقد تمتد إجمالاً إلى نحو 3 إلى 5 سنوات مع مرحلتَي الاستئناف والتمييز. وتتغير المدة حسب عدد الشركاء والتبليغات وكثافة الملف. وبعد 1 سبتمبر 2023 يجب أولاً اللجوء إلى الوساطة الإلزامية في هذه الدعاوى."},"Veraset ilamını noterden mi mahkemeden mi almak daha iyidir?":{"en":"Is it better to obtain the certificate of inheritance from a notary or a court?","ru":"Свидетельство о праве на наследство лучше получать у нотариуса или в суде?","zh":"继承权证明是从公证处还是法院取得更好？","ar":"هل الأفضل الحصول على حجة الوراثة من الكاتب بالعدل أم من المحكمة؟"},"Belgeler eksiksizse ve karmaşık bir durum yoksa noter yolu çok daha hızlıdır; çoğu zaman aynı gün belge alınabilir. Ancak vasiyetname varsa, mirasçılardan biri yabancı uyrukluysa veya nüfus kayıtlarından soy bağı net tespit edilemiyorsa noter belge veremez; bu durumlarda Sulh Hukuk Mahkemesine başvurmak zorunludur.":{"en":"If the documents are complete and there is no complex situation, the notary route is much faster; the document can often be obtained the same day. However, if there is a will, if one of the heirs is a foreign national, or if the lineage cannot be clearly determined from the population records, the notary cannot issue the document; in these cases, application to the Civil Court of Peace is mandatory.","ru":"Если документы в порядке и нет сложной ситуации, путь через нотариуса гораздо быстрее; чаще всего документ можно получить в тот же день. Однако если есть завещание, если один из наследников — иностранный гражданин или если по записям актов гражданского состояния невозможно чётко установить родственную связь, нотариус не может выдать документ; в этих случаях обязательно обращаться в мировой суд по гражданским делам.","zh":"若文件齐全且不存在复杂情形，公证处途径快得多；多数情况下当天可取得文件。但若存在遗嘱、某位继承人为外国国籍，或无法从户籍记录明确确定血亲关系，公证处则不能出具文件；在这些情况下必须向民事和平法院申请。","ar":"إذا كانت الوثائق كاملة ولا توجد حالة معقّدة فطريق الكاتب بالعدل أسرع بكثير؛ ويمكن غالباً الحصول على الوثيقة في اليوم نفسه. لكن إذا وُجدت وصية، أو كان أحد الورثة من جنسية أجنبية، أو تعذّر تحديد صلة النسب بوضوح من سجلات الأحوال، فلا يستطيع الكاتب بالعدل إصدار الوثيقة؛ وفي هذه الحالات يكون اللجوء إلى محكمة الصلح المدنية إلزامياً."},"Reddi miras için sürem ne kadar ve nasıl yaparım?":{"en":"How long is my period for renunciation of inheritance and how do I do it?","ru":"Каков мой срок для отказа от наследства (Reddi Miras) и как это сделать?","zh":"放弃继承我有多长时限，如何办理？","ar":"كم مدتي لرفض الميراث وكيف أقوم به؟"},"Gerçek ret için süre kural olarak 3 aydır ve genellikle ölümü öğrendiğiniz tarihten başlar. Ret, murisin son yerleşim yeri Sulh Hukuk Mahkemesine kayıtsız ve şartsız beyanla yapılır; notere yapılan ret geçersizdir. Süreyi kaçırmak veya terekeye sahip çıkmak ret hakkını düşürür, bu yüzden bu adımda hukuki destek almak önemlidir.":{"en":"The period for actual renunciation is, as a rule, 3 months and generally starts from the date you learn of the death. Renunciation is made by an unconditional and unreserved declaration to the Civil Court of Peace of the deceased's last place of residence; a renunciation made to a notary is invalid. Missing the deadline or taking possession of the estate forfeits the right to renounce, so it is important to obtain legal support at this step.","ru":"Срок для действительного отказа по общему правилу составляет 3 месяца и обычно начинается с даты, когда вы узнали о смерти. Отказ совершается безоговорочным и безусловным заявлением в мировой суд по гражданским делам по последнему месту жительства наследодателя; отказ, поданный нотариусу, недействителен. Пропуск срока или вступление во владение наследственной массой лишает права на отказ, поэтому на этом шаге важно получить юридическую поддержку.","zh":"真正放弃的时限原则上为 3 个月，通常自您获知死亡之日起算。放弃须以无保留、无条件的声明向被继承人最后居所地的民事和平法院作出；向公证处作出的放弃无效。错过时限或接管遗产会使放弃权消灭，因此此步骤寻求法律支持很重要。","ar":"مدة الردّ الحقيقي كقاعدة 3 أشهر وتبدأ عادةً من تاريخ علمكم بالوفاة. ويُقدَّم الردّ إلى محكمة الصلح المدنية لمحل الإقامة الأخير للمورّث ببيان دون قيد أو شرط؛ والردّ المقدَّم إلى الكاتب بالعدل باطل. وتفويت المدة أو الاستيلاء على التركة يُسقِط حق الردّ، لذلك من المهم الحصول على دعم قانوني في هذه الخطوة."},"Mirasçılardan biri satışa yanaşmıyorsa ne yapabilirim?":{"en":"What can I do if one of the heirs is unwilling to sell?","ru":"Что я могу сделать, если один из наследников не соглашается на продажу?","zh":"若某位继承人不愿出售，我该怎么办？","ar":"ماذا يمكنني أن أفعل إذا رفض أحد الورثة البيع؟"},"Öncelikle o mirasçının payını satın alarak (pay birleştirmesi) veya anlaşmalı çözümlerle uzlaşma denenmelidir. Uzlaşma sağlanamazsa, zorunlu arabuluculuk sonrası Sulh Hukuk Mahkemesinde izale-i şuyu (ortaklığın giderilmesi) davası açılarak taşınmazın satılıp bedelinin paylara göre dağıtılması istenebilir.":{"en":"First, settlement should be attempted by buying that heir's share (share consolidation) or through agreed solutions. If settlement cannot be reached, after mandatory mediation a partition action (İzale-i Şuyu / dissolution of co-ownership) can be filed at the Civil Court of Peace to have the property sold and its proceeds distributed according to the shares.","ru":"Прежде всего следует попытаться достичь согласия, выкупив долю этого наследника (объединение долей) или через договорные решения. Если согласия достичь не удаётся, после обязательной медиации в мировом суде по гражданским делам можно подать иск о разделе общей собственности (İzale-i Şuyu) и потребовать продажи недвижимости с распределением выручки по долям.","zh":"首先应尝试通过买下该继承人的份额（份额合并）或协议方式达成和解。若无法达成和解，则可在强制调解之后，向民事和平法院提起共有物分割之诉（消除共有），请求出售房产并按份额分配价款。","ar":"ينبغي أولاً محاولة التوصّل إلى تسوية بشراء حصة ذلك الوارث (دمج الحصص) أو بحلول رضائية. وإذا تعذّرت التسوية، يمكن بعد الوساطة الإلزامية رفع دعوى إزالة الشيوع (İzale-i Şuyu) في محكمة الصلح المدنية لطلب بيع العقار وتوزيع ثمنه حسب الحصص."},"Hisseli (paylı) tapuda kendi payımı dışarıya satabilir miyim?":{"en":"Can I sell my own share to an outsider on a shared (co-owned) title deed?","ru":"Могу ли я при долевом тапу продать свою долю на сторону?","zh":"在共有（按份）房产证中，我能把自己的份额卖给外部吗？","ar":"هل يمكنني بيع حصتي إلى الخارج في سند الملكية المشاع؟"},"Prensipte payınızı üçüncü bir kişiye satabilirsiniz; ancak diğer paydaşların yasal önalım (şufa) hakkı devreye girer. Paydaşlar, satışı noter bildirimiyle öğrendikten sonra yaklaşık 3 ay ve her halde satıştan itibaren en geç 2 yıl içinde, payı aynı şartlarla satın alma davası açabilir. Bu riski azaltmak için satıştan önce diğer paydaşlara noter aracılığıyla önalım bildirimi yapılması önerilir.":{"en":"In principle you can sell your share to a third party; however, the other co-owners' statutory right of pre-emption (şufa) comes into play. After learning of the sale through notary notification, the co-owners can file suit within approximately 3 months and, in any event, within at most 2 years from the sale, to buy the share on the same terms. To reduce this risk, it is recommended that a pre-emption notice be served on the other co-owners through a notary before the sale.","ru":"В принципе вы можете продать свою долю третьему лицу; однако вступает в действие законное право преимущественной покупки (şufa) других сособственников. Сособственники в течение приблизительно 3 месяцев после того, как узнали о продаже из нотариального уведомления, и в любом случае не позднее чем в течение 2 лет с даты продажи могут подать иск о выкупе доли на тех же условиях. Чтобы снизить этот риск, перед продажей рекомендуется направить другим сособственникам нотариальное уведомление о преимущественной покупке.","zh":"原则上您可将份额卖给第三人；但其他共有人的法定优先购买权（şufa）会被触发。共有人在通过公证通知获知出售后约 3 个月内、且无论如何自出售起最迟 2 年内，可提起按相同条件买下该份额之诉。为降低这一风险，建议在出售前通过公证向其他共有人作出优先购买权通知。","ar":"من حيث المبدأ يمكنكم بيع حصتكم إلى شخص ثالث؛ لكن حق الشفعة (şufa) القانوني لبقية الشركاء يدخل حيّز التطبيق. ويمكن للشركاء، بعد علمهم بالبيع عبر تبليغ الكاتب بالعدل، رفع دعوى لشراء الحصة بالشروط نفسها تقريبًا خلال 3 أشهر وفي كل الأحوال خلال سنتين كحد أقصى من البيع. ولتقليل هذا الخطر يُنصَح بتوجيه تبليغ شفعة إلى بقية الشركاء عبر الكاتب بالعدل قبل البيع."},"Hangi hizmete ihtiyacınız olduğundan emin değil misiniz?":{"en":"Not sure which service you need?","ru":"Не уверены, какая услуга вам нужна?","zh":"不确定您需要哪项服务？","ar":"ألستم متأكدين من الخدمة التي تحتاجونها؟"},"Gayrimenkulünüzü ya da hedefinizi anlatın; size en uygun süreci, bölge verisiyle birlikte 24 saat içinde planlayalım. İlk ekspertiz ve yönlendirme ücretsiz.":{"en":"Tell us about your property or your goal; let us plan the most suitable process for you, together with regional data, within 24 hours. The first appraisal and referral are free.","ru":"Расскажите о вашей недвижимости или вашей цели; мы вместе с данными по региону спланируем для вас наиболее подходящий процесс в течение 24 часов. Первая оценка и консультация бесплатны.","zh":"告诉我们您的房产或您的目标；我们会在 24 小时内连同区域数据，为您规划最合适的流程。首次估价和转介免费。","ar":"أخبرونا عن عقاركم أو هدفكم؛ ودعونا نخطّط لكم أنسب عملية مع بيانات المنطقة خلال 24 ساعة. التقييم والإرشاد الأول مجاناً."},"Ücretsiz Ekspertiz Al":{"en":"Get a Free Appraisal","ru":"Получить бесплатную оценку","zh":"获取免费估价","ar":"احصل على تقييم مجاني"},"WhatsApp'tan Yazın":{"en":"Message us on WhatsApp","ru":"Напишите в WhatsApp","zh":"通过 WhatsApp 联系","ar":"راسلونا عبر WhatsApp"},"Hizmetlerimiz — Danışmanlık, Değerleme, Yatırım · Meridyen Gayrimenkul":{"en":"Our Services — Advisory, Valuation, Investment · Meridyen Gayrimenkul","ru":"Наши услуги — консалтинг, оценка, инвестиции · Meridyen Gayrimenkul","zh":"我们的服务 — 顾问、估价、投资 · Meridyen Gayrimenkul","ar":"خدماتنا — استشارات، تقييم، استثمار · Meridyen Gayrimenkul"},"İzmir ve Ege’de alım-satım, kiralama, değerleme, yatırım danışmanlığı ve miras/intikal işlemleri. Veri odaklı, uctan uca emlak hizmetleri.":{"en":"Buying-selling, leasing, valuation, investment advisory and inheritance/transfer procedures in İzmir and the Aegean. Data-driven, end-to-end real estate services.","ru":"Купля-продажа, аренда, оценка, инвестиционный консалтинг и наследственные операции в Измире и Эгейском регионе. Услуги в сфере недвижимости на основе данных, от и до.","zh":"在伊兹密尔和爱琴海地区的买卖、租赁、估价、投资顾问及遗产/继承过户业务。以数据为核心、端到端的房产服务。","ar":"بيع وشراء وتأجير وتقييم واستشارات استثمارية ومعاملات ميراث/انتقال في إزمير ومنطقة بحر إيجه. خدمات عقارية قائمة على البيانات ومن البداية إلى النهاية."},"Hizmetlerimiz — Emlak Danışmanlığı, Değerleme, Yatırım ve Miras İntikal · Meridyen Gayrimenkul":{"en":"Our Services — Real Estate Advisory, Valuation, Investment and Inheritance Transfer · Meridyen Gayrimenkul","ru":"Наши услуги — консультации по недвижимости, оценка, инвестиции и переход наследства · Meridyen Gayrimenkul","zh":"我们的服务 — 房产顾问、估价、投资及遗产继承过户 · Meridyen Gayrimenkul","ar":"خدماتنا — استشارات عقارية، تقييم، استثمار وانتقال الميراث · Meridyen Gayrimenkul"}};